// Países del mundo derivados del dataset CANÓNICO de beterano-data
// (datasets/geo/countries.json), vendorizado aquí como worldCountries.json.
// MISMA fuente que el marketplace: unifica el origen de países en todo el ecosistema.
// Para actualizar: copiar de nuevo datasets/geo/countries.json sobre worldCountries.json.
//
// Cada país: { code (ISO2), name (ES), nameEn (EN), region (continente) }.
import RAW from "./worldCountries.json";

// Continentes (campo `region` del dataset), en orden de presentación.
const CONTINENTS = [
  { id: "europe", label: "Europe", region: "Europe" },
  { id: "americas", label: "Americas", region: "Americas" },
  { id: "asia", label: "Asia", region: "Asia" },
  { id: "africa", label: "Africa", region: "Africa" },
  { id: "oceania", label: "Oceania", region: "Oceania" },
  { id: "antarctic", label: "Antarctic", region: "Antarctic" },
];

// El mapa venía usando el nombre en inglés; lo mantenemos como `name` (sin cambiar
// comportamiento) y guardamos el nombre ES en `nameEs` para lookups y futura i18n.
export const WORLD_COUNTRIES_BY_CONTINENT = CONTINENTS.map((continent) => ({
  id: continent.id,
  label: continent.label,
  countries: RAW
    .filter((country) => country.region === continent.region)
    .map((country) => ({
      code: country.code,
      name: country.nameEn || country.name,
      nameEs: country.name,
    }))
    .sort((a, b) => a.name.localeCompare(b.name, "en")),
}));

export const WORLD_COUNTRIES = WORLD_COUNTRIES_BY_CONTINENT.flatMap((group) =>
  group.countries.map((country) => ({
    ...country,
    continentId: group.id,
    continentLabel: group.label,
  })),
);

// Lookup por nombre tolerante: acepta el nombre en inglés o en español.
const COUNTRY_BY_NAME_MAP = new Map();
for (const country of WORLD_COUNTRIES) {
  COUNTRY_BY_NAME_MAP.set(country.name, country);
  if (country.nameEs) COUNTRY_BY_NAME_MAP.set(country.nameEs, country);
}
const COUNTRY_BY_CODE_MAP = new Map(WORLD_COUNTRIES.map((country) => [country.code, country]));

export const getWorldCountryByName = (countryName) => COUNTRY_BY_NAME_MAP.get(String(countryName || "").trim()) || null;
export const getWorldCountryByCode = (countryCode) =>
  COUNTRY_BY_CODE_MAP.get(String(countryCode || "").trim().toUpperCase()) || null;

export const countryCodeToFlagEmoji = (countryCode) => {
  const code = String(countryCode || "").trim().toUpperCase();
  if (!/^[A-Z]{2}$/.test(code)) return "";
  return String.fromCodePoint(...code.split("").map((char) => char.charCodeAt(0) + 127397));
};

export const getCountryFlagImageUrl = (countryCode, width = 20) => {
  const code = String(countryCode || "").trim().toLowerCase();
  if (!/^[a-z]{2}$/.test(code)) return "";
  const clampedWidth = Number.isFinite(width) ? Math.min(Math.max(Math.round(width), 12), 64) : 20;
  return `https://flagcdn.com/w${clampedWidth}/${code}.png`;
};
