import React, { useMemo } from "react";
import { getMapVehicleCategoryMeta } from "../../features/mapShell/vehicleCategories.js";
import { useChromeI18n } from "../../shared/i18n/i18n.jsx";

function getUniqueVehicleCategories(item, locale) {
  const raw = Array.isArray(item?.vehicleCategoryIds) ? item.vehicleCategoryIds : [];
  const seen = new Set();
  const values = [];

  for (const entry of raw) {
    const meta = getMapVehicleCategoryMeta(entry, locale);
    if (!meta || seen.has(meta.id)) continue;
    seen.add(meta.id);
    values.push(meta);
  }

  return values;
}

export function MapPlaceVehicleCategoryTags({
  item,
  className = "",
  includeLabel = false,
  max = 4,
}) {
  const { locale, t } = useChromeI18n();
  const categories = useMemo(() => getUniqueVehicleCategories(item, locale), [item, locale]);

  if (!categories.length) return null;

  const normalizedMax = Number.isFinite(Number(max)) ? Math.max(1, Number(max)) : categories.length;
  const visibleCategories = categories.slice(0, normalizedMax);
  const hiddenCount = categories.length - visibleCategories.length;
  const rootClass = className
    ? `map-vehicle-category-tags ${className}`
    : "map-vehicle-category-tags";

  return (
    <div className={rootClass} aria-label={t("common.vehicle", "Vehiculos")}>
      {includeLabel ? <span className="map-vehicle-category-tags__label">{t("common.vehicle", "Vehiculos")}</span> : null}
      <div className="map-vehicle-category-tags__list">
        {visibleCategories.map((entry) => (
          <span key={entry.id} className="map-vehicle-category-tag">
            <span aria-hidden="true">{entry.icon}</span>
            <span>{entry.label}</span>
          </span>
        ))}
        {hiddenCount > 0 ? (
          <span className="map-vehicle-category-tag map-vehicle-category-tag--muted">
            +{hiddenCount}
          </span>
        ) : null}
      </div>
    </div>
  );
}
