import { useEffect, useMemo, useRef, useState } from "react";
import { fetchMapPlaces } from "../../lib/mapShellApi.js";
import { MAP_BRAND_CATALOG } from "./brands.js";
import {
  createEmptySwapistaFilters,
  getSwapistaFieldOptions,
  isSwapistaTribe,
  normalizeSwapistaFieldState,
  SWAPISTA_FIELD_DEFS,
} from "./swapistas.js";
import { DEFAULT_MAP_TRIBE } from "./tribes.js";
import { matchShopCategory } from "./shopCategories.js";
import { MAP_VEHICLE_CATEGORIES, matchVehicleCategory } from "./vehicleCategories.js";
import { WORLD_CLASSICS_BRANDS, modelsForBrand } from "./worldClassicsCatalog.js";

function toStringArray(value) {
  if (Array.isArray(value)) {
    return value
      .map((entry) => (typeof entry === "string" ? entry.trim() : ""))
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return value
      .split(",")
      .map((entry) => entry.trim())
      .filter(Boolean);
  }

  return [];
}

function uniqueStrings(values) {
  const seen = new Set();
  const output = [];

  for (const value of values) {
    const trimmed = String(value || "").trim();
    if (!trimmed) continue;
    const key = trimmed.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    output.push(trimmed);
  }

  return output;
}

function normalizeTagValue(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const INVALID_BRAND_KEYS = new Set(["all", "todas", "todos", "alltodas", "alltodos"]);

function isValidBrandValue(value) {
  const key = String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "")
    .trim();
  if (!key) return false;
  return !INVALID_BRAND_KEYS.has(key);
}

function hasTagMatch(values, filterValue) {
  if (!filterValue) return true;
  const normalizedFilter = normalizeTagValue(filterValue);
  if (!normalizedFilter) return true;
  return values.some((value) => normalizeTagValue(value) === normalizedFilter);
}

function sortStrings(values) {
  return [...values].sort((a, b) => a.localeCompare(b));
}

function sortBrandOptions(values) {
  return [...values].sort((a, b) => a.value.localeCompare(b.value));
}

function firstStringValue(values) {
  for (const value of values) {
    const normalized = String(value || "").trim();
    if (normalized) return normalized;
  }
  return "";
}

function toObject(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return value;
}

function toFiniteNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function normalizeItem(item, index) {
  const point = item?.location?.point;
  if (!point || !Number.isFinite(point.lat) || !Number.isFinite(point.lng)) return null;

  const tagsInput = typeof item?.tags === "object" && item.tags && !Array.isArray(item.tags)
    ? item.tags
    : {};

  const categories = uniqueStrings([
    ...toStringArray(tagsInput.categories),
    ...toStringArray(tagsInput.category),
    ...toStringArray(tagsInput.vehicleCategories),
    ...toStringArray(tagsInput.vehicleCategory),
    ...toStringArray(tagsInput.types),
  ]);

  const brands = uniqueStrings(toStringArray(tagsInput.brands).filter(isValidBrandValue));
  const models = uniqueStrings(toStringArray(tagsInput.models));
  const professions = uniqueStrings(toStringArray(tagsInput.professions));
  const services = uniqueStrings(toStringArray(tagsInput.services));
  const rawShopCategories = uniqueStrings([
    ...toStringArray(tagsInput.shopCategories),
    ...toStringArray(tagsInput.shopCategory),
  ]);
  const images = uniqueStrings([
    ...toStringArray(item?.media?.images),
    ...toStringArray(item?.images),
  ]);
  const marketplaceInput = toObject(item?.marketplace);
  const logoUrl = firstStringValue([
    item?.logoUrl,
    item?.logo,
    item?.media?.logo,
    item?.media?.avatar,
    item?.company?.logo,
    item?.brand?.logo,
    item?.profile?.logo,
  ]);
  const marketplaceUrl = firstStringValue([marketplaceInput.url, marketplaceInput.marketplaceUrl]);
  const marketplaceProductCount = toFiniteNumber(
    marketplaceInput.productCount ?? marketplaceInput.productsCount,
  );
  const marketplaceHasProducts = Boolean(
    marketplaceInput.hasProducts === true ||
      (typeof marketplaceProductCount === "number" && marketplaceProductCount > 0) ||
      marketplaceUrl,
  );
  const swapistaTags = SWAPISTA_FIELD_DEFS.reduce((accumulator, field) => {
    const rawValue = tagsInput[field.id];
    accumulator[field.id] = field.selectionMode === "single"
      ? firstStringValue([rawValue])
      : uniqueStrings(toStringArray(rawValue));
    return accumulator;
  }, {});

  return {
    id: String(item.id || item.slug || `${item.name || "place"}-${index}`),
    name: item.name || "Sin nombre",
    tribe: item.tribe || DEFAULT_MAP_TRIBE,
    city: item.city || "",
    country: item.country || "",
    countryCode: item.countryCode || "",
    region: item.region || "",
    address: item.address || "",
    coverage: item.coverage || "",
    contactName: item.contactName || "",
    description: item.description || "",
    shortDescription: item.shortDescription || item.description || "",
    longDescription: item.longDescription || item.description || "",
    published: item?.published !== false,
    metadata: toObject(item?.metadata),
    images,
    logoUrl,
    flags: toObject(item?.flags),
    vehicleCategoryIds: uniqueStrings(categories.map((value) => matchVehicleCategory(value)).filter(Boolean)),
    shopCategoryIds: uniqueStrings(
      [...rawShopCategories, ...categories, ...services].map((value) => matchShopCategory(value)).filter(Boolean),
    ),
    tags: {
      categories,
      brands,
      models,
      professions,
      services,
      shopCategories: rawShopCategories,
      ...swapistaTags,
    },
    location: {
      point: {
        lat: Number(point.lat),
        lng: Number(point.lng),
      },
      precision: item?.location?.precision || "point",
      bufferKm: Number(item?.location?.bufferKm) || null,
    },
    links: {
      website: item?.links?.website || "",
      instagram: item?.links?.instagram || "",
      facebook: item?.links?.facebook || "",
      youtube: item?.links?.youtube || "",
      linkedin: item?.links?.linkedin || "",
      tiktok: item?.links?.tiktok || "",
      whatsapp: item?.links?.whatsapp || "",
      email: item?.links?.email || "",
      phone: item?.links?.phone || "",
    },
    marketplace: {
      hasProducts: marketplaceHasProducts,
      productCount: marketplaceProductCount,
      url: marketplaceUrl,
      shopId: firstStringValue([marketplaceInput.shopId, marketplaceInput.id]),
      shopSlug: firstStringValue([marketplaceInput.shopSlug, marketplaceInput.slug]),
    },
  };
}

function matchesSearch(item, search) {
  if (!search) return true;
  const normalizedSearch = normalizeTagValue(search);
  if (!normalizedSearch) return true;

  const tagValues = Object.values(item.tags || {}).flatMap((entry) =>
    Array.isArray(entry) ? entry : entry ? [entry] : []
  );

  const haystack = normalizeTagValue([
    item.name,
    item.city,
    item.country,
    item.region,
    item.address,
    item.coverage,
    item.contactName,
    item.description,
    item.shortDescription,
    item.longDescription,
    ...tagValues,
  ]
    .filter(Boolean)
    .join(" "));

  return haystack.includes(normalizedSearch);
}

function applySwapistaFilters(item, tribeFilters) {
  return SWAPISTA_FIELD_DEFS.every((field) => {
    const filterValue = tribeFilters[field.id];
    if (field.selectionMode === "single") {
      if (!filterValue) return true;
      return hasTagMatch([item.tags?.[field.id]].filter(Boolean), filterValue);
    }

    const selectedValues = Array.isArray(filterValue) ? filterValue : [];
    if (!selectedValues.length) return true;
    const itemValues = Array.isArray(item.tags?.[field.id]) ? item.tags[field.id] : [];
    return selectedValues.every((entry) => hasTagMatch(itemValues, entry));
  });
}

function buildSwapistaOptionsByField(items, tribeFilters) {
  return SWAPISTA_FIELD_DEFS.reduce((accumulator, field) => {
    const discoveredValues = items.flatMap((item) => {
      const rawValue = item.tags?.[field.id];
      if (field.selectionMode === "single") return rawValue ? [rawValue] : [];
      return Array.isArray(rawValue) ? rawValue : [];
    });

    const selectedValues = field.selectionMode === "single"
      ? [tribeFilters[field.id]].filter(Boolean)
      : Array.isArray(tribeFilters[field.id])
        ? tribeFilters[field.id]
        : [];

    accumulator[field.id] = getSwapistaFieldOptions(field.id, [...discoveredValues, ...selectedValues]);
    return accumulator;
  }, {});
}

export function useMapShellState(enabled, preferredCountry = "", brandCatalog = MAP_BRAND_CATALOG) {
  const [tribe, setTribe] = useState(DEFAULT_MAP_TRIBE);
  const [search, setSearch] = useState("");
  const [country, setCountry] = useState("");
  const [profession, setProfession] = useState("");
  const [shopCategory, setShopCategory] = useState("");
  const [vehicleCategory, setVehicleCategory] = useState("");
  const [brand, setBrand] = useState("");
  const [model, setModel] = useState("");
  const [tribeFilters, setTribeFilters] = useState(() => createEmptySwapistaFilters());
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [selectedItemId, setSelectedItemId] = useState(null);
  const [refreshTick, setRefreshTick] = useState(0);
  const autoCountryPrefillRef = useRef(false);
  const preferredCountryNormalized = useMemo(() => String(preferredCountry || "").trim(), [preferredCountry]);

  useEffect(() => {
    if (tribe !== "services" && profession) {
      setProfession("");
    }
    if (tribe !== "shops" && shopCategory) {
      setShopCategory("");
    }
    if (isSwapistaTribe(tribe)) {
      if (vehicleCategory) setVehicleCategory("");
      if (brand) setBrand("");
      if (model) setModel("");
    }
  }, [tribe, profession, shopCategory, vehicleCategory, brand, model]);

  useEffect(() => {
    if (!enabled) {
      autoCountryPrefillRef.current = false;
      return;
    }

    if (autoCountryPrefillRef.current) return;
    if (!preferredCountryNormalized) return;

    if (country) {
      autoCountryPrefillRef.current = true;
      return;
    }

    setCountry(preferredCountryNormalized);
    autoCountryPrefillRef.current = true;
  }, [enabled, preferredCountryNormalized, country]);

  useEffect(() => {
    if (!enabled) return;

    setLoading(true);
    setError("");
    const controller = new AbortController();

    fetchMapPlaces(
      {
        tribe,
        profession,
        limit: 500,
      },
      { signal: controller.signal },
    )
      .then((result) => {
        setItems(result.items.map((item, index) => normalizeItem(item, index)).filter(Boolean));
      })
      .catch((err) => {
        if (controller.signal.aborted) return;
        setItems([]);
        setError(err instanceof Error ? err.message : "No se pudieron cargar los lugares.");
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      });

    return () => controller.abort();
  }, [enabled, tribe, profession, refreshTick]);

  const countries = useMemo(() => {
    return Array.from(new Set(items.map((item) => item.country).filter(Boolean))).sort((a, b) =>
      a.localeCompare(b),
    );
  }, [items]);

  const countryAndSearchItems = useMemo(() => {
    return items.filter((item) => {
      if (country && item.country !== country) return false;
      return matchesSearch(item, search);
    });
  }, [items, country, search]);

  const vehicleCategoryCounts = useMemo(() => {
    if (isSwapistaTribe(tribe)) {
      return Object.fromEntries(MAP_VEHICLE_CATEGORIES.map((entry) => [entry.id, 0]));
    }

    const counts = Object.fromEntries(MAP_VEHICLE_CATEGORIES.map((entry) => [entry.id, 0]));
    for (const item of countryAndSearchItems) {
      for (const categoryId of item.vehicleCategoryIds) {
        if (counts[categoryId] != null) {
          counts[categoryId] += 1;
        }
      }
    }
    return counts;
  }, [countryAndSearchItems, tribe]);

  const categoryFilteredItems = useMemo(() => {
    if (isSwapistaTribe(tribe) || !vehicleCategory) return countryAndSearchItems;
    return countryAndSearchItems.filter((item) => item.vehicleCategoryIds.includes(vehicleCategory));
  }, [countryAndSearchItems, tribe, vehicleCategory]);

  const shopCategoryFilteredItems = useMemo(() => {
    if (tribe !== "shops" || !shopCategory) return categoryFilteredItems;
    return categoryFilteredItems.filter((item) => item.shopCategoryIds.includes(shopCategory));
  }, [categoryFilteredItems, shopCategory, tribe]);

  const availableBrands = useMemo(() => {
    if (isSwapistaTribe(tribe)) return [];

    // Base: catálogo canónico (world_classics de beterano-data). Se completa con las
    // marcas que declaren los pines (por si alguna no estuviera en el catálogo).
    const brandMap = new Map(
      WORLD_CLASSICS_BRANDS.map((entry) => [entry, { value: entry, vehicleCategoryIds: [] }]),
    );

    for (const item of shopCategoryFilteredItems) {
      for (const entry of item.tags.brands) {
        const current = brandMap.get(entry) || { value: entry, vehicleCategoryIds: [] };
        const nextCategoryIds = sortStrings(
          uniqueStrings([...current.vehicleCategoryIds, ...item.vehicleCategoryIds]),
        );
        brandMap.set(entry, {
          value: entry,
          vehicleCategoryIds: nextCategoryIds,
        });
      }
    }

    return sortBrandOptions(Array.from(brandMap.values()));
  }, [shopCategoryFilteredItems, tribe]);

  const availableBrandValues = useMemo(
    () => availableBrands.map((entry) => entry.value),
    [availableBrands],
  );

  useEffect(() => {
    if (brand && !hasTagMatch(availableBrandValues, brand)) {
      setBrand("");
    }
  }, [brand, availableBrandValues]);

  const brandFilteredItems = useMemo(() => {
    if (isSwapistaTribe(tribe) || !brand) return shopCategoryFilteredItems;
    return shopCategoryFilteredItems.filter((item) => hasTagMatch(item.tags.brands, brand));
  }, [shopCategoryFilteredItems, brand, tribe]);

  const availableModels = useMemo(() => {
    if (isSwapistaTribe(tribe)) return [];
    // Modelos canónicos de la marca elegida (world_classics), no solo los de los pines.
    return modelsForBrand(brand);
  }, [brand, tribe]);

  const availableServices = useMemo(() => {
    return sortStrings(uniqueStrings(items.flatMap((item) => item.tags.services)));
  }, [items]);

  const availableSwapistaOptions = useMemo(
    () =>
      isSwapistaTribe(tribe)
        ? buildSwapistaOptionsByField(countryAndSearchItems, tribeFilters)
        : buildSwapistaOptionsByField([], tribeFilters),
    [countryAndSearchItems, tribe, tribeFilters],
  );

  useEffect(() => {
    if (model && !hasTagMatch(availableModels, model)) {
      setModel("");
    }
  }, [model, availableModels]);

  const legacyFilteredItems = useMemo(() => {
    const nextItems = isSwapistaTribe(tribe) ? countryAndSearchItems : brandFilteredItems;
    if (isSwapistaTribe(tribe) || !model) return nextItems;
    return nextItems.filter((item) => hasTagMatch(item.tags.models, model));
  }, [brandFilteredItems, countryAndSearchItems, model, tribe]);

  const filteredItems = useMemo(() => {
    if (isSwapistaTribe(tribe)) {
      return countryAndSearchItems.filter((item) => applySwapistaFilters(item, tribeFilters));
    }
    return legacyFilteredItems;
  }, [countryAndSearchItems, legacyFilteredItems, tribe, tribeFilters]);

  useEffect(() => {
    if (!enabled) return;
    if (!filteredItems.length) {
      setSelectedItemId(null);
      return;
    }
    if (selectedItemId && !filteredItems.some((item) => item.id === selectedItemId)) {
      setSelectedItemId(null);
    }
  }, [enabled, filteredItems, selectedItemId]);

  const selectedItem = useMemo(
    () => filteredItems.find((item) => item.id === selectedItemId) || null,
    [filteredItems, selectedItemId],
  );

  const upsertItem = (nextItem) => {
    if (!nextItem?.id) return;
    setItems((current) => {
      const normalizedNext = normalizeItem(nextItem, 0);
      if (!normalizedNext) return current;
      const index = current.findIndex((item) => item.id === normalizedNext.id);
      if (index === -1) return [normalizedNext, ...current];
      return current.map((item) => (item.id === normalizedNext.id ? normalizedNext : item));
    });
  };

  const removeItem = (itemId) => {
    const normalizedId = String(itemId || "").trim();
    if (!normalizedId) return;
    setItems((current) => current.filter((item) => item.id !== normalizedId));
  };

  const setTribeFilter = (fieldId, value) => {
    setTribeFilters((current) => ({
      ...current,
      [fieldId]: normalizeSwapistaFieldState(fieldId, value),
    }));
  };

  const clearTribeFilters = () => {
    setTribeFilters(createEmptySwapistaFilters());
  };

  return {
    tribe,
    setTribe,
    search,
    setSearch,
    country,
    setCountry,
    profession,
    setProfession,
    shopCategory,
    setShopCategory,
    vehicleCategory,
    setVehicleCategory,
    brand,
    setBrand,
    model,
    setModel,
    tribeFilters,
    setTribeFilter,
    clearTribeFilters,
    availableBrands,
    availableModels,
    availableServices,
    availableSwapistaOptions,
    vehicleCategoryCounts,
    items,
    filteredItems,
    countries,
    selectedItemId,
    setSelectedItemId,
    selectedItem,
    loading,
    error,
    refresh: () => setRefreshTick((value) => value + 1),
    upsertItem,
    removeItem,
    hostPayload: {
      tribe,
      search,
      country,
      profession,
      shopCategory,
      vehicleCategory,
      brand,
      model,
      tribeFilters,
      selectedItemId,
    },
  };
}
