const ENV = import.meta.env;
const LOCAL_HOSTS = new Set(["", "localhost", "127.0.0.1", "::1"]);
const PREVIEW_ACCESS_GATE_CODE = "__BTR_PREVIEW_ACCESS_GATE__";
const PREVIEW_ACCESS_GATE_MESSAGES = {
  es: "Para ver este contenido debes registrarte y activar una suscripcion.",
  en: "Register your account and activate a subscription to view this content.",
  de: "Registriere dein Konto und aktiviere ein Abo, um diesen Inhalt zu sehen.",
  fr: "Cree ton compte et active un abonnement pour voir ce contenu.",
  it: "Crea il tuo account e attiva un abbonamento per vedere questo contenuto.",
  tr: "Bu icerigi gormek icin hesabini olustur ve bir abonelik etkinlestir.",
  nl: "Maak je account aan en activeer een abonnement om deze inhoud te bekijken.",
  pl: "Aby zobaczyc te tresci, zaloz konto i aktywuj subskrypcje.",
  hr: "Za pregled ovog sadrzaja registriraj racun i aktiviraj pretplatu.",
  ja: "このコンテンツを見るには、登録してサブスクリプションを有効にする必要があります。",
  zh: "要查看此内容，你需要先注册并启用订阅。",
  ar: "لعرض هذا المحتوى يجب عليك التسجيل وتفعيل الاشتراك.",
};

const shellHost = typeof window !== "undefined" ? String(window.location.hostname || "").toLowerCase() : "";
const hasExplicitCoreApiBaseUrl = Object.prototype.hasOwnProperty.call(ENV, "VITE_CORE_API_BASE_URL");
const explicitCoreApiBaseUrl = hasExplicitCoreApiBaseUrl ? String(ENV.VITE_CORE_API_BASE_URL || "").trim() : "";

export const CORE_API_BASE_URL = explicitCoreApiBaseUrl || (LOCAL_HOSTS.has(shellHost) ? "/__core" : "");
export const HAS_CORE_API_BASE_URL = Boolean(CORE_API_BASE_URL);
export const MISSING_CORE_API_MESSAGE = PREVIEW_ACCESS_GATE_CODE;

function normalizeLocale(value) {
  const normalized = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/_/g, "-");
  return normalized.split("-")[0] || "en";
}

export function isPreviewAccessGateMessage(value) {
  return String(value || "").trim() === PREVIEW_ACCESS_GATE_CODE;
}

export function resolveCoreApiUiMessage(message, locale = "en") {
  if (!isPreviewAccessGateMessage(message)) return message;
  const normalizedLocale = normalizeLocale(locale);
  return PREVIEW_ACCESS_GATE_MESSAGES[normalizedLocale] || PREVIEW_ACCESS_GATE_MESSAGES.en;
}
