import React, { useMemo } from "react";
import {
  SWAPISTA_DETAIL_FIELD_IDS,
  SWAPISTA_FIELD_BY_ID,
  SWAPISTA_SUMMARY_FIELD_IDS,
  getSwapistaValueLabel,
  isSwapistaTribe,
} from "../../features/mapShell/swapistas.js";
import { MapPlaceTagGroup } from "./MapPlaceTagGroup.jsx";

function buildGroups(item, fieldIds) {
  const tags = item?.tags && typeof item.tags === "object" ? item.tags : {};

  return fieldIds
    .map((fieldId) => {
      const field = SWAPISTA_FIELD_BY_ID.get(fieldId);
      if (!field) return null;

      const rawValue = tags[fieldId];
      const values = field.selectionMode === "single"
        ? [String(rawValue || "").trim()].filter(Boolean)
        : (Array.isArray(rawValue) ? rawValue : []).filter(Boolean);
      const displayValues = values.map((value) => getSwapistaValueLabel(fieldId, value)).filter(Boolean);

      if (!displayValues.length) return null;
      return {
        id: fieldId,
        label: field.label,
        values: displayValues,
      };
    })
    .filter(Boolean);
}

export function MapPlaceSwapistaTags({
  item,
  mode = "summary",
  className = "",
  includeLabels = false,
  max = 4,
}) {
  const fieldIds = mode === "detail" ? SWAPISTA_DETAIL_FIELD_IDS : SWAPISTA_SUMMARY_FIELD_IDS;
  const groups = useMemo(() => buildGroups(item, fieldIds), [fieldIds, item]);

  if (!isSwapistaTribe(item?.tribe)) return null;
  if (!groups.length) return null;

  return (
    <div className={className ? `map-swapista-tags ${className}` : "map-swapista-tags"}>
      {groups.map((group) => (
        <MapPlaceTagGroup
          key={group.id}
          label={group.label}
          values={group.values}
          includeLabel={includeLabels}
          max={max}
          className={mode === "detail" ? "map-tag-group--detail" : "map-tag-group--summary"}
        />
      ))}
    </div>
  );
}
