import { fetchCoreJson } from "./coreApi.js";

function uniqueSorted(values) {
  return [...new Set(values.map((value) => String(value || "").trim()).filter(Boolean))].sort((a, b) =>
    a.localeCompare(b),
  );
}

export async function fetchVehicleMakeNames() {
  const payload = await fetchCoreJson("/v1/catalog/vehicle-makes");
  const items = Array.isArray(payload?.items) ? payload.items : [];
  return uniqueSorted(items.map((item) => item?.name));
}
