function isServiceLikeTribe(value) {
  return normalizeMapTribeId(value) === "services";
}

function isShopLikeTribe(value) {
  return normalizeMapTribeId(value) === "shops";
}

function isSwapistaEditorTribe(value) {
  return isSwapistaTribe(normalizeMapTribeId(value));
}

function normalizeEditorTribe(value, fallback = "restauradores") {
  return normalizeMapTribeId(value) || fallback;
}

function collectEditorContentTags(item) {
  const normalizedTribe = normalizeEditorTribe(item?.tribe);

  if (isServiceLikeTribe(normalizedTribe)) {
    return uniqueStrings([...(item?.tags?.professions || []), ...(item?.tags?.services || [])]);
  }

  if (isShopLikeTribe(normalizedTribe)) {
    return uniqueStrings([
      ...(item?.shopCategoryIds || []),
      ...((item?.tags?.shopCategories || []).map((entry) => matchShopCategory(entry)).filter(Boolean)),
      ...((item?.tags?.categories || []).map((entry) => matchShopCategory(entry)).filter(Boolean)),
      ...((item?.tags?.services || []).map((entry) => matchShopCategory(entry)).filter(Boolean)),
    ]);
  }

  return uniqueStrings([...(item?.tags?.services || [])]);
}

function readObject(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return value;
}

function parseCsv(value) {
  return String(value || "")
    .split(",")
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function toMultiValues(value) {
  if (Array.isArray(value)) {
    return value.map((entry) => String(entry || "").trim()).filter(Boolean);
  }
  return parseCsv(value);
}

function uniqueStrings(values) {
  const seen = new Set();
  const output = [];
  for (const value of values) {
    const normalized = String(value || "").trim();
    if (!normalized) continue;
    const key = normalized.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    output.push(normalized);
  }
  return output;
}

function sortStrings(values) {
  return [...values].sort((left, right) => left.localeCompare(right));
}

function toOptionalTrimmed(value) {
  const normalized = String(value || "").trim();
  return normalized ? normalized : undefined;
}

function toDraftCoordinate(value) {
  const normalized = Number(value);
  return Number.isFinite(normalized) ? normalized.toFixed(6) : "";
}

function validateEditorDraft(draft) {
  if (!draft.name.trim()) return "El nombre es obligatorio.";
  if (!draft.tribe.trim()) return "La tribu es obligatoria.";
  if (isSwapistaEditorTribe(draft.tribe) && !draft.country.trim()) {
    return "El pais es obligatorio para publicar un swapista.";
  }

  const lat = Number(draft.lat);
  if (!Number.isFinite(lat) || lat < -90 || lat > 90) {
    return "La latitud debe estar entre -90 y 90.";
  }

  const lng = Number(draft.lng);
  if (!Number.isFinite(lng) || lng < -180 || lng > 180) {
    return "La longitud debe estar entre -180 y 180.";
  }

  if (draft.precision === "buffer") {
    const bufferKm = Number(draft.bufferKm);
    if (!Number.isFinite(bufferKm) || bufferKm <= 0) {
      return "El radio debe ser mayor que 0 km cuando la precision es buffer.";
    }
  }

  if (
    isSwapistaEditorTribe(draft.tribe) &&
    !draft.swapCategories.length &&
    !draft.swapTypes.length
  ) {
    return "Selecciona al menos una categoria o un tipo para el swapista.";
  }

  return "";
}

function createEditorDraft(item) {
  const metadata = readObject(item?.metadata);
  const swapistaState = item?.swapista || readSwapistaState(metadata);
  return {
    name: item?.name || "",
    tribe: normalizeEditorTribe(item?.tribe),
    countryCode: item?.countryCode || "",
    country: item?.country || "",
    region: item?.region || metadata.region || metadata.state || metadata.province || "",
    city: item?.city || "",
    address: item?.address || metadata.address || "",
    postalCode: item?.postalCode || metadata.postalCode || metadata.postal_code || metadata.zipCode || metadata.zip || "",
    coverage: item?.coverage || metadata.coverage || metadata.zonaCobertura || "",
    lat: toDraftCoordinate(item?.location?.point?.lat),
    lng: toDraftCoordinate(item?.location?.point?.lng),
    precision: item?.location?.precision || "point",
    bufferKm:
      item?.location?.bufferKm != null && Number.isFinite(Number(item.location.bufferKm))
        ? String(item.location.bufferKm)
        : "",
    shortDescription: item?.shortDescription || metadata.shortDescription || metadata.short_description || item?.description || "",
    longDescription: item?.longDescription || metadata.longDescription || metadata.long_description || item?.description || "",
    website: item?.links?.website || "",
    instagram: item?.links?.instagram || "",
    facebook: item?.links?.facebook || "",
    youtube: item?.links?.youtube || "",
    linkedin: item?.links?.linkedin || "",
    tiktok: item?.links?.tiktok || metadata.tiktok || metadata.tiktokUrl || "",
    whatsapp: item?.links?.whatsapp || "",
    email: item?.links?.email || "",
    phone: item?.links?.phone || "",
    contactName: item?.contactName || metadata.contactName || metadata.contactoPrincipal || "",
    dataSource: metadata.dataSource || metadata.fuenteDatos || "",
    internalNotes: metadata.internalNotes || metadata.notasInternas || "",
    verified: item?.flags?.verified === true,
    featured: item?.flags?.featured === true,
    categories: [...(item?.tags?.categories || [])],
    brands: [...(item?.tags?.brands || [])],
    models: (item?.tags?.models || []).join(", "),
    contentTags: collectEditorContentTags(item),
    ...swapistaState,
    published: item?.published !== false,
  };
}

