function writeStringMetadata(next, primaryKey, value, aliases = []) {
  const normalized = toOptionalTrimmed(value);
  if (normalized) {
    next[primaryKey] = normalized;
    return;
  }

  delete next[primaryKey];
  for (const alias of aliases) {
    delete next[alias];
  }
}

function writeBooleanMetadata(next, primaryKey, value, aliases = []) {
  if (value === true || value === false) {
    next[primaryKey] = value;
    return;
  }

  delete next[primaryKey];
  for (const alias of aliases) {
    delete next[alias];
  }
}

function buildMetadataPatch(item, draft) {
  const next = { ...readObject(item?.metadata) };
  const categories = toMultiValues(draft.categories);
  const brands = toMultiValues(draft.brands);
  const models = parseCsv(draft.models);
  const contentTags = toMultiValues(draft.contentTags);
  const normalizedTribe = normalizeEditorTribe(draft.tribe);
  const professions = contentTags.filter((entry) => OFFICIAL_PROFESSION_IDS.has(String(entry || "").trim()));
  const shopCategories = uniqueStrings(
    contentTags.map((entry) => matchShopCategory(entry)).filter((entry) => OFFICIAL_SHOP_CATEGORY_IDS.has(entry)),
  );
  const services = contentTags;
  const swapistaEditor = isSwapistaEditorTribe(normalizedTribe);

  if (!swapistaEditor && categories.length) {
    next.categories = categories;
    next.category = categories[0];
    next.vehicleCategories = categories;
    next.vehicleCategory = categories[0];
  } else {
    delete next.categories;
    delete next.category;
    delete next.vehicleCategories;
    delete next.vehicleCategory;
  }

  if (!swapistaEditor && brands.length) next.brands = brands;
  else delete next.brands;

  if (!swapistaEditor && models.length) next.models = models;
  else delete next.models;

  if (!swapistaEditor && isServiceLikeTribe(normalizedTribe) && professions.length) {
    next.professions = professions;
    next.profession = professions[0];
  } else {
    delete next.professions;
    delete next.profession;
  }

  if (!swapistaEditor && isShopLikeTribe(normalizedTribe) && shopCategories.length) {
    next.shopCategories = shopCategories;
    next.shopCategory = shopCategories[0];
  } else {
    delete next.shopCategories;
    delete next.shopCategory;
  }

  if (!swapistaEditor && !isShopLikeTribe(normalizedTribe) && services.length) next.services = services;
  else delete next.services;

  writeStringMetadata(next, "postalCode", draft.postalCode, ["postal_code", "zipCode", "zip_code", "zip"]);
  writeStringMetadata(next, "region", draft.region, ["state", "province"]);
  writeStringMetadata(next, "address", draft.address);
  writeStringMetadata(next, "coverage", draft.coverage, ["zonaCobertura"]);
  writeStringMetadata(next, "contactName", draft.contactName, ["contactoPrincipal"]);
  writeStringMetadata(next, "facebook", draft.facebook, ["facebookUrl", "facebook_url"]);
  writeStringMetadata(next, "youtube", draft.youtube, ["youtubeUrl", "youtube_url"]);
  writeStringMetadata(next, "linkedin", draft.linkedin, ["linkedinUrl", "linkedin_url"]);
  writeStringMetadata(next, "tiktok", draft.tiktok, ["tiktokUrl", "tiktok_url"]);
  writeStringMetadata(next, "whatsapp", draft.whatsapp, ["whatsappUrl", "whatsapp_url", "whatsApp"]);
  writeStringMetadata(next, "dataSource", draft.dataSource, ["fuenteDatos"]);
  writeStringMetadata(next, "internalNotes", draft.internalNotes, ["notasInternas"]);
  writeStringMetadata(next, "shortDescription", draft.shortDescription, ["short_description"]);
  writeStringMetadata(next, "longDescription", draft.longDescription, ["long_description"]);
  writeBooleanMetadata(next, "verified", draft.verified);
  writeBooleanMetadata(next, "featured", draft.featured);

  return swapistaEditor
    ? applySwapistaStateToMetadata(next, draft)
    : clearSwapistaMetadata(next);
}

function getDraftPoint(draft) {
  const lat = Number(draft?.lat);
  const lng = Number(draft?.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return { lat, lng };
}

function buildCreatePayload(draft) {
  const normalizedTribe = normalizeEditorTribe(draft.tribe);
  const description = toOptionalTrimmed(draft.shortDescription) || toOptionalTrimmed(draft.longDescription);
  const payload = {
    name: draft.name.trim(),
    tribe: normalizedTribe,
    countryCode: toOptionalTrimmed(draft.countryCode)?.toUpperCase(),
    country: toOptionalTrimmed(draft.country),
    city: toOptionalTrimmed(draft.city),
    lat: Number(draft.lat),
    lng: Number(draft.lng),
    precision: toOptionalTrimmed(draft.precision) || "point",
    description,
    website: toOptionalTrimmed(draft.website),
    instagram: toOptionalTrimmed(draft.instagram),
    email: toOptionalTrimmed(draft.email),
    phone: toOptionalTrimmed(draft.phone),
    published: Boolean(draft.published),
    metadata: buildMetadataPatch(null, draft),
    source: "SUPERADMIN_SEED",
  };

  if (draft.precision === "buffer") {
    payload.bufferKm = Number(draft.bufferKm || 0);
  }

  return payload;
}

function buildUpdatePayload(item, draft) {
  const normalizedTribe = normalizeEditorTribe(draft.tribe);
  const description = toOptionalTrimmed(draft.shortDescription) || toOptionalTrimmed(draft.longDescription);
  const payload = {
    name: draft.name.trim(),
    tribe: normalizedTribe,
    countryCode: toOptionalTrimmed(draft.countryCode)?.toUpperCase(),
    country: toOptionalTrimmed(draft.country),
    city: toOptionalTrimmed(draft.city),
    lat: Number(draft.lat),
    lng: Number(draft.lng),
    precision: toOptionalTrimmed(draft.precision) || "point",
    description,
    website: toOptionalTrimmed(draft.website),
    instagram: toOptionalTrimmed(draft.instagram),
    email: toOptionalTrimmed(draft.email),
    phone: toOptionalTrimmed(draft.phone),
    published: Boolean(draft.published),
    metadata: buildMetadataPatch(item, draft),
  };

  if (draft.precision === "buffer") {
    payload.bufferKm = Number(draft.bufferKm || 0);
  } else {
    payload.bufferKm = 0;
  }

  return payload;
}

function normalizeExternalUrl(value) {
  if (!value) return "";
  const raw = String(value).trim();
  if (!raw) return "";
  if (/^(https?:|mailto:|tel:)/i.test(raw)) return raw;
  return `https://${raw}`;
}

function normalizeWhatsappHref(value) {
  if (!value) return "";
  const raw = String(value).trim();
  if (!raw) return "";
  if (/^(https?:)/i.test(raw)) return raw;
  const digits = raw.replace(/[^\d]/g, "");
  if (!digits) return "";
  return `https://wa.me/${digits}`;
}

