function getMarkerIcon(tribeId) {
  const tribe = getMapTribeMeta(tribeId);
  const cacheKey = `${tribe.id}-${tribe.iconId || tribe.id}-${tribe.color}`;
  if (markerIconCache.has(cacheKey)) return markerIconCache.get(cacheKey);

  const icon = L.divIcon({
    className: "tribe-map-marker",
    html: `
      <span class="tribe-map-marker__bubble" style="--tribe-color: ${tribe.color};">
        <span class="tribe-map-marker__glyph">${getTribeIconSvgMarkup(tribe.iconId || tribe.id, { size: 14 })}</span>
      </span>
    `,
    iconSize: [34, 42],
    iconAnchor: [17, 42],
    popupAnchor: [0, -32],
  });

  markerIconCache.set(cacheKey, icon);
  return icon;
}

async function resolveCountryViewport(countryName, countryCode, signal) {
  const normalizedName = String(countryName || "").trim();
  const normalizedCode = String(countryCode || "").trim().toLowerCase();
  if (!normalizedName) return null;

  const cacheKey = `${normalizedCode}:${normalizedName}`;
  if (countryViewportCache.has(cacheKey)) {
    return countryViewportCache.get(cacheKey);
  }

  const params = new URLSearchParams({
    format: "jsonv2",
    limit: "1",
    featuretype: "country",
    q: normalizedName,
  });
  if (/^[a-z]{2}$/.test(normalizedCode)) {
    params.set("countrycodes", normalizedCode);
  }

  const response = await fetch(`https://nominatim.openstreetmap.org/search?${params.toString()}`, {
    signal,
    headers: { Accept: "application/json" },
  });
  if (!response.ok) {
    throw new Error(`Nominatim HTTP ${response.status}`);
  }

  const payload = await response.json().catch(() => []);
  const first = Array.isArray(payload) ? payload[0] : null;
  if (!first) {
    countryViewportCache.set(cacheKey, null);
    return null;
  }

  const bounding = Array.isArray(first.boundingbox) ? first.boundingbox.map(Number) : [];
  const hasBounds = bounding.length === 4 && bounding.every((value) => Number.isFinite(value));
  if (hasBounds) {
    const viewport = {
      bounds: [
        [bounding[0], bounding[2]],
        [bounding[1], bounding[3]],
      ],
    };
    countryViewportCache.set(cacheKey, viewport);
    return viewport;
  }

  const lat = Number(first.lat);
  const lng = Number(first.lon);
  if (Number.isFinite(lat) && Number.isFinite(lng)) {
    const viewport = { center: [lat, lng], zoom: 5 };
    countryViewportCache.set(cacheKey, viewport);
    return viewport;
  }

  countryViewportCache.set(cacheKey, null);
  return null;
}

// Builds Leaflet fitBounds padding. When `insets` are given the padding becomes
// asymmetric, so the fitted content lands in the visible gap (e.g. above the mobile
// results panel) instead of being centered behind the overlays.
function resolveFitPadding(padding, insets) {
  const baseX = Array.isArray(padding) ? padding[0] : padding;
  const baseY = Array.isArray(padding) ? padding[1] : padding;
  if (!insets) return { padding: [baseX, baseY] };
  const { top = 0, bottom = 0, left = 0, right = 0 } = insets;
  return {
    paddingTopLeft: [baseX + left, baseY + top],
    paddingBottomRight: [baseX + right, baseY + bottom],
  };
}

function focusMapViewport(map, viewport, { padding = [42, 42], maxZoom = 6, insets = null } = {}) {
  if (!map || !viewport) return;

  if (viewport.bounds) {
    map.fitBounds(viewport.bounds, { ...resolveFitPadding(padding, insets), maxZoom });
    return;
  }

  if (viewport.center) {
    map.flyTo(viewport.center, viewport.zoom || maxZoom, { animate: true, duration: 0.35 });
  }
}

function collectMapLinks(item) {
  const socialLinks = MAP_LINK_DEFS.map((entry) => ({
    ...entry,
    href: normalizeExternalUrl(item?.links?.[entry.key] || ""),
  })).filter((entry) => entry.href);

  const whatsappHref = normalizeWhatsappHref(item?.links?.whatsapp || "");
  if (whatsappHref) {
    socialLinks.push({ key: "whatsapp", label: "WhatsApp", icon: MessageCircle, href: whatsappHref });
  }

  const email = String(item?.links?.email || "").trim();
  const phone = String(item?.links?.phone || "").trim();

  if (email) {
    socialLinks.push({ key: "email", label: "Email", icon: Mail, href: `mailto:${email}` });
  }

  if (phone) {
    socialLinks.push({
      key: "phone",
      label: "Telefono",
      icon: Phone,
      href: `tel:${phone.replace(/\s+/g, "")}`,
    });
  }

  return socialLinks;
}

function resolveMarketplaceTarget(item) {
  const marketplace = item?.marketplace || {};
  const hasProducts = Boolean(
    marketplace.hasProducts === true ||
      (Number.isFinite(Number(marketplace.productCount)) && Number(marketplace.productCount) > 0) ||
      String(marketplace.url || "").trim(),
  );
  if (!hasProducts) return null;

  const href = normalizeExternalUrl(marketplace.url || "");
  if (href) {
    return { href, label: "Marketplace" };
  }

  return { href: "", label: "Marketplace" };
}

function navigateMarketplaceFromMapItem(item) {
  const payload = {
    itemId: item?.id || null,
    shopId: item?.marketplace?.shopId || null,
    shopSlug: item?.marketplace?.shopSlug || null,
    name: item?.name || null,
  };
  try {
    window.localStorage?.setItem("btr_marketplace_focus_store_v1", JSON.stringify(payload));
  } catch {
    // noop
  }

  const shell = window.BTR_CHROME_SHELL;
  if (shell && typeof shell.navigate === "function") {
    shell.navigate("marketplace");
    return;
  }
  syncSectionLocation("marketplace");
}

function IconLinks({ item, className, includeMarketplace = false }) {
  const links = collectMapLinks(item);
  const marketplaceTarget = includeMarketplace ? resolveMarketplaceTarget(item) : null;
  if (!links.length && !marketplaceTarget) return null;

  return (
    <div className={className}>
      {links.map((link) => (
        <a
          key={`${link.key}-${link.href}`}
          className="map-icon-link"
          href={link.href}
          target={/^https?:/i.test(link.href) ? "_blank" : undefined}
          rel={/^https?:/i.test(link.href) ? "noreferrer" : undefined}
          aria-label={link.label}
          title={link.label}
        >
          <link.icon size={14} strokeWidth={2} aria-hidden="true" />
          <span className="sr-only">{link.label}</span>
        </a>
      ))}
      {marketplaceTarget ? (
        marketplaceTarget.href ? (
          <a
            className="map-icon-link map-icon-link--marketplace"
            href={marketplaceTarget.href}
            target="_blank"
            rel="noreferrer"
            aria-label={marketplaceTarget.label}
            title={marketplaceTarget.label}
          >
            <Store size={14} strokeWidth={2} aria-hidden="true" />
            <span className="sr-only">{marketplaceTarget.label}</span>
          </a>
        ) : (
          <button
            type="button"
            className="map-icon-link map-icon-link--marketplace"
            aria-label={marketplaceTarget.label}
            title={marketplaceTarget.label}
            onClick={() => navigateMarketplaceFromMapItem(item)}
          >
            <Store size={14} strokeWidth={2} aria-hidden="true" />
            <span className="sr-only">{marketplaceTarget.label}</span>
          </button>
        )
      ) : null}
    </div>
  );
}

function DetailLinks({ item }) {
  return <IconLinks item={item} className="selection-links" includeMarketplace />;
}

