export function MapShellMain({
  state,
  canManageMapPlaces = false,
  brandCatalog = MAP_BRAND_CATALOG,
  suppressSelectionOverlay = false,
  focusInsets = null,
}) {
  const { locale } = useChromeI18n();
  const [editor, setEditor] = useState(INITIAL_EDITOR_STATE);
  const [actionError, setActionError] = useState("");
  const [pendingDeleteId, setPendingDeleteId] = useState("");
  const localizedVehicleCategories = useMemo(() => getMapVehicleCategories(locale), [locale]);
  const localizedProfessions = useMemo(() => getMapProfessions(locale), [locale]);
  const localizedShopCategories = useMemo(() => getMapShopCategories(locale), [locale]);
  const vehicleCategoryOptions = useMemo(() => {
    const localizedById = new Map(localizedVehicleCategories.map((entry) => [entry.id, entry]));
    const officialOptions = MAP_VEHICLE_CATEGORIES.map((entry) => {
      const localizedEntry = localizedById.get(entry.id) || entry;
      return {
        value: entry.label,
        label: `${localizedEntry.icon} ${localizedEntry.label}`,
      };
    });
    const knownValues = new Set(officialOptions.map((entry) => entry.value.toLowerCase()));
    const draftOptions = (editor.draft?.categories || [])
      .filter((entry) => !knownValues.has(String(entry || "").trim().toLowerCase()))
      .map((entry) => ({
        value: entry,
        label: entry,
      }));
    return [...officialOptions, ...draftOptions];
  }, [editor.draft?.categories, localizedVehicleCategories]);
  const brandOptions = useMemo(() => {
    const seeded = editor.draft?.brands || [];
    return sortStrings(uniqueStrings([...brandCatalog, ...seeded])).map((entry) => ({
      value: entry,
      label: entry,
    }));
  }, [brandCatalog, editor.draft?.brands]);
  const serviceOptions = useMemo(() => {
    const seeded = editor.draft?.contentTags || [];
    return sortStrings(uniqueStrings([...(state.availableServices || []), ...seeded])).map((entry) => {
      const professionMeta = getMapProfessionMeta(entry, locale);
      return {
        value: entry,
        label: professionMeta ? professionMeta.label : entry,
      };
    });
  }, [editor.draft?.contentTags, locale, state.availableServices]);
  const professionOptions = useMemo(
    () =>
      localizedProfessions.map((entry) => ({
        value: entry.id,
        label: entry.label,
      })),
    [localizedProfessions],
  );
  const shopCategoryOptions = useMemo(() => {
    const localizedById = new Map(localizedShopCategories.map((entry) => [entry.id, entry]));
    const officialOptions = MAP_SHOP_CATEGORIES.map((entry) => {
      const localizedEntry = localizedById.get(entry.id) || entry;
      return {
        value: entry.id,
        label: `${localizedEntry.icon} ${localizedEntry.label}`,
      };
    });
    const knownValues = new Set(officialOptions.map((entry) => entry.value.toLowerCase()));
    const draftOptions = (editor.draft?.contentTags || [])
      .filter((entry) => !knownValues.has(String(entry || "").trim().toLowerCase()))
      .map((entry) => ({
        value: entry,
        label: entry,
    }));
    return [...officialOptions, ...draftOptions];
  }, [editor.draft?.contentTags, localizedShopCategories]);
  const swapistaOptionsByField = useMemo(
    () =>
      SWAPISTA_FIELD_DEFS.reduce((accumulator, field) => {
        const sidebarValues = (state.availableSwapistaOptions?.[field.id] || []).map((entry) => entry.value);
        const draftValue = field.selectionMode === "single"
          ? [editor.draft?.[field.id]].filter(Boolean)
          : Array.isArray(editor.draft?.[field.id])
            ? editor.draft[field.id]
            : [];

        accumulator[field.id] = getSwapistaFieldOptions(field.id, [...sidebarValues, ...draftValue]);
        return accumulator;
      }, {}),
    [editor.draft, state.availableSwapistaOptions],
  );
  const tribeContentOptions = useMemo(() => {
    const draftValues = editor.draft?.contentTags || [];
    const normalizedTribe = normalizeEditorTribe(editor.draft?.tribe, state.tribe);

    if (isServiceLikeTribe(normalizedTribe)) {
      const knownValues = new Set(professionOptions.map((entry) => entry.value.toLowerCase()));
      const draftOptions = draftValues
        .filter((entry) => !knownValues.has(String(entry || "").trim().toLowerCase()))
        .map((entry) => ({ value: entry, label: entry }));
      return [...professionOptions, ...draftOptions];
    }

    if (isShopLikeTribe(normalizedTribe)) {
      return shopCategoryOptions;
    }

    return serviceOptions;
  }, [
    editor.draft?.contentTags,
    editor.draft?.tribe,
    professionOptions,
    serviceOptions,
    shopCategoryOptions,
    state.tribe,
  ]);
  const tribeContentLabel = useMemo(() => {
    const normalizedTribe = editor.draft?.tribe || state.tribe;
    if (isServiceLikeTribe(normalizedTribe)) return "Especialidades";
    if (isShopLikeTribe(normalizedTribe)) return "Subcategorias de tienda";
    return "Contenido de tribu";
  }, [editor.draft?.tribe, state.tribe]);
  const tribeContentPlaceholder = useMemo(() => {
    const normalizedTribe = editor.draft?.tribe || state.tribe;
    if (isServiceLikeTribe(normalizedTribe)) return "Seleccionar especialidades";
    if (isShopLikeTribe(normalizedTribe)) return "Seleccionar subcategorias";
    return "Seleccionar contenido";
  }, [editor.draft?.tribe, state.tribe]);
  const tribeContentAllowCustom = useMemo(() => {
    const normalizedTribe = editor.draft?.tribe || state.tribe;
    return !isServiceLikeTribe(normalizedTribe) && !isShopLikeTribe(normalizedTribe);
  }, [editor.draft?.tribe, state.tribe]);

  useEffect(() => {
    if (!canManageMapPlaces && editor.mode !== "idle") {
      setEditor(INITIAL_EDITOR_STATE);
    }
  }, [canManageMapPlaces, editor.mode]);

  useEffect(() => {
    if (editor.mode === "edit" && editor.itemId && editor.itemId !== state.selectedItemId) {
      setEditor(INITIAL_EDITOR_STATE);
    }
  }, [editor.itemId, editor.mode, state.selectedItemId]);

  const handleCloseOverlay = () => {
    setActionError("");
    if (editor.mode !== "idle") {
      setEditor(INITIAL_EDITOR_STATE);
      return;
    }
    state.setSelectedItemId(null);
  };

  const handleStartCreate = () => {
    if (!canManageMapPlaces) return;
    const activeSwapistaFilters = isSwapistaTribe(state.tribe)
      ? {
          swapista: {
            ...createEmptySwapistaFilters(),
            ...(state.tribeFilters || {}),
          },
        }
      : {};

    setActionError("");
    state.setSelectedItemId(null);
    setEditor({
      mode: "create",
      itemId: "",
      loading: false,
      saving: false,
      error: "",
      locationPicker: false,
      item: null,
      draft: createSeedDraft({
        tribe: state.tribe,
        country: state.country,
        ...activeSwapistaFilters,
        contentTags:
          state.tribe === "shops" && state.shopCategory
            ? [state.shopCategory]
            : state.tribe === "services" && state.profession
              ? [state.profession]
              : [],
      }),
    });
  };

  const handleStartEdit = async () => {
    if (!state.selectedItem || !canManageMapPlaces) return;

    setActionError("");
    setEditor({
      mode: "edit",
      itemId: state.selectedItem.id,
      loading: true,
      saving: false,
      error: "",
      locationPicker: false,
      item: null,
      draft: null,
    });

    try {
      const detailedItem = await fetchMapPlaceDetail(state.selectedItem.id);
      if (!detailedItem) throw new Error("No se pudo cargar el detalle editable del pin.");

      state.upsertItem(detailedItem);
      setEditor({
        mode: "edit",
        itemId: detailedItem.id,
        loading: false,
        saving: false,
        error: "",
        locationPicker: false,
        item: detailedItem,
        draft: createEditorDraft(detailedItem),
      });
    } catch (error) {
      setEditor({
        mode: "edit",
        itemId: state.selectedItem.id,
        loading: false,
        saving: false,
        error: error instanceof Error ? error.message : "No se pudo abrir el editor.",
        locationPicker: false,
        item: null,
        draft: null,
      });
    }
  };

  const handleEditorFieldChange = (field, value) => {
    setEditor((current) => ({
      ...current,
      error: "",
      draft: current.draft
        ? {
            ...current.draft,
            [field]: field === "tribe" ? normalizeEditorTribe(value) : value,
          }
        : current.draft,
    }));
  };

  const handleToggleLocationPicker = () => {
    setEditor((current) => {
      if (current.mode === "idle") return current;
      return {
        ...current,
        locationPicker: !current.locationPicker,
      };
    });
  };

  const handleMapCoordinatePick = (point) => {
    setEditor((current) => {
      if (current.mode === "idle" || !current.draft) return current;
      return {
        ...current,
        locationPicker: false,
        draft: {
          ...current.draft,
          lat: point.lat.toFixed(6),
          lng: point.lng.toFixed(6),
        },
      };
    });
  };

  const handleCancelEdit = () => {
    setActionError("");
    setEditor(INITIAL_EDITOR_STATE);
  };

  const handleSaveEdit = async () => {
    if (!editor.draft) return;

    const validationError = validateEditorDraft(editor.draft);
    if (validationError) {
      setEditor((current) => ({ ...current, error: validationError }));
      return;
    }

    setEditor((current) => ({ ...current, saving: true, error: "" }));
    setActionError("");

    try {
      if (editor.mode === "create") {
        const created = await createMapPlace(buildCreatePayload(editor.draft));
        if (!created.item) throw new Error("La API no devolvio el pin creado.");

        state.upsertItem(created.item);
        state.setSelectedItemId(created.item.id);
      } else if (editor.mode === "edit" && editor.item) {
        const updatedItem = await updateMapPlace(editor.item.id, buildUpdatePayload(editor.item, editor.draft));
        if (!updatedItem) throw new Error("La API no devolvio el pin actualizado.");

        state.upsertItem(updatedItem);
        state.setSelectedItemId(updatedItem.id);
      }

      setEditor(INITIAL_EDITOR_STATE);
      state.refresh();
    } catch (error) {
      setEditor((current) => ({
        ...current,
        saving: false,
        error: error instanceof Error ? error.message : "No se pudo guardar el pin.",
      }));
    }
  };

  const handleDelete = async () => {
    if (!state.selectedItem || !canManageMapPlaces) return;

    const confirmed = window.confirm(
      `Vas a eliminar "${state.selectedItem.name}". Esta accion no se puede deshacer.`,
    );
    if (!confirmed) return;

    setActionError("");
    setPendingDeleteId(state.selectedItem.id);

    try {
      await deleteMapPlace(state.selectedItem.id);
      state.removeItem(state.selectedItem.id);
      state.setSelectedItemId(null);
      setEditor(INITIAL_EDITOR_STATE);
      state.refresh();
    } catch (error) {
      setActionError(error instanceof Error ? error.message : "No se pudo eliminar el pin.");
    } finally {
      setPendingDeleteId("");
    }
  };

  return (
    <section className="map-main-direct" aria-label="Mapa">
      <div className="map-main-direct__body">
        <HostLeafletMap
          items={state.filteredItems}
          selectedCountry={state.country}
          selectedItemId={state.selectedItemId}
          onSelectItem={state.setSelectedItemId}
          focusInsets={focusInsets}
          suppressSelectionOverlay={suppressSelectionOverlay}
          locationPicker={{
            enabled: editor.mode !== "idle" && editor.locationPicker,
            point: getDraftPoint(editor.draft),
            onPick: handleMapCoordinatePick,
          }}
        />
        {canManageMapPlaces ? (
          <button
            type="button"
            className="map-admin-fab"
            onClick={handleStartCreate}
            aria-label="Crear nuevo pin seed"
            title="Crear nuevo pin seed"
          >
            <Plus size={18} strokeWidth={2.3} aria-hidden="true" />
            <span>Nuevo pin</span>
          </button>
        ) : null}
        {!suppressSelectionOverlay || editor.mode !== "idle" ? (
          <MapOverlayDetail
            item={state.selectedItem}
            canManageMapPlaces={canManageMapPlaces}
            editor={editor}
            actionError={actionError}
            deleting={pendingDeleteId === state.selectedItem?.id}
            vehicleCategoryOptions={vehicleCategoryOptions}
            brandOptions={brandOptions}
            tribeContentOptions={tribeContentOptions}
            tribeContentLabel={tribeContentLabel}
            tribeContentPlaceholder={tribeContentPlaceholder}
            tribeContentAllowCustom={tribeContentAllowCustom}
            swapistaOptionsByField={swapistaOptionsByField}
            onClose={handleCloseOverlay}
            onStartEdit={handleStartEdit}
            onDelete={handleDelete}
            onFieldChange={handleEditorFieldChange}
            onToggleLocationPicker={handleToggleLocationPicker}
            onCancelEdit={handleCancelEdit}
            onSaveEdit={handleSaveEdit}
          />
        ) : null}
      </div>
    </section>
  );
}
