import React from "react";
import { useChromeI18n } from "../../shared/i18n/i18n.jsx";

export const SETTINGS_TABS = [
  { id: "profile", label: "Perfil" },
  { id: "language", label: "Idioma" },
  { id: "subscription", label: "Suscripcion" },
  { id: "notifications", label: "Notificaciones" },
];

export function SettingsShellSidebar({ activeTab, onSelectTab, session }) {
  const { t } = useChromeI18n();
  const tabs = [
    { id: "profile", label: t("common.profile", "Perfil") },
    { id: "language", label: t("common.language", "Idioma") },
    { id: "subscription", label: t("common.subscription", "Suscripcion") },
    { id: "notifications", label: t("common.notifications", "Notificaciones") },
  ];

  return (
    <section className="settings-shell settings-shell--sidebar">
      <header className="settings-shell__header">
        <div>
          <p className="planning-panel__eyebrow">{t("common.motors", "Motors")}</p>
          <h2 className="planning-panel__title">{t("common.settings", "Settings")}</h2>
        </div>
      </header>

      <section className="settings-profile-card">
        <strong>{session.displayName}</strong>
        <span>{session.subject?.email || session.user?.primaryEmail || t("common.noEmail", "Sin email")}</span>
      </section>

      <nav className="settings-nav" aria-label={t("common.settings", "Settings")}>
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            className={`settings-nav__item ${activeTab === tab.id ? "is-active" : ""}`}
            onClick={() => onSelectTab(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </nav>
    </section>
  );
}
