export function normalizeProfessionIconId(professionId) {
  const normalized = String(professionId || "").trim().toLowerCase();
  if (!normalized) return "unknown";
  return ICON_ALIAS_BY_ID[normalized] || (ICON_MARKUP_BY_ID[normalized] ? normalized : "unknown");
}

export function getProfessionIconSvgMarkup(
  professionId,
  { size = 16, className = "profession-icon__svg", stroke = "currentColor", strokeWidth = 1.9 } = {},
) {
  const iconId = normalizeProfessionIconId(professionId);
  const innerMarkup = ICON_MARKUP_BY_ID[iconId] || ICON_MARKUP_BY_ID.unknown;

  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"`,
    ` stroke="${stroke}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round"`,
    ` width="${size}" height="${size}" class="${className}" aria-hidden="true" focusable="false">`,
    innerMarkup,
    "</svg>",
  ].join("");
}

export function ProfessionIcon({
  professionId,
  className = "",
  size = 16,
  stroke = "currentColor",
  strokeWidth = 1.9,
}) {
  return (
    <span
      className={className}
      aria-hidden="true"
      dangerouslySetInnerHTML={{
        __html: getProfessionIconSvgMarkup(professionId, { size, stroke, strokeWidth }),
      }}
    />
  );
}
