const ICON_ALIAS_BY_ID = {
  profesionales: "services",
  servicios: "services",
};

export function normalizeTribeIconId(tribeId) {
  const normalized = String(tribeId || "").trim().toLowerCase();
  if (!normalized) return "unknown";
  return ICON_ALIAS_BY_ID[normalized] || (ICON_MARKUP_BY_ID[normalized] ? normalized : "unknown");
}

export function getTribeIconSvgMarkup(
  tribeId,
  { size = 16, className = "tribe-icon__svg", stroke = "currentColor", strokeWidth = 1.9 } = {},
) {
  const iconId = normalizeTribeIconId(tribeId);
  const innerMarkup = ICON_MARKUP_BY_ID[iconId] || ICON_MARKUP_BY_ID.unknown;

  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"`,
    ` stroke="${stroke}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round"`,
    ` width="${size}" height="${size}" class="${className}" aria-hidden="true" focusable="false">`,
    innerMarkup,
    "</svg>",
  ].join("");
}

export function TribeIcon({ tribeId, className = "", size = 16, stroke = "currentColor", strokeWidth = 1.9 }) {
  return (
    <span
      className={className}
      aria-hidden="true"
      dangerouslySetInnerHTML={{
        __html: getTribeIconSvgMarkup(tribeId, { size, stroke, strokeWidth }),
      }}
    />
  );
}
