import { initializeApp, getApps } from "firebase/app";
import {
  GoogleAuthProvider,
  browserLocalPersistence,
  connectAuthEmulator,
  createUserWithEmailAndPassword,
  getAuth,
  onIdTokenChanged,
  setPersistence,
  signInWithEmailAndPassword,
  signInWithPopup,
  signOut,
} from "firebase/auth";

const AUTH_CACHE_KEY = "btr_auth_cache_v1";
const AUTH_CACHE_UPDATED_EVENT = "btr:auth-cache-updated";

const FIREBASE_CONFIG = {
  apiKey: String(import.meta.env.VITE_FIREBASE_API_KEY || "").trim(),
  authDomain: String(import.meta.env.VITE_FIREBASE_AUTH_DOMAIN || "").trim(),
  projectId: String(import.meta.env.VITE_FIREBASE_PROJECT_ID || "").trim(),
  storageBucket: String(import.meta.env.VITE_FIREBASE_STORAGE_BUCKET || "").trim(),
  appId: String(import.meta.env.VITE_FIREBASE_APP_ID || "").trim(),
};

const FIREBASE_AUTH_EMULATOR_URL = String(
  import.meta.env.VITE_FIREBASE_AUTH_EMULATOR_URL || "",
).trim();

let firebaseApp = null;
let firebaseAuth = null;
let persistencePromise = null;
let authEmulatorConnected = false;

function buildSnapshot(user, tokenResult) {
  const token = tokenResult?.token || "";
  return {
    user: user
      ? {
          uid: user.uid,
          displayName: user.displayName || "",
          email: user.email || "",
          photoURL: user.photoURL || "",
        }
      : null,
    idToken: token || null,
    token: token || null,
    claims: tokenResult?.claims || {},
    expiresAt: tokenResult?.expirationTime ? new Date(tokenResult.expirationTime).getTime() : null,
    isReady: true,
  };
}

function emitSnapshot(snapshot) {
  try {
    if (snapshot) {
      window.localStorage?.setItem(AUTH_CACHE_KEY, JSON.stringify(snapshot));
      window.__BTR_AUTH__ = snapshot;
    } else {
      window.localStorage?.removeItem(AUTH_CACHE_KEY);
      window.sessionStorage?.removeItem(AUTH_CACHE_KEY);
      delete window.__BTR_AUTH__;
    }
  } catch {
    // noop
  }

  try {
    window.dispatchEvent(new CustomEvent(AUTH_CACHE_UPDATED_EVENT, { detail: snapshot || null }));
  } catch {
    // noop
  }
}

export function isFirebaseAuthConfigured() {
  return Boolean(
    FIREBASE_CONFIG.apiKey &&
      FIREBASE_CONFIG.authDomain &&
      FIREBASE_CONFIG.projectId &&
      FIREBASE_CONFIG.appId,
  );
}

function ensureFirebaseAuth() {
  if (!isFirebaseAuthConfigured()) {
    throw new Error(
      "Firebase web config missing. Define VITE_FIREBASE_API_KEY, VITE_FIREBASE_AUTH_DOMAIN, VITE_FIREBASE_PROJECT_ID and VITE_FIREBASE_APP_ID.",
    );
  }

  if (!firebaseApp) {
    firebaseApp = getApps().length ? getApps()[0] : initializeApp(FIREBASE_CONFIG);
  }

  if (!firebaseAuth) {
    firebaseAuth = getAuth(firebaseApp);
    if (FIREBASE_AUTH_EMULATOR_URL && !authEmulatorConnected) {
      connectAuthEmulator(firebaseAuth, FIREBASE_AUTH_EMULATOR_URL, { disableWarnings: true });
      authEmulatorConnected = true;
    }
  }

  return firebaseAuth;
}

async function ensureFirebaseAuthWithPersistence() {
  const auth = ensureFirebaseAuth();
  if (!persistencePromise) {
    persistencePromise = setPersistence(auth, browserLocalPersistence);
  }
  await persistencePromise;
  return auth;
}

export function subscribeToFirebaseSession(onChange) {
  if (!isFirebaseAuthConfigured()) return () => {};

  const auth = ensureFirebaseAuth();
  return onIdTokenChanged(
    auth,
    async (user) => {
      if (!user) {
        emitSnapshot(null);
        onChange?.(null);
        return;
      }

      const tokenResult = await user.getIdTokenResult();
      const snapshot = buildSnapshot(user, tokenResult);
      emitSnapshot(snapshot);
      onChange?.(snapshot);
    },
    () => {},
  );
}

export async function signInWithFirebaseEmail(email, password) {
  const auth = await ensureFirebaseAuthWithPersistence();
  const credential = await signInWithEmailAndPassword(auth, email, password);
  const tokenResult = await credential.user.getIdTokenResult();
  emitSnapshot(buildSnapshot(credential.user, tokenResult));
  return credential;
}

export async function registerWithFirebaseEmail(email, password) {
  const auth = await ensureFirebaseAuthWithPersistence();
  const credential = await createUserWithEmailAndPassword(auth, email, password);
  const tokenResult = await credential.user.getIdTokenResult();
  emitSnapshot(buildSnapshot(credential.user, tokenResult));
  return credential;
}

export async function signInWithFirebaseGoogle() {
  const auth = await ensureFirebaseAuthWithPersistence();
  const credential = await signInWithPopup(auth, new GoogleAuthProvider());
  const tokenResult = await credential.user.getIdTokenResult();
  emitSnapshot(buildSnapshot(credential.user, tokenResult));
  return credential;
}

export async function signOutFirebaseSession() {
  const auth = ensureFirebaseAuth();
  await signOut(auth);
  emitSnapshot(null);
}

export async function refreshFirebaseSession() {
  const auth = ensureFirebaseAuth();
  const user = auth.currentUser;
  if (!user) {
    emitSnapshot(null);
    return null;
  }

  const tokenResult = await user.getIdTokenResult(true);
  const snapshot = buildSnapshot(user, tokenResult);
  emitSnapshot(snapshot);
  return snapshot;
}

export { AUTH_CACHE_UPDATED_EVENT };
