import { DEFAULT_SECTION_ID, isKnownSection, resolveSectionId } from "../config/sections.js";

const trimSegmentSlashes = (value) => String(value || "").replace(/^\/+|\/+$/g, "");
const baseUrl = String(import.meta.env.BASE_URL || "/").trim();
const normalizedBasePath = trimSegmentSlashes(baseUrl);

function getBasePath() {
  return normalizedBasePath ? `/${normalizedBasePath}` : "";
}

function stripBasePath(pathname) {
  const normalizedPathname = String(pathname || "").trim() || "/";
  const basePath = getBasePath();
  if (!basePath) return normalizedPathname;
  if (normalizedPathname === basePath) return "/";
  if (normalizedPathname.startsWith(`${basePath}/`)) {
    return normalizedPathname.slice(basePath.length) || "/";
  }
  return normalizedPathname;
}

export function readSectionFromHash(hashValue) {
  const raw = String(hashValue || "")
    .replace(/^#\/?/, "")
    .trim()
    .toLowerCase();
  return resolveSectionId(raw);
}

export function readSectionFromPath(pathname) {
  const relativePath = trimSegmentSlashes(stripBasePath(pathname)).toLowerCase();
  if (!relativePath) return DEFAULT_SECTION_ID;
  const firstSegment = relativePath.split("/")[0];
  return resolveSectionId(firstSegment) || DEFAULT_SECTION_ID;
}

export function readSectionFromLocation(locationValue = window.location) {
  const hashSection = readSectionFromHash(locationValue?.hash);
  if (hashSection) return hashSection;
  return readSectionFromPath(locationValue?.pathname);
}

export function getSectionPath(sectionId) {
  const normalizedSectionId = isKnownSection(sectionId) ? sectionId : DEFAULT_SECTION_ID;
  const basePath = getBasePath();
  return `${basePath}/${normalizedSectionId}` || `/${normalizedSectionId}`;
}

export function syncSectionLocation(sectionId, { replace = false } = {}) {
  if (typeof window === "undefined") return;

  const nextPath = getSectionPath(sectionId);
  const currentPath = window.location.pathname || "/";
  const currentHashSection = readSectionFromHash(window.location.hash);

  if (currentPath === nextPath && !currentHashSection) return;

  const nextUrl = `${nextPath}${window.location.search || ""}`;
  const writer = replace ? window.history.replaceState : window.history.pushState;
  writer.call(window.history, null, "", nextUrl);
}

export function normalizeSectionLocation(sectionId = readSectionFromLocation(), options = {}) {
  syncSectionLocation(sectionId, { replace: true, ...options });
  return sectionId;
}
