import React from "react";
import * as FlagIcons from "country-flag-icons/react/3x2";

const normalizeCountryCode = (value) => String(value || "").trim().toUpperCase();

export function CountryFlag({ countryCode, className, title }) {
  const code = normalizeCountryCode(countryCode);
  if (!code) return null;

  const FlagIcon = FlagIcons[code];
  if (!FlagIcon) return null;

  return <FlagIcon className={className} title={title || code} aria-label={title || code} />;
}

