import React from "react";
import { useChromeI18n } from "../shared/i18n/i18n.jsx";
import { resolveCoreApiUiMessage } from "../lib/coreApiConfig.js";

function formatTime(value, localeTag) {
  if (!value) return "-";
  try {
    return new Intl.DateTimeFormat(localeTag, {
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    }).format(new Date(value));
  } catch {
    return "-";
  }
}

export default function AuthStatusCard({ session, compact = false }) {
  const { locale, localeTag, t } = useChromeI18n();
  const authz = session.me?.authz;
  const permissions = Array.isArray(authz?.permissions) ? authz.permissions : [];
  const statusClass = `auth-card__badge auth-card__badge--${session.status}`;
  const uiError = resolveCoreApiUiMessage(session.error, locale);

  return (
    <section className={`panel-card auth-card ${compact ? "auth-card--compact" : ""}`}>
      <header className="panel-card__header">
        <div>
          <p className="panel-card__eyebrow">Auto ID</p>
          <h3 className="panel-card__title">beterano-core-api</h3>
        </div>
        <span className={statusClass}>{session.status}</span>
      </header>

      <div className="auth-card__body">
        <div className="auth-card__row">
          <span>{t("common.user", "Usuario")}</span>
          <strong>{session.displayName}</strong>
        </div>
        <div className="auth-card__row">
          <span>{t("common.mode", "Modo")}</span>
          <span>{session.authMode || "none"}</span>
        </div>
        <div className="auth-card__row">
          <span>{t("common.uid", "UID")}</span>
          <code>{session.subject?.uid || "-"}</code>
        </div>
        <div className="auth-card__row">
          <span>{t("common.email", "Email")}</span>
          <span>{session.subject?.email || session.user?.primaryEmail || "-"}</span>
        </div>
        {authz ? (
          <div className="auth-card__row">
            <span>Authz</span>
            <span>{authz.allow ? "allow" : "deny"}</span>
          </div>
        ) : null}
        {authz ? (
          <div className="auth-card__row">
            <span>{t("common.admin", "Admin")}</span>
            <span>{permissions.includes("*") ? t("common.superAdmin", "super admin") : "no"}</span>
          </div>
        ) : null}
        {!compact && session.memberships.length ? (
          <div className="auth-card__memberships">
            {session.memberships.slice(0, 4).map((membership) => (
              <div key={membership.id} className="auth-card__membership-pill">
                {membership.scope}:{" "}
                {membership.workshop?.name || membership.role}
              </div>
            ))}
          </div>
        ) : null}
        {uiError ? <p className="auth-card__error">{uiError}</p> : null}
      </div>

      <footer className="panel-card__footer">
        <span>{`${t("common.updatedAt", "Actualizado")} ${formatTime(session.updatedAt, localeTag)}`}</span>
        <button type="button" className="ghost-btn" onClick={session.refresh}>
          {t("common.refresh", "Refresh")}
        </button>
      </footer>
    </section>
  );
}
