// Catálogo canónico de marcas/modelos (world_classics de beterano-data), vendorizado
// aquí como worldClassics.json — MISMA fuente que el marketplace. Se usa para poblar
// el filtro de "especialidad" del mapa (marca/modelo que trabaja una tribu), en vez del
// catálogo estático viejo o del endpoint del core-api (que hoy devuelve 0).
// Para actualizar: copiar de nuevo el worldClassics.json del marketplace.
import RAW from "./worldClassics.json";

const brandSet = new Set();
const modelsByBrand = new Map();
for (const types of Object.values(RAW.classes || {})) {
  for (const brands of Object.values(types)) {
    for (const [brand, models] of Object.entries(brands)) {
      brandSet.add(brand);
      if (!modelsByBrand.has(brand)) modelsByBrand.set(brand, new Set());
      for (const model of models) modelsByBrand.get(brand).add(model);
    }
  }
}

const sortEs = (values) => [...values].sort((a, b) => a.localeCompare(b, "es"));

/** Todas las marcas del catálogo (coche + moto), ordenadas. */
export const WORLD_CLASSICS_BRANDS = sortEs([...brandSet]);

/** Modelos catalogados de una marca (todas las clases). */
export function modelsForBrand(brand) {
  const set = modelsByBrand.get(String(brand || "").trim());
  return set ? sortEs([...set]) : [];
}
