function resolveLocale(locale) {
  const normalized = String(locale || "es").trim().toLowerCase();
  if (normalized === "es") return "es";
  return PROFESSION_LABELS[normalized] ? normalized : "en";
}

function localizeProfession(entry, locale) {
  const normalizedLocale = resolveLocale(locale);
  if (normalizedLocale === "es") {
    return entry;
  }
  const labelMap = PROFESSION_LABELS[normalizedLocale] || PROFESSION_LABELS.en;
  const groupMap = PROFESSION_GROUP_LABELS[normalizedLocale] || PROFESSION_GROUP_LABELS.en;
  return {
    ...entry,
    label: labelMap[entry.id] || entry.label,
    group: groupMap[entry.group] || entry.group,
  };
}

export const MAP_PROFESSION_BY_ID = new Map(MAP_PROFESSIONS.map((entry) => [entry.id, entry]));

export const getMapProfessions = (locale = "es") => MAP_PROFESSIONS.map((entry) => localizeProfession(entry, locale));

export const getMapProfessionMeta = (professionId, locale = "es") => {
  const entry = MAP_PROFESSION_BY_ID.get(String(professionId || "").trim());
  return entry ? localizeProfession(entry, locale) : null;
};

