import { useEffect, useState } from "react";

function toLogoUrl(value) {
  const raw = String(value || "").trim();
  return raw || "";
}

export function CompanyLogoSlot({ logoUrl, fallbackIcon, sizeClass = "company-logo-slot--md", title = "" }) {
  const resolvedLogoUrl = toLogoUrl(logoUrl);
  const [hasError, setHasError] = useState(false);

  useEffect(() => {
    setHasError(false);
  }, [resolvedLogoUrl]);

  const showImage = Boolean(resolvedLogoUrl) && !hasError;

  return (
    <span className={`company-logo-slot ${sizeClass}`.trim()} title={title || undefined} aria-hidden="true">
      {showImage ? (
        <img src={resolvedLogoUrl} alt="" loading="lazy" decoding="async" onError={() => setHasError(true)} />
      ) : (
        <span className="company-logo-slot__glyph">{fallbackIcon || "*"}</span>
      )}
    </span>
  );
}
