import React from "react";
import AuthStatusCard from "../AuthStatusCard.jsx";
import { AuthSessionCard } from "../auth/AuthSessionCard.jsx";
import { LOCALE_OPTIONS, useChromeI18n } from "../../shared/i18n/i18n.jsx";

function SettingsProfileTab({ session, compact = false }) {
  const { t } = useChromeI18n();
  return (
    <div className="settings-main__grid">
      <section className="panel-card">
        <header className="panel-card__header">
          <div>
            <p className="panel-card__eyebrow">{t("common.profile", "Perfil")}</p>
            <h2 className="panel-card__title">{t("common.identityMotors", "Identidad Motors")}</h2>
          </div>
        </header>
        <div className="selection-details">
          <div>
            <span>{t("common.displayName", "Display name")}</span>
            <strong>{session.displayName}</strong>
          </div>
          <div>
            <span>{t("common.email", "Email")}</span>
            <strong>{session.subject?.email || session.user?.primaryEmail || "-"}</strong>
          </div>
          <div>
            <span>{t("common.uid", "UID")}</span>
            <strong>{session.subject?.uid || "-"}</strong>
          </div>
        </div>
      </section>

      <AuthSessionCard session={session} />
      <AuthStatusCard session={session} compact={compact} />
    </div>
  );
}

function SettingsLanguageTab({ preferences, onChangePreferences }) {
  const { t } = useChromeI18n();
  return (
    <section className="panel-card">
      <header className="panel-card__header">
        <div>
          <p className="panel-card__eyebrow">{t("common.language", "Idioma")}</p>
          <h2 className="panel-card__title">{t("common.shellLanguage", "Idioma del shell")}</h2>
        </div>
      </header>
      <label className="profile-settings__field">
        <span>{t("common.language", "Idioma")}</span>
        <select
          value={preferences.language}
          onChange={(event) => onChangePreferences({ language: event.target.value })}
        >
          {LOCALE_OPTIONS.map((entry) => (
            <option key={entry.value} value={entry.value}>
              {entry.label}
            </option>
          ))}
        </select>
      </label>
    </section>
  );
}

function SettingsSubscriptionTab({ preferences, onChangePreferences }) {
  const { t } = useChromeI18n();
  return (
    <section className="panel-card">
      <header className="panel-card__header">
        <div>
          <p className="panel-card__eyebrow">{t("common.subscription", "Suscripcion")}</p>
          <h2 className="panel-card__title">{t("common.planMotors", "Plan Motors")}</h2>
        </div>
      </header>
      <label className="profile-settings__field">
        <span>{t("common.plan", "Plan")}</span>
        <select
          value={preferences.subscription}
          onChange={(event) => onChangePreferences({ subscription: event.target.value })}
        >
          <option value="motors-basic">Motors Basic</option>
          <option value="motors-pro">Motors Pro</option>
          <option value="motors-business">Motors Business</option>
        </select>
      </label>
    </section>
  );
}

function SettingsNotificationsTab({ preferences, onChangePreferences }) {
  const { t } = useChromeI18n();
  const toggle = (key) => {
    onChangePreferences({
      notifications: {
        [key]: !preferences.notifications[key],
      },
    });
  };

  return (
    <section className="panel-card">
      <header className="panel-card__header">
        <div>
          <p className="panel-card__eyebrow">{t("common.notifications", "Notificaciones")}</p>
          <h2 className="panel-card__title">{t("common.activeChannels", "Canales activos")}</h2>
        </div>
      </header>
      <div className="profile-settings__block">
        <label className="profile-settings__toggle">
          <input type="checkbox" checked={preferences.notifications.push} onChange={() => toggle("push")} />
          <span>{t("common.pushBrowser", "Push en navegador")}</span>
        </label>
        <label className="profile-settings__toggle">
          <input type="checkbox" checked={preferences.notifications.email} onChange={() => toggle("email")} />
          <span>{t("common.email", "Email")}</span>
        </label>
        <label className="profile-settings__toggle">
          <input
            type="checkbox"
            checked={preferences.notifications.workAlerts}
            onChange={() => toggle("workAlerts")}
          />
          <span>{t("common.workAlerts", "Avisos de trabajos / actividad")}</span>
        </label>
      </div>
    </section>
  );
}

export function SettingsShellMain({ activeTab, preferences, onChangePreferences, session, compact = false, hideHeader = false }) {
  const { t } = useChromeI18n();
  return (
    <section className="settings-main-shell">
      {!hideHeader ? (
        <header className="planning-main-shell__header">
          <div>
            <p className="planning-panel__eyebrow">{t("common.settings", "Settings")}</p>
            <h2 className="planning-panel__title">
              {activeTab === "profile" && t("common.profile", "Perfil")}
              {activeTab === "language" && t("common.language", "Idioma")}
              {activeTab === "subscription" && t("common.subscription", "Suscripcion")}
              {activeTab === "notifications" && t("common.notifications", "Notificaciones")}
            </h2>
          </div>
        </header>
      ) : null}

      {activeTab === "profile" ? <SettingsProfileTab session={session} compact={compact} /> : null}
      {activeTab === "language" ? (
        <SettingsLanguageTab preferences={preferences} onChangePreferences={onChangePreferences} />
      ) : null}
      {activeTab === "subscription" ? (
        <SettingsSubscriptionTab preferences={preferences} onChangePreferences={onChangePreferences} />
      ) : null}
      {activeTab === "notifications" ? (
        <SettingsNotificationsTab preferences={preferences} onChangePreferences={onChangePreferences} />
      ) : null}
    </section>
  );
}
