import { CORE_API_BASE_URL, MISSING_CORE_API_MESSAGE } from "./coreApiConfig.js";

const CORE_API_BASE = CORE_API_BASE_URL;
const DEV_AUTH_EMAIL = String(import.meta.env.VITE_DEV_AUTH_EMAIL || "").trim();

function readStoredSnapshot() {
  if (typeof window === "undefined") return null;

  const tryParse = (raw) => {
    if (!raw) return null;
    try {
      return JSON.parse(raw);
    } catch {
      return null;
    }
  };

  return (
    tryParse(window.localStorage?.getItem("btr_auth_cache_v1")) ||
    tryParse(window.sessionStorage?.getItem("btr_auth_cache_v1")) ||
    (window.__BTR_AUTH__ && typeof window.__BTR_AUTH__ === "object" ? window.__BTR_AUTH__ : null)
  );
}

function resolveIdToken(snapshot) {
  if (!snapshot || typeof snapshot !== "object") return "";
  if (typeof snapshot.idToken === "string" && snapshot.idToken.trim()) return snapshot.idToken.trim();
  if (typeof snapshot.token === "string" && snapshot.token.trim()) return snapshot.token.trim();
  return "";
}

function buildBaseUrl(path) {
  const base = String(CORE_API_BASE || "").trim();
  const normalizedPath = path.startsWith("/") ? path : `/${path}`;
  if (!base) throw new Error(MISSING_CORE_API_MESSAGE);

  if (base.startsWith("http://") || base.startsWith("https://")) {
    return new URL(normalizedPath, `${base.replace(/\/+$/, "")}/`).toString();
  }

  const origin = typeof window !== "undefined" ? window.location.origin : "http://localhost:5173";
  const normalizedBase = base.startsWith("/") ? base : `/${base}`;
  return new URL(`${normalizedBase.replace(/\/+$/, "")}${normalizedPath}`, origin).toString();
}

export function buildCoreApiHeaders() {
  const snapshot = readStoredSnapshot();
  const idToken = resolveIdToken(snapshot);
  const headers = {
    Accept: "application/json",
  };

  if (idToken) {
    headers.Authorization = `Bearer ${idToken}`;
    return headers;
  }

  if (DEV_AUTH_EMAIL) {
    headers["x-dev-auth-email"] = DEV_AUTH_EMAIL;
  }

  return headers;
}

export async function fetchCoreJson(path, query = {}, options = {}) {
  const url = new URL(buildBaseUrl(path));

  Object.entries(query).forEach(([key, value]) => {
    if (value === undefined || value === null || value === "") return;
    url.searchParams.set(key, String(value));
  });

  const response = await fetch(url.toString(), {
    ...options,
    headers: {
      ...buildCoreApiHeaders(),
      ...(options.headers || {}),
    },
  });

  const payload = await response.json().catch(() => null);
  if (!response.ok) {
    throw new Error(payload?.error || payload?.message || `HTTP ${response.status}`);
  }

  return payload;
}
