const ENV = import.meta.env;

const trimSlash = (value) => String(value || "").replace(/\/+$/, "");
const LOCAL_HOSTS = new Set(["", "localhost", "127.0.0.1", "::1"]);
const shellHost = typeof window !== "undefined" ? String(window.location.hostname || "").toLowerCase() : "";
const shellPort = typeof window !== "undefined" ? String(window.location.port || "") : "";
const isLocalHost = LOCAL_HOSTS.has(shellHost);
const labSafeMode = shellPort === "5273";
const publicPagesOrigin = trimSlash(ENV.VITE_PUBLIC_PAGES_ORIGIN || "https://beteranomotors.github.io");
const publicRemoteUrl = (path) => `${publicPagesOrigin}${path}`;
// Los hijos empaquetados dentro del bundle chrome (calendar) se sirven en el mismo
// origen que el shell, no en publicPagesOrigin (alli dan 404). Ver scripts/publish-pages.mjs.
const shellOrigin = typeof window !== "undefined" ? trimSlash(window.location.origin || "") : "";
const childRemoteUrl = (path) => `${shellOrigin}${path}`;
const mapDefaultUrl = isLocalHost
  ? labSafeMode
    ? "http://localhost:5274/"
    : "http://localhost:5174/"
  : publicRemoteUrl("/map/");
const garagexDefaultUrl = isLocalHost
  ? labSafeMode
    ? "http://localhost:5275/"
    : "http://localhost:5175/"
  : publicRemoteUrl("/apps/garagex/");
const workerDefaultUrl = isLocalHost
  ? shellPort === "5273"
    ? "http://localhost:5276/"
    : "http://localhost:5176/"
  : "";
const calendarDefaultUrl = trimSlash(
  ENV.VITE_REMOTE_CALENDAR_URL ||
    (isLocalHost
      ? labSafeMode
        ? "http://localhost:3202/calendar/"
        : "http://localhost:3002/calendar/"
      : childRemoteUrl("/apps/calendar/")),
);
const marketplaceDefaultUrl = trimSlash(
  ENV.VITE_REMOTE_MARKETPLACE_URL || (isLocalHost ? "http://localhost:3001" : ""),
);

