export const SECTION_BY_ID = Object.fromEntries(SECTION_DEFS.map((section) => [section.id, section]));

// Alias -> id canonico. `planning` fue el id de esta seccion cuando servia el
// planning de taller de LAB; se mantiene como alias para no romper enlaces vivos.
// El planning operativo de taller es de LAB, no de Motors.
export const SECTION_ALIASES = {
  cal: "calendar",
  plan: "calendar",
  planning: "calendar",
  events: "calendar",
  market: "marketplace",
  shop: "marketplace",
  garage: "garagex",
  work: "worker",
};

export function isKnownSection(sectionId) {
  return Boolean(SECTION_BY_ID[sectionId]);
}

// Devuelve el id canonico de una seccion (resolviendo alias), o "" si no existe.
export function resolveSectionId(value) {
  const raw = String(value || "").trim().toLowerCase();
  const target = SECTION_ALIASES[raw] || raw;
  return isKnownSection(target) ? target : "";
}

export function getSectionOrDefault(sectionId) {
  return SECTION_BY_ID[sectionId] || SECTION_BY_ID[DEFAULT_SECTION_ID];
}
