function resolveLocale(locale) {
  const normalized = String(locale || "es").trim().toLowerCase();
  return VEHICLE_CATEGORY_LABELS[normalized] ? normalized : "en";
}

function localizeVehicleCategory(entry, locale) {
  const labels = VEHICLE_CATEGORY_LABELS[resolveLocale(locale)] || VEHICLE_CATEGORY_LABELS.en;
  return {
    ...entry,
    label: labels[entry.id] || entry.label,
  };
}

export const MAP_VEHICLE_CATEGORIES = BASE_MAP_VEHICLE_CATEGORIES;
export const MAP_VEHICLE_CATEGORY_BY_ID = new Map(MAP_VEHICLE_CATEGORIES.map((entry) => [entry.id, entry]));

export const getMapVehicleCategories = (locale = "es") =>
  BASE_MAP_VEHICLE_CATEGORIES.map((entry) => localizeVehicleCategory(entry, locale));

export const getMapVehicleCategoryMeta = (categoryId, locale = "es") => {
  const entry = MAP_VEHICLE_CATEGORY_BY_ID.get(String(categoryId || "").trim());
  return entry ? localizeVehicleCategory(entry, locale) : null;
};

export const matchVehicleCategory = (rawValue) => {
  const normalizedRaw = normalizeText(rawValue);
  if (!normalizedRaw) return "";

  for (const category of MAP_VEHICLE_CATEGORIES) {
    const matched = category.keywords.some((keyword) => normalizedRaw.includes(normalizeText(keyword)));
    if (matched) return category.id;
  }

  return "";
};
