import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App.jsx";
import { initSentry, SentryErrorBoundary } from "./shared/monitoring/sentry.js";
import "./styles.css";

initSentry();

ReactDOM.createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <SentryErrorBoundary fallback={<div style={{ padding: 24 }}>Algo fallo. Recarga la pagina.</div>}>
      <App />
    </SentryErrorBoundary>
  </React.StrictMode>,
);

requestAnimationFrame(() => {
  requestAnimationFrame(() => {
    window.dispatchEvent(new Event("btr:app-ready"));
  });
});
