import React, { useMemo, useState } from "react";

function normalizeSearch(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function summarizeSelection(value, options, placeholder, selectionMode) {
  if (selectionMode === "single") {
    const selectedValue = String(value || "").trim();
    if (!selectedValue) return placeholder;
    const found = options.find((entry) => entry.value === selectedValue);
    return found?.label || selectedValue;
  }

  const values = Array.isArray(value) ? value : [];
  if (!values.length) return placeholder;

  const labelMap = new Map(options.map((entry) => [entry.value, entry.label]));
  const labels = values.map((entry) => labelMap.get(entry) || entry).filter(Boolean);
  if (labels.length <= 2) return labels.join(", ");
  return `${labels[0]}, ${labels[1]} +${labels.length - 2}`;
}

export function OptionDisclosure({
  label,
  value,
  options,
  placeholder,
  searchable = false,
  allowCustom = false,
  selectionMode = "multi",
  onChange,
}) {
  const [search, setSearch] = useState("");
  const selectedValues = selectionMode === "single"
    ? []
    : Array.isArray(value)
      ? value
      : [];
  const selectedValue = selectionMode === "single" ? String(value || "").trim() : "";
  const normalizedSearch = normalizeSearch(search);
  const trimmedSearch = String(search || "").trim();

  const filteredOptions = useMemo(() => {
    if (!normalizedSearch) return options;
    return options.filter((entry) => normalizeSearch(entry.label).includes(normalizedSearch));
  }, [normalizedSearch, options]);

  const normalizedSelectedValues = useMemo(
    () =>
      new Set(
        (selectionMode === "single" ? [selectedValue] : selectedValues)
          .map((entry) => normalizeSearch(entry))
          .filter(Boolean),
      ),
    [selectedValue, selectedValues, selectionMode],
  );

  const canAddCustom =
    allowCustom &&
    trimmedSearch &&
    !options.some((entry) => normalizeSearch(entry.value) === normalizeSearch(trimmedSearch)) &&
    !normalizedSelectedValues.has(normalizeSearch(trimmedSearch));

  const toggleValue = (entryValue) => {
    if (selectionMode === "single") {
      onChange(selectedValue === entryValue ? "" : entryValue);
      return;
    }

    const exists = selectedValues.includes(entryValue);
    if (exists) {
      onChange(selectedValues.filter((entry) => entry !== entryValue));
      return;
    }
    onChange([...selectedValues, entryValue]);
  };

  return (
    <details className="editor-multi-select">
      <summary className="editor-multi-select__summary">
        <span>{label}</span>
        <strong>{summarizeSelection(value, options, placeholder, selectionMode)}</strong>
      </summary>
      <div className="editor-multi-select__panel">
        {searchable ? (
          <label className="profile-settings__field editor-multi-select__search">
            <span>Buscar</span>
            <input value={search} onChange={(event) => setSearch(event.target.value)} />
          </label>
        ) : null}

        <div className="editor-multi-select__actions">
          <button
            type="button"
            className="ghost-btn"
            onClick={() => onChange(selectionMode === "single" ? "" : [])}
          >
            Limpiar
          </button>
          {canAddCustom ? (
            <button
              type="button"
              className="ghost-btn ghost-btn--accent"
              onClick={() => {
                onChange(selectionMode === "single" ? trimmedSearch : [...selectedValues, trimmedSearch]);
                setSearch("");
              }}
            >
              Anadir "{trimmedSearch}"
            </button>
          ) : null}
        </div>

        <div className="editor-multi-select__options">
          {filteredOptions.map((entry) => {
            const checked = selectionMode === "single"
              ? selectedValue === entry.value
              : selectedValues.includes(entry.value);

            return (
              <label key={`${label}-${entry.value}`} className="editor-multi-select__option">
                <input
                  type={selectionMode === "single" ? "radio" : "checkbox"}
                  checked={checked}
                  onChange={() => toggleValue(entry.value)}
                />
                <span>{entry.label}</span>
              </label>
            );
          })}
          {!filteredOptions.length ? <p className="editor-multi-select__empty">Sin resultados.</p> : null}
        </div>
      </div>
    </details>
  );
}
