import React, { useMemo } from "react";

function getUniqueBrands(item) {
  const raw = Array.isArray(item?.tags?.brands) ? item.tags.brands : [];
  const seen = new Set();
  const values = [];

  for (const entry of raw) {
    const brand = String(entry || "").trim();
    if (!brand) continue;
    const key = brand.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    values.push(brand);
  }

  return values;
}

export function MapPlaceBrandTags({ item, className = "", includeLabel = false, max = 6 }) {
  const brands = useMemo(() => getUniqueBrands(item), [item]);

  if (item?.tribe !== "restauradores") return null;
  if (!brands.length) return null;

  const normalizedMax = Number.isFinite(Number(max)) ? Math.max(1, Number(max)) : brands.length;
  const visibleBrands = brands.slice(0, normalizedMax);
  const hiddenCount = brands.length - visibleBrands.length;
  const rootClass = className ? `map-brand-tags ${className}` : "map-brand-tags";

  return (
    <div className={rootClass} aria-label="Marcas con las que trabaja">
      {includeLabel ? <span className="map-brand-tags__label">Marcas</span> : null}
      <div className="map-brand-tags__list">
        {visibleBrands.map((brand, index) => (
          <span key={`${brand.toLowerCase()}-${index}`} className="map-brand-tag">
            {brand}
          </span>
        ))}
        {hiddenCount > 0 ? <span className="map-brand-tag map-brand-tag--muted">+{hiddenCount}</span> : null}
      </div>
    </div>
  );
}
