import React from "react";
import { X } from "lucide-react";
import { CountryFlag } from "./CountryFlag.jsx";
import { CompanyLogoSlot } from "./CompanyLogoSlot.jsx";
import { MapPlaceBrandTags } from "./MapPlaceBrandTags.jsx";
import { MapPlaceSwapistaTags } from "./MapPlaceSwapistaTags.jsx";
import { MapPlaceVehicleCategoryTags } from "./MapPlaceVehicleCategoryTags.jsx";
import { getWorldCountryByName } from "../../features/mapShell/countries.js";
import { ProfessionIcon } from "../../features/mapShell/professionIcons.jsx";
import { getMapProfessionMeta } from "../../features/mapShell/professions.js";
import { getMapShopCategoryMeta } from "../../features/mapShell/shopCategories.js";
import { getSwapistaValueLabel, isSwapistaTribe, SWAPISTA_FIELD_DEFS } from "../../features/mapShell/swapistas.js";
import { TribeIcon } from "../../features/mapShell/tribeIcons.jsx";
import { getMapTribeMeta } from "../../features/mapShell/tribes.js";
import { getMapVehicleCategoryMeta } from "../../features/mapShell/vehicleCategories.js";
import { resolveCoreApiUiMessage } from "../../lib/coreApiConfig.js";
import { useChromeI18n } from "../../shared/i18n/i18n.jsx";

function ActiveFilterChip({ chip }) {
  return (
    <span className="map-active-filter-chip">
      <span className="map-active-filter-chip__content">
        <span className="map-active-filter-chip__prefix">{chip.prefix}</span>
        {chip.countryCode ? (
          <CountryFlag
            countryCode={chip.countryCode}
            className="map-active-filter-chip__flag"
            title={chip.label}
          />
        ) : null}
        {chip.icon ? <span className="map-active-filter-chip__icon">{chip.icon}</span> : null}
        <span className="map-active-filter-chip__value">{chip.label}</span>
      </span>
      <button
        type="button"
        className="map-active-filter-chip__remove"
        aria-label={`Quitar filtro ${chip.prefix} ${chip.label}`}
        onClick={chip.onRemove}
      >
        <X size={12} strokeWidth={2.2} aria-hidden="true" />
      </button>
    </span>
  );
}

export function MapShellContextPanel({ state }) {
  const { t, locale } = useChromeI18n();
  const uiError = resolveCoreApiUiMessage(state.error, locale);
  const selectedCountry = getWorldCountryByName(state.country);
  const selectedProfession = getMapProfessionMeta(state.profession, locale);
  const selectedShopCategory = getMapShopCategoryMeta(state.shopCategory, locale);
  const selectedVehicleCategory = getMapVehicleCategoryMeta(state.vehicleCategory, locale);
  const swapistaFilterChips = isSwapistaTribe(state.tribe)
    ? SWAPISTA_FIELD_DEFS.flatMap((field) => {
        const rawValue = state.tribeFilters?.[field.id];
        const selectedValues = field.selectionMode === "single"
          ? [String(rawValue || "").trim()].filter(Boolean)
          : Array.isArray(rawValue)
            ? rawValue.filter(Boolean)
            : [];

        return selectedValues.map((entry) => ({
          id: `${field.id}-${entry}`,
          prefix: field.label,
          label: getSwapistaValueLabel(field.id, entry),
          onRemove: () => {
            if (field.selectionMode === "single") {
              state.setTribeFilter(field.id, "");
              return;
            }
            state.setTribeFilter(
              field.id,
              selectedValues.filter((value) => value !== entry),
            );
          },
        }));
      })
    : [];

  const activeFilters = [
    state.country
      ? {
          id: "country",
          prefix: t("common.country", "Pais"),
          label: state.country,
          countryCode: selectedCountry?.code || "",
          onRemove: () => state.setCountry(""),
        }
      : null,
    selectedVehicleCategory
      ? {
          id: "vehicleCategory",
          prefix: t("common.vehicle", "Vehiculo"),
          label: selectedVehicleCategory.label,
          icon: selectedVehicleCategory.icon,
          onRemove: () => state.setVehicleCategory(""),
        }
      : null,
    state.brand
      ? {
          id: "brand",
          prefix: t("common.brand", "Marca"),
          label: state.brand,
          onRemove: () => state.setBrand(""),
        }
      : null,
    state.model
      ? {
          id: "model",
          prefix: t("common.model", "Modelo"),
          label: state.model,
          onRemove: () => state.setModel(""),
        }
      : null,
    selectedProfession
      ? {
          id: "profession",
          prefix: t("map.profession", "Oficio"),
          label: selectedProfession.label,
          icon: <ProfessionIcon professionId={selectedProfession.iconId || selectedProfession.id} size={14} />,
          onRemove: () => state.setProfession(""),
        }
      : null,
    selectedShopCategory
      ? {
          id: "shopCategory",
          prefix: t("map.shopSubcategory", "Subcategoria de tienda"),
          label: selectedShopCategory.label,
          icon: selectedShopCategory.icon,
          onRemove: () => state.setShopCategory(""),
        }
      : null,
    state.search.trim()
      ? {
          id: "search",
          prefix: t("common.search", "Buscar"),
          label: state.search.trim(),
          onRemove: () => state.setSearch(""),
        }
      : null,
    ...swapistaFilterChips,
  ].filter(Boolean);

  return (
    <section className="map-panel map-panel--selection map-panel--results">
      <header className={`map-panel__header ${activeFilters.length ? "map-panel__header--with-filters" : ""}`}>
        <div className="map-panel__header-copy">
          <p className="map-panel__eyebrow">{t("common.results", "Resultados")}</p>
          <h2 className="map-panel__title">{t("common.filteredPlaces", "Lugares filtrados")}</h2>
        </div>
        <span className="results-count">{state.filteredItems.length}</span>
        {activeFilters.length ? (
          <div className="map-active-filters" aria-label="Filtros activos">
            {activeFilters.map((chip) => (
              <ActiveFilterChip key={chip.id} chip={chip} />
            ))}
          </div>
        ) : null}
      </header>

      {uiError ? <div className="map-status-box__error">{uiError}</div> : null}
      {state.loading ? <p className="results-state">{t("common.loadingResults", "Cargando resultados...")}</p> : null}
      {!state.loading && !state.filteredItems.length ? (
        <p className="results-state">{t("common.noResults", "No hay resultados con los filtros actuales.")}</p>
      ) : null}

      <div className="results-list map-sidebar-results__list" role="list">
        {state.filteredItems.map((entry) => {
          const tribe = getMapTribeMeta(entry.tribe, locale);
          return (
            <button
              key={entry.id}
              type="button"
              role="listitem"
              className={`result-row ${entry.id === state.selectedItemId ? "is-active" : ""}`}
              onClick={() => state.setSelectedItemId(entry.id)}
            >
              <span className="result-row__head">
                <CompanyLogoSlot
                  logoUrl={entry.logoUrl}
                  fallbackIcon={<TribeIcon tribeId={tribe.iconId || tribe.id} className="company-logo-slot__glyph-icon" size={14} />}
                  sizeClass="company-logo-slot--sm"
                  title={entry.name}
                />
                <span className="result-row__main">
                  <span className="result-row__name">
                    <span>{entry.name}</span>
                  </span>
                  <span className="result-row__meta">
                    <span className="map-country-inline">
                      <CountryFlag
                        countryCode={entry.countryCode}
                        className="map-country-flag map-country-flag--sm"
                        title={entry.country || entry.countryCode}
                      />
                      <span>{[entry.city, entry.country].filter(Boolean).join(", ") || t("map.noLocation", "Sin ubicacion")}</span>
                    </span>
                  </span>
                </span>
              </span>
              <MapPlaceBrandTags item={entry} className="map-brand-tags--result" max={4} />
              <MapPlaceSwapistaTags item={entry} className="map-swapista-tags--result" max={3} />
              <MapPlaceVehicleCategoryTags
                item={entry}
                className="map-vehicle-category-tags--result"
                max={3}
              />
              {entry.description ? <span className="result-row__desc">{entry.description}</span> : null}
            </button>
          );
        })}
      </div>
    </section>
  );
}
