import React, { useMemo } from "react";
import { getMapTribes, normalizeMapTribeId } from "../../features/mapShell/tribes.js";
import { isSwapistaTribe, SWAPISTA_FIELD_DEFS } from "../../features/mapShell/swapistas.js";
import { useChromeI18n } from "../../shared/i18n/i18n.jsx";
import { OptionDisclosure } from "./OptionDisclosure.jsx";

const EDITOR_TRIBE_IDS = new Set(["restauradores", "swapistas", "desguaces", "services", "shops"]);

function EditorSection({ eyebrow, title, children, actions = null }) {
  return (
    <section className="editor-section">
      <div className="editor-section__header">
        <div>
          <p className="map-panel__eyebrow">{eyebrow}</p>
          <h4 className="editor-section__title">{title}</h4>
        </div>
        {actions}
      </div>
      <div className="selection-editor__grid">{children}</div>
    </section>
  );
}

function renderSwapistaField(field, draft, swapistaOptionsByField, onFieldChange) {
  return (
    <div key={field.id} className="selection-editor__field--wide">
      <OptionDisclosure
        label={field.label}
        value={draft[field.id]}
        options={swapistaOptionsByField[field.id] || field.options}
        placeholder={field.placeholder}
        searchable={field.searchable}
        allowCustom={field.allowCustom}
        selectionMode={field.selectionMode}
        onChange={(value) => onFieldChange(field.id, value)}
      />
    </div>
  );
}

export function MapShellSelectionEditor({
  draft,
  saving,
  error,
  locationPickerActive,
  vehicleCategoryOptions,
  brandOptions,
  tribeContentOptions,
  tribeContentLabel,
  tribeContentPlaceholder,
  tribeContentAllowCustom,
  swapistaOptionsByField = {},
  onFieldChange,
  onToggleLocationPicker,
  onCancel,
  onSave,
}) {
  const { locale } = useChromeI18n();
  const tribeOptions = useMemo(
    () => getMapTribes(locale).filter((entry) => EDITOR_TRIBE_IDS.has(normalizeMapTribeId(entry.id))),
    [locale],
  );
  const editingSwapista = isSwapistaTribe(draft.tribe);

  return (
    <form
      className="selection-editor"
      onSubmit={(event) => {
        event.preventDefault();
        onSave();
      }}
    >
      <div className="selection-admin-note">
        {locationPickerActive
          ? "Modo seleccion de coordenadas activo. Haz clic en el mapa para actualizar latitud y longitud."
          : "Pin seed super admin. Puedes publicar el punto manualmente o elegir coordenadas haciendo clic en el mapa."}
      </div>
      {error ? <div className="map-status-box__error">{error}</div> : null}

      <EditorSection eyebrow="General" title="Informacion general">
        <label className="profile-settings__field">
          <span>Nombre</span>
          <input value={draft.name} onChange={(event) => onFieldChange("name", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Tribu</span>
          <select value={draft.tribe} onChange={(event) => onFieldChange("tribe", event.target.value)}>
            {tribeOptions.map((tribe) => (
              <option key={tribe.id} value={tribe.id}>
                {tribe.label}
              </option>
            ))}
          </select>
        </label>

        <label className="profile-settings__field">
          <span>Contacto principal</span>
          <input value={draft.contactName} onChange={(event) => onFieldChange("contactName", event.target.value)} />
        </label>

        <label className="profile-settings__field selection-editor__field--wide">
          <span>Descripcion corta</span>
          <textarea
            rows={3}
            value={draft.shortDescription}
            onChange={(event) => onFieldChange("shortDescription", event.target.value)}
          />
        </label>

        <label className="profile-settings__field selection-editor__field--wide">
          <span>Descripcion larga</span>
          <textarea
            rows={5}
            value={draft.longDescription}
            onChange={(event) => onFieldChange("longDescription", event.target.value)}
          />
        </label>
      </EditorSection>

      <EditorSection
        eyebrow="Localizacion"
        title="Ubicacion"
        actions={
          <button type="button" className="ghost-btn ghost-btn--accent" onClick={onToggleLocationPicker}>
            {locationPickerActive ? "Cancelar click mapa" : "Seleccionar en mapa"}
          </button>
        }
      >
        <label className="profile-settings__field">
          <span>Pais</span>
          <input value={draft.country} onChange={(event) => onFieldChange("country", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Codigo pais</span>
          <input
            value={draft.countryCode}
            onChange={(event) => onFieldChange("countryCode", event.target.value.toUpperCase())}
            maxLength={2}
          />
        </label>

        <label className="profile-settings__field">
          <span>Region / estado</span>
          <input value={draft.region} onChange={(event) => onFieldChange("region", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Ciudad</span>
          <input value={draft.city} onChange={(event) => onFieldChange("city", event.target.value)} />
        </label>

        <label className="profile-settings__field selection-editor__field--wide">
          <span>Direccion</span>
          <input value={draft.address} onChange={(event) => onFieldChange("address", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Codigo postal</span>
          <input value={draft.postalCode} onChange={(event) => onFieldChange("postalCode", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Zona de cobertura</span>
          <input value={draft.coverage} onChange={(event) => onFieldChange("coverage", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Precision</span>
          <select value={draft.precision} onChange={(event) => onFieldChange("precision", event.target.value)}>
            <option value="point">point</option>
            <option value="buffer">buffer</option>
            <option value="city">city</option>
            <option value="country">country</option>
          </select>
        </label>

        <div className="selection-editor__field--wide selection-editor__grid selection-editor__grid--compact">
          <label className="profile-settings__field">
            <span>Latitud</span>
            <input value={draft.lat} onChange={(event) => onFieldChange("lat", event.target.value)} />
          </label>

          <label className="profile-settings__field">
            <span>Longitud</span>
            <input value={draft.lng} onChange={(event) => onFieldChange("lng", event.target.value)} />
          </label>

          <label className="profile-settings__field">
            <span>Radio km</span>
            <input
              value={draft.bufferKm}
              onChange={(event) => onFieldChange("bufferKm", event.target.value)}
              disabled={draft.precision !== "buffer"}
            />
          </label>
        </div>
      </EditorSection>

      <EditorSection eyebrow="Contacto" title="Contacto y redes">
        <label className="profile-settings__field">
          <span>Web</span>
          <input value={draft.website} onChange={(event) => onFieldChange("website", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Instagram</span>
          <input value={draft.instagram} onChange={(event) => onFieldChange("instagram", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Facebook</span>
          <input value={draft.facebook} onChange={(event) => onFieldChange("facebook", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>YouTube</span>
          <input value={draft.youtube} onChange={(event) => onFieldChange("youtube", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>LinkedIn</span>
          <input value={draft.linkedin} onChange={(event) => onFieldChange("linkedin", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>TikTok</span>
          <input value={draft.tiktok} onChange={(event) => onFieldChange("tiktok", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>WhatsApp</span>
          <input value={draft.whatsapp} onChange={(event) => onFieldChange("whatsapp", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Email</span>
          <input value={draft.email} onChange={(event) => onFieldChange("email", event.target.value)} />
        </label>

        <label className="profile-settings__field">
          <span>Telefono</span>
          <input value={draft.phone} onChange={(event) => onFieldChange("phone", event.target.value)} />
        </label>
      </EditorSection>

      {editingSwapista ? (
        <>
          <EditorSection eyebrow="Especializacion" title="Especializacion swap">
            {SWAPISTA_FIELD_DEFS.filter((field) => ["swapCategories", "swapTypes", "workshopLevel"].includes(field.id)).map(
              (field) => renderSwapistaField(field, draft, swapistaOptionsByField, onFieldChange),
            )}
          </EditorSection>

          <EditorSection eyebrow="Vehiculos" title="Vehiculos y motores">
            {SWAPISTA_FIELD_DEFS.filter((field) => ["vehicleTypes", "vehicleUses", "vehiclePlatforms", "engines"].includes(field.id)).map(
              (field) => renderSwapistaField(field, draft, swapistaOptionsByField, onFieldChange),
            )}
          </EditorSection>

          <EditorSection eyebrow="Servicios" title="Servicios y electronica">
            {SWAPISTA_FIELD_DEFS.filter((field) => ["workshopServices", "electronics"].includes(field.id)).map(
              (field) => renderSwapistaField(field, draft, swapistaOptionsByField, onFieldChange),
            )}
          </EditorSection>

          <EditorSection eyebrow="Productos" title="Productos y fabricacion">
            {SWAPISTA_FIELD_DEFS.filter((field) => ["fabricationProducts"].includes(field.id)).map(
              (field) => renderSwapistaField(field, draft, swapistaOptionsByField, onFieldChange),
            )}
          </EditorSection>
        </>
      ) : (
        <EditorSection eyebrow="Clasificacion" title="Taxonomia del pin">
          <div className="selection-editor__field--wide">
            <OptionDisclosure
              label="Categorias de vehiculo"
              value={draft.categories}
              options={vehicleCategoryOptions}
              placeholder="Seleccionar categorias"
              onChange={(value) => onFieldChange("categories", value)}
            />
          </div>

          <div className="selection-editor__field--wide">
            <OptionDisclosure
              label="Marcas"
              value={draft.brands}
              options={brandOptions}
              placeholder="Seleccionar marcas"
              searchable
              onChange={(value) => onFieldChange("brands", value)}
            />
          </div>

          <label className="profile-settings__field selection-editor__field--wide">
            <span>Modelos</span>
            <input value={draft.models} onChange={(event) => onFieldChange("models", event.target.value)} />
          </label>

          <div className="selection-editor__field--wide">
            <OptionDisclosure
              label={tribeContentLabel}
              value={draft.contentTags}
              options={tribeContentOptions}
              placeholder={tribeContentPlaceholder}
              searchable
              allowCustom={tribeContentAllowCustom}
              onChange={(value) => onFieldChange("contentTags", value)}
            />
          </div>
        </EditorSection>
      )}

      <EditorSection eyebrow="Estado" title="Publicacion / estado">
        <label className="selection-editor__toggle">
          <input
            type="checkbox"
            checked={draft.verified}
            onChange={(event) => onFieldChange("verified", event.target.checked)}
          />
          <span>Verificado</span>
        </label>

        <label className="selection-editor__toggle">
          <input
            type="checkbox"
            checked={draft.featured}
            onChange={(event) => onFieldChange("featured", event.target.checked)}
          />
          <span>Destacado</span>
        </label>

        <label className="selection-editor__toggle">
          <input
            type="checkbox"
            checked={draft.published}
            onChange={(event) => onFieldChange("published", event.target.checked)}
          />
          <span>Publicado</span>
        </label>

        <label className="profile-settings__field">
          <span>Fuente de datos</span>
          <input value={draft.dataSource} onChange={(event) => onFieldChange("dataSource", event.target.value)} />
        </label>

        <label className="profile-settings__field selection-editor__field--wide">
          <span>Notas internas</span>
          <textarea
            rows={3}
            value={draft.internalNotes}
            onChange={(event) => onFieldChange("internalNotes", event.target.value)}
          />
        </label>
      </EditorSection>

      <div className="selection-editor__actions">
        <button type="button" className="ghost-btn" onClick={onCancel} disabled={saving}>
          Cancelar
        </button>
        <button type="submit" className="ghost-btn ghost-btn--accent" disabled={saving}>
          {saving ? "Guardando..." : "Guardar"}
        </button>
      </div>
    </form>
  );
}
