function iconFor(sectionId) {
  switch (sectionId) {
    case "map":
      return MapPinned;
    case "marketplace":
      return Store;
    case "garagex":
      return CarFront;
    case "worker":
      return Wrench;
    case "calendar":
      return CalendarDays;
    case "settings":
      return Settings;
    default:
      return LayoutPanelLeft;
  }
}

