function countSelectedFilterValues(value) {
  if (Array.isArray(value)) return value.filter(Boolean).length;
  return value ? 1 : 0;
}

function countActiveSwapistaFilters(tribeFilters = {}) {
  return Object.values(tribeFilters).reduce((total, value) => total + countSelectedFilterValues(value), 0);
}

function getMobileMapDockBadges(state) {
  const vehicleFilters =
    countSelectedFilterValues(state.vehicleCategory)
    + countSelectedFilterValues(state.brand)
    + countSelectedFilterValues(state.model);

  const quickTribeFilters =
    (state.tribe && state.tribe !== DEFAULT_MAP_TRIBE ? 1 : 0)
    + countSelectedFilterValues(state.profession)
    + countSelectedFilterValues(state.shopCategory)
    + countActiveSwapistaFilters(state.tribeFilters);

  return {
    "map-tribe": quickTribeFilters,
    "map-vehicle": vehicleFilters,
    "map-country": countSelectedFilterValues(state.country),
    "map-search": countSelectedFilterValues(state.search),
  };
}

function getQuickTribeBadgeCount(state, tribeId) {
  let total = 0;

  if (state.tribe === tribeId && tribeId !== DEFAULT_MAP_TRIBE) {
    total += 1;
  }

  if (tribeId === "services") {
    total += countSelectedFilterValues(state.profession);
  }

  if (tribeId === "shops") {
    total += countSelectedFilterValues(state.shopCategory);
  }

  if (tribeId === "swapistas" && state.tribe === "swapistas") {
    total += countActiveSwapistaFilters(state.tribeFilters);
  }

  return total;
}

function applyMobileMapTribeSelection(state, tribeId) {
  state.setTribe(tribeId);
  state.setSelectedItemId("");

  if (tribeId !== "services" && state.profession) {
    state.setProfession("");
  }

  if (tribeId !== "shops" && state.shopCategory) {
    state.setShopCategory("");
  }

  if (isSwapistaTribe(tribeId)) {
    state.setVehicleCategory("");
    state.setBrand("");
    state.setModel("");
  }
}

function hasDedicatedMobileMapTribeFilters(tribeId) {
  return tribeId === "services" || tribeId === "shops" || isSwapistaTribe(tribeId);
}

function useIsMobile() {
  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== "undefined" ? window.matchMedia("(max-width: 900px)").matches : false,
  );

  useEffect(() => {
    const media = window.matchMedia("(max-width: 900px)");
    const onChange = () => setIsMobile(media.matches);
    media.addEventListener("change", onChange);
    onChange();
    return () => media.removeEventListener("change", onChange);
  }, []);

  return isMobile;
}

function useActiveSection() {
  const [activeSectionId, setActiveSectionId] = useState(() =>
    typeof window === "undefined" ? DEFAULT_SECTION_ID : readSectionFromLocation(window.location),
  );

  useEffect(() => {
    const applyLocation = ({ replace = false } = {}) => {
      const nextSectionId = typeof window === "undefined" ? DEFAULT_SECTION_ID : readSectionFromLocation(window.location);
      setActiveSectionId(nextSectionId);
      normalizeSectionLocation(nextSectionId, { replace });
    };

    applyLocation({ replace: true });

    const onLocationChange = () => applyLocation();
    window.addEventListener("popstate", onLocationChange);
    window.addEventListener("hashchange", onLocationChange);

    return () => {
      window.removeEventListener("popstate", onLocationChange);
      window.removeEventListener("hashchange", onLocationChange);
    };
  }, []);

  const navigate = (sectionId) => {
    if (!isKnownSection(sectionId)) return;
    setActiveSectionId(sectionId);
    syncSectionLocation(sectionId);
  };

  return [activeSectionId, navigate];
}

function useElementHeight() {
  const ref = useRef(null);
  const [height, setHeight] = useState(0);

  useEffect(() => {
    const node = ref.current;
    if (!node) return undefined;

    const update = () => {
      setHeight(Math.ceil(node.getBoundingClientRect().height));
    };

    update();
    window.addEventListener("resize", update);

    if (typeof ResizeObserver === "undefined") {
      return () => window.removeEventListener("resize", update);
    }

    const observer = new ResizeObserver(update);
    observer.observe(node);

    return () => {
      observer.disconnect();
      window.removeEventListener("resize", update);
    };
  }, []);

  return [ref, height];
}

function normalizeRoleToken(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[\s_]+/g, "-");
}

function listTokens(value) {
  if (Array.isArray(value)) return value.map(normalizeRoleToken).filter(Boolean);
  if (typeof value === "string") return [normalizeRoleToken(value)].filter(Boolean);
  return [];
}

function readObject(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return value;
}

function readString(value) {
  if (typeof value !== "string") return "";
  return value.trim();
}

function resolveSessionCountry(session) {
  if (!session || session.status !== "ready") return "";

  const me = readObject(session.me);
  const subject = readObject(session.subject);
  const user = readObject(session.user);
  const userGeo = readObject(me.userGeo);
  const claims = readObject(subject.claims || user.claims);
  const location = readObject(claims.location);
  const address = readObject(claims.address);

  const countryNameCandidates = [
    userGeo.country,
    subject.country,
    user.country,
    claims.country,
    claims.countryName,
    claims.country_name,
    location.country,
    location.countryName,
    address.country,
    address.countryName,
  ];
  for (const entry of countryNameCandidates) {
    const value = readString(entry);
    if (!value) continue;
    const country = getWorldCountryByName(value);
    if (country) return country.name;
  }

  const countryCodeCandidates = [
    userGeo.countryCode,
    subject.countryCode,
    user.countryCode,
    claims.countryCode,
    claims.country_code,
    claims.countryISO2,
    claims.country_iso2,
    claims.cc,
    location.countryCode,
    location.country_code,
    location.countryISO2,
    address.countryCode,
    address.country_code,
    address.countryISO2,
  ];
  for (const entry of countryCodeCandidates) {
    const value = readString(entry).toUpperCase();
    if (!value) continue;
    const country = getWorldCountryByCode(value);
    if (country) return country.name;
  }

  return "";
}

function hasSuperAdminMapAccess(session) {
  const me = readObject(session?.me);
  const user = readObject(session?.user);
  const subject = readObject(session?.subject);
  const authz = readObject(me.authz || session?.authz);
  const claims = readObject(subject.claims || user.claims);

  if (Array.isArray(authz.permissions) && authz.permissions.includes("*")) return true;

  const booleanFlags = [
    claims.admin,
    claims.isAdmin,
    claims.superAdmin,
    claims.super_admin,
    claims.isSuperAdmin,
  ];
  if (booleanFlags.some((value) => value === true)) return true;

  const roleBuckets = [
    ...listTokens(user.role),
    ...listTokens(user.roles),
    ...listTokens(subject.role),
    ...listTokens(subject.roles),
    ...listTokens(claims.role),
    ...listTokens(claims.roles),
    ...listTokens(claims.scopes),
    ...listTokens(authz.role),
    ...listTokens(authz.roles),
    ...listTokens(authz.scopes),
  ];

  return roleBuckets.some((token) => token === "admin" || token === "superadmin" || token === "super-admin");
}

const PROFILE_PREFS_STORAGE_KEY = "btr_chrome_profile_prefs_v1";
const DEFAULT_PROFILE_PREFS = {
  language: resolveInitialLocale("es"),
  subscription: "motors-pro",
  notifications: {
    push: true,
    email: true,
    workAlerts: true,
  },
};

function readProfilePrefs() {
  if (typeof window === "undefined") return DEFAULT_PROFILE_PREFS;
  try {
    const raw = window.localStorage.getItem(PROFILE_PREFS_STORAGE_KEY);
    if (!raw) return DEFAULT_PROFILE_PREFS;
    const parsed = JSON.parse(raw);
    return {
      ...DEFAULT_PROFILE_PREFS,
      ...parsed,
      language: normalizeLocale(parsed?.language) || DEFAULT_PROFILE_PREFS.language,
      notifications: {
        ...DEFAULT_PROFILE_PREFS.notifications,
        ...(parsed?.notifications || {}),
      },
    };
  } catch {
    return DEFAULT_PROFILE_PREFS;
  }
}

function useProfilePreferences() {
  const [prefs, setPrefs] = useState(readProfilePrefs);

  useEffect(() => {
    try {
      window.localStorage.setItem(PROFILE_PREFS_STORAGE_KEY, JSON.stringify(prefs));
    } catch {
      // noop
    }
  }, [prefs]);

  const updatePrefs = (nextPartial) => {
    setPrefs((current) => ({
      ...current,
      ...nextPartial,
      language: normalizeLocale(nextPartial.language) || current.language,
      notifications: {
        ...current.notifications,
        ...(nextPartial.notifications || {}),
      },
    }));
  };

  return [prefs, updatePrefs];
}

function hasWorkerProfileAccess(session) {
  if (!session || session.status !== "ready") return false;

  const me = session.me || {};
  const user = session.user || {};
  const subject = session.subject || {};
  const authz = me.authz || {};
  const claims = subject.claims || user.claims || {};

  if (me.worker?.enabled || me.worker?.registered || me.labWorker?.enabled || me.labWorker?.registered) {
    return true;
  }

  const booleanFlags = [
    claims.worker,
    claims.isWorker,
    claims.labWorker,
    claims.lab_worker,
    user.isWorker,
    user.workerEnabled,
    user.labWorkerEnabled,
    me.isWorker,
    me.workerEnabled,
  ];
  if (booleanFlags.some((value) => value === true)) return true;

  const tokenBuckets = [
    ...listTokens(user.role),
    ...listTokens(user.roles),
    ...listTokens(subject.role),
    ...listTokens(subject.roles),
    ...listTokens(claims.role),
    ...listTokens(claims.roles),
    ...listTokens(authz.role),
    ...listTokens(authz.roles),
    ...listTokens(authz.scopes),
    ...listTokens(me.profiles),
    ...listTokens(me.capabilities),
    ...(session.memberships || []).flatMap((membership) => [
      normalizeRoleToken(membership?.scope),
      normalizeRoleToken(membership?.role),
      normalizeRoleToken(membership?.type),
      normalizeRoleToken(membership?.profile),
    ]),
  ].filter(Boolean);

  return tokenBuckets.some(
    (token) =>
      token === "worker" ||
      token === "lab-worker" ||
      token === "beterano-lab-worker" ||
      token.startsWith("worker-") ||
      token.startsWith("lab-worker") ||
      token.includes(":worker") ||
      token.includes("-worker"),
  );
}

function ProfileModeSwitcher({
  activeSectionId,
  canAccessWorkerProfile,
  onOpenSettings,
  onSwitchMode,
  session,
  variant = "desktop",
}) {
  const { t } = useChromeI18n();
  const [open, setOpen] = useState(false);
  const rootRef = useRef(null);
  const isWorkerMode = activeSectionId === "worker";
  const isDesktop = variant === "desktop";
  const isSettingsActive = activeSectionId === "settings";

  useEffect(() => {
    if (!open) return undefined;

    const onPointerDown = (event) => {
      if (!rootRef.current?.contains(event.target)) setOpen(false);
    };
    const onKeyDown = (event) => {
      if (event.key === "Escape") setOpen(false);
    };

    window.addEventListener("mousedown", onPointerDown);
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("mousedown", onPointerDown);
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  const switchMode = (mode) => {
    onSwitchMode(mode);
    setOpen(false);
  };

  const openSettings = () => {
    onOpenSettings?.();
    setOpen(false);
  };

  const wrapperClass = [
    "profile-switch",
    isDesktop ? "profile-switch--desktop" : "profile-switch--mobile",
    open ? "is-open" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={wrapperClass} ref={rootRef}>
      <button
        type="button"
        className={`profile-switch__button ${isWorkerMode ? "is-worker" : ""}`}
        title={isWorkerMode ? "Perfil activo: Beterano LAB Worker" : "Perfil activo: Beterano Motors"}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
      >
        <CircleUserRound size={16} />
      </button>

      {open ? (
        <div className="profile-switch__popover" role="menu" aria-label="Cambio de perfil">
          <div className="profile-switch__header">
            <p className="profile-switch__eyebrow">Perfil activo</p>
            <strong>{isWorkerMode ? "Beterano LAB Worker" : "Beterano Motors"}</strong>
            <span>{session.displayName}</span>
          </div>

          {!isDesktop ? (
            <button
              type="button"
              className={`profile-switch__item ${isSettingsActive ? "is-active" : ""}`}
              role="menuitem"
              onClick={openSettings}
            >
              <Settings size={14} />
              <span>
                <strong>{t("common.settings", "Settings")}</strong>
                <small>
                  {[
                    t("common.profile", "Profile"),
                    t("common.language", "Language"),
                    t("common.notifications", "Notifications"),
                  ].join(" · ")}
                </small>
              </span>
              {isSettingsActive ? <BadgeCheck size={14} /> : null}
            </button>
          ) : null}

          <button
            type="button"
            className={`profile-switch__item ${!isWorkerMode ? "is-active" : ""}`}
            role="menuitem"
            onClick={() => switchMode("motors")}
          >
            <LayoutPanelLeft size={14} />
            <span>
              <strong>Beterano Motors</strong>
              <small>Shell Motors (map, marketplace, garagex, calendar)</small>
            </span>
            {!isWorkerMode ? <BadgeCheck size={14} /> : null}
          </button>

          {canAccessWorkerProfile ? (
            <button
              type="button"
              className={`profile-switch__item ${isWorkerMode ? "is-active" : ""}`}
              role="menuitem"
              onClick={() => switchMode("worker")}
            >
              <Wrench size={14} />
              <span>
                <strong>Beterano LAB Worker</strong>
                <small>App de trabajo en taller y bolsa de trabajos</small>
              </span>
              {isWorkerMode ? <BadgeCheck size={14} /> : null}
            </button>
          ) : (
            <div className="profile-switch__hint">
              El perfil LAB Worker aparece cuando tu usuario tiene registro o rol worker.
            </div>
          )}
        </div>
      ) : null}
    </div>
  );
}

