// Per-tribe filter model for the mobile subdock:
// - swapistas: groups = swapista fields, options multi-select (state.tribeFilters)
// - services: groups = profession groups, options single-select (state.profession)
// - shops: flat single-select list (state.shopCategory), no group step
function getTribeFilterConfig(tribeId, locale) {
  if (isSwapistaTribe(tribeId)) {
    return {
      groups: SWAPISTA_FIELD_DEFS.map((field) => ({ id: field.id, label: field.label })),
      getOptions: (state, groupId) =>
        (state.availableSwapistaOptions?.[groupId] || []).map((option) => ({ id: option.value, label: option.label })),
      getSelected: (state, groupId) => {
        const value = state.tribeFilters?.[groupId];
        return Array.isArray(value) ? value : value ? [value] : [];
      },
      isMulti: (groupId) => SWAPISTA_FIELD_BY_ID.get(groupId)?.selectionMode !== "single",
      toggle: (state, groupId, optionId) => {
        const field = SWAPISTA_FIELD_BY_ID.get(groupId);
        if (field?.selectionMode === "single") {
          const current = state.tribeFilters?.[groupId] || "";
          state.setTribeFilter(groupId, current === optionId ? "" : optionId);
          return;
        }
        const current = Array.isArray(state.tribeFilters?.[groupId]) ? state.tribeFilters[groupId] : [];
        const next = current.includes(optionId)
          ? current.filter((entry) => entry !== optionId)
          : [...current, optionId];
        state.setTribeFilter(groupId, next);
      },
    };
  }

  if (tribeId === "services") {
    const groups = [];
    const seen = new Set();
    for (const profession of getMapProfessions(locale)) {
      if (seen.has(profession.group)) continue;
      seen.add(profession.group);
      groups.push({ id: profession.group, label: profession.group });
    }
    return {
      groups,
      getOptions: (_state, groupId) =>
        getMapProfessions(locale)
          .filter((profession) => profession.group === groupId)
          .map((profession) => ({ id: profession.id, label: profession.label })),
      getSelected: (state) => (state.profession ? [state.profession] : []),
      getSelectedLabel: (state) => (state.profession ? getMapProfessionMeta(state.profession, locale)?.label || "" : ""),
      isMulti: () => false,
      toggle: (state, _groupId, optionId) => state.setProfession(state.profession === optionId ? "" : optionId),
    };
  }

  if (tribeId === "shops") {
    return {
      flat: true,
      getOptions: (_state) => getMapShopCategories(locale).map((category) => ({ id: category.id, label: category.label })),
      getSelected: (state) => (state.shopCategory ? [state.shopCategory] : []),
      getSelectedLabel: (state) => {
        const category = getMapShopCategories(locale).find((entry) => entry.id === state.shopCategory);
        return category?.label || "";
      },
      isMulti: () => false,
      toggle: (state, _groupId, optionId) => state.setShopCategory(state.shopCategory === optionId ? "" : optionId),
    };
  }

  return null;
}

function MobileMapTribeSubdock({ state }) {
  const { t, locale } = useChromeI18n();
  const tribeId = state.tribe || DEFAULT_MAP_TRIBE;
  const selectedTribe = getMapTribeMeta(tribeId, locale);
  const config = useMemo(() => getTribeFilterConfig(tribeId, locale), [tribeId, locale]);
  const hasGroups = Boolean(config && !config.flat && config.groups?.length);
  const hasFilter = Boolean(config);

  const [expanded, setExpanded] = useState(null); // null | "tribe" | "group" | "filter"
  const [groupId, setGroupId] = useState(() => (hasGroups ? config.groups[0].id : ""));

  useEffect(() => {
    setExpanded(null);
    setGroupId(hasGroups ? config.groups[0].id : "");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tribeId]);

  const activeGroupId = hasGroups ? groupId : "";
  const groupLabel = hasGroups
    ? config.groups.find((group) => group.id === groupId)?.label || t("common.group", "Grupo")
    : "";
  const selectedInGroup = hasFilter ? config.getSelected(state, activeGroupId) : [];
  const filterMulti = hasFilter ? config.isMulti(activeGroupId) : false;

  let filterValueLabel = t("common.all", "Todas");
  if (hasFilter && filterMulti) {
    filterValueLabel = selectedInGroup.length ? `${selectedInGroup.length} sel.` : t("common.all", "Todas");
  } else if (hasFilter && selectedInGroup.length) {
    filterValueLabel =
      (config.getSelectedLabel && config.getSelectedLabel(state)) ||
      config.getOptions(state, activeGroupId).find((option) => option.id === selectedInGroup[0])?.label ||
      t("common.all", "Todas");
  }

  const toggleExpanded = (key) => setExpanded((current) => (current === key ? null : key));

  let cascade = null;
  if (expanded === "tribe") {
    cascade = <MobileMapTribeSelector state={state} onSelect={() => setExpanded(null)} />;
  } else if (expanded === "group" && hasGroups) {
    cascade = (
      <MobileMapOptionStack
        key="group"
        forceFrame
        options={config.groups}
        selectedId={groupId}
        ariaLabel={t("common.group", "Grupo")}
        onSelect={(id) => {
          setGroupId(id);
          setExpanded("filter");
        }}
      />
    );
  } else if (expanded === "filter" && hasFilter) {
    const options = config.getOptions(state, activeGroupId);
    cascade = (
      <MobileMapOptionStack
        key={`filter-${activeGroupId}`}
        forceFrame
        multi={filterMulti}
        options={options}
        selectedIds={filterMulti ? selectedInGroup : undefined}
        selectedId={filterMulti ? undefined : selectedInGroup[0]}
        ariaLabel={hasGroups ? groupLabel : t("common.filters", "Filters")}
        onToggle={(id) => config.toggle(state, activeGroupId, id)}
        onSelect={(id) => {
          config.toggle(state, activeGroupId, id);
          setExpanded(null);
        }}
        onAccept={filterMulti ? () => setExpanded(null) : undefined}
        acceptLabel={`${t("common.apply", "Aplicar")}${selectedInGroup.length ? ` (${selectedInGroup.length})` : ""}`}
      />
    );
  }

  const columns = 1 + (hasGroups ? 1 : 0) + (hasFilter ? 1 : 0);
  const gridTemplateColumns =
    columns === 3
      ? "minmax(0, 1.1fr) minmax(0, 1fr) minmax(0, 1fr)"
      : columns === 2
        ? "minmax(0, 1fr) minmax(0, 1fr)"
        : "minmax(0, 1fr)";

  return (
    <>
      {cascade}
      <section
        className="mobile-map-tribe-subdock"
        role="toolbar"
        aria-label={t("common.tribe", "Tribe")}
        style={{ gridTemplateColumns }}
      >
        <button
          type="button"
          className={`mobile-map-tribe-subdock__action mobile-map-tribe-subdock__action--primary ${expanded === "tribe" ? "is-open" : ""}`}
          aria-expanded={expanded === "tribe"}
          onClick={() => toggleExpanded("tribe")}
        >
          <span
            className="mobile-map-tribe-subdock__bubble"
            style={{ "--tribe-accent": selectedTribe.color }}
            aria-hidden="true"
          >
            <TribeIcon tribeId={selectedTribe.iconId || selectedTribe.id} size={15} />
          </span>
          <span className="mobile-map-tribe-subdock__copy">
            <small>{t("common.tribe", "Tribe")}</small>
            <strong>{selectedTribe.label}</strong>
          </span>
        </button>

        {hasGroups ? (
          <button
            type="button"
            className={`mobile-map-tribe-subdock__action mobile-map-tribe-subdock__action--slot ${expanded === "group" ? "is-open" : ""}`}
            aria-expanded={expanded === "group"}
            onClick={() => toggleExpanded("group")}
          >
            <span className="mobile-map-tribe-subdock__copy">
              <small>{t("common.group", "Grupo")}</small>
              <strong>{groupLabel}</strong>
            </span>
          </button>
        ) : null}

        {hasFilter ? (
          <button
            type="button"
            className={`mobile-map-tribe-subdock__action mobile-map-tribe-subdock__action--slot ${expanded === "filter" ? "is-open" : ""}`}
            aria-expanded={expanded === "filter"}
            onClick={() => toggleExpanded("filter")}
          >
            <span className="mobile-map-tribe-subdock__copy">
              <small>{t("common.filters", "Filtro")}</small>
              <strong>{filterValueLabel}</strong>
            </span>
          </button>
        ) : null}
      </section>
    </>
  );
}

const MOBILE_MAP_OPTION_FRAME_THRESHOLD = 8;

function MobileMapOptionStack({
  options,
  selectedId,
  selectedIds,
  onSelect,
  onToggle,
  onAccept,
  acceptLabel,
  ariaLabel,
  forceFrame = false,
  multi = false,
}) {
  const selectedSet = multi ? new Set(selectedIds || []) : null;
  const isSelected = (id) => (multi ? selectedSet.has(id) : id === selectedId);
  const handle = (id) => (multi ? onToggle?.(id) : onSelect?.(id));

  // Long lists (brands, models, grouped filters...) become a single scrollable framed
  // list instead of a tall column of floating pills. Multi-select always uses the frame.
  if (multi || forceFrame || options.length > MOBILE_MAP_OPTION_FRAME_THRESHOLD) {
    return (
      <section
        className="mobile-map-option-frame"
        role="listbox"
        aria-multiselectable={multi || undefined}
        aria-label={ariaLabel}
      >
        {multi && onAccept ? (
          <div className="mobile-map-option-frame__head">
            <button type="button" className="mobile-map-option-frame__accept" onClick={onAccept}>
              {acceptLabel}
            </button>
          </div>
        ) : null}
        {options.map((option) => {
          const active = isSelected(option.id);
          return (
            <button
              key={option.id || "__all"}
              type="button"
              role="option"
              aria-selected={active}
              className={`mobile-map-option-frame__row ${active ? "is-active" : ""}`}
              onClick={() => handle(option.id)}
            >
              {option.icon ? (
                <span className="mobile-map-option-frame__icon" aria-hidden="true">
                  {option.icon}
                </span>
              ) : null}
              <span className="mobile-map-option-frame__label">{option.label}</span>
              {multi ? (
                <span className={`mobile-map-option-frame__check ${active ? "is-on" : ""}`} aria-hidden="true">
                  {active ? <Check size={13} /> : null}
                </span>
              ) : null}
            </button>
          );
        })}
      </section>
    );
  }

  return (
    <section className="mobile-map-tribe-stack mobile-map-option-stack" role="toolbar" aria-label={ariaLabel}>
      {options.map((option) => {
        const active = isSelected(option.id);
        return (
          <button
            key={option.id || "__all"}
            type="button"
            className={`mobile-map-tribe-stack__option ${active ? "is-active" : ""}`}
            aria-pressed={active}
            onClick={() => handle(option.id)}
          >
            {option.icon ? (
              <span className="mobile-map-tribe-stack__bubble" aria-hidden="true">
                {option.icon}
              </span>
            ) : null}
            <span className="mobile-map-tribe-stack__label">{option.label}</span>
          </button>
        );
      })}
    </section>
  );
}

