function MobileMapCardRail({ state }) {
  const { t, locale } = useChromeI18n();
  const uiError = resolveCoreApiUiMessage(state.error, locale);
  const hasResults = state.filteredItems.length > 0;
  const trackRef = useRef(null);
  const [nav, setNav] = useState({ canPrev: false, canNext: false });
  // Lugar cuyo modal de detalle está abierto (botón ⓘ de la card).
  const [detailEntry, setDetailEntry] = useState(null);
  // Split móvil (mapa|cards): al scrollear la columna de cards, la card más
  // centrada pasa a activa → el mapa vuela a su pin. `syncFromScrollRef` evita el
  // bucle: marca que el cambio vino del scroll para no re-hacer scrollIntoView.
  const syncFromScrollRef = useRef("");

  const updateNav = () => {
    const track = trackRef.current;
    if (!track) return;
    const canPrev = track.scrollLeft > 4;
    const canNext = track.scrollLeft + track.clientWidth < track.scrollWidth - 4;
    setNav((current) =>
      current.canPrev === canPrev && current.canNext === canNext ? current : { canPrev, canNext },
    );
  };

  // Card más centrada verticalmente → selección (con debounce por rAF).
  const syncSelectionFromScroll = () => {
    const track = trackRef.current;
    if (!track) return;
    const center = track.scrollTop + track.clientHeight / 2;
    let bestId = "";
    let bestDist = Infinity;
    for (const child of track.children) {
      const id = child.getAttribute?.("data-item-id");
      if (!id) continue;
      const mid = child.offsetTop + child.offsetHeight / 2;
      const dist = Math.abs(mid - center);
      if (dist < bestDist) {
        bestDist = dist;
        bestId = id;
      }
    }
    if (bestId && bestId !== state.selectedItemId) {
      syncFromScrollRef.current = bestId;
      state.setSelectedItemId(bestId);
    }
  };

  // Debounce por "asentamiento": la selección (y por tanto el flyTo del mapa) se
  // dispara ~120ms DESPUÉS de que el scroll para, no en cada frame. Evita que el
  // mapa "salte" sin parar mientras se scrollea.
  const scrollTimerRef = useRef(0);
  const onTrackScroll = () => {
    updateNav();
    window.clearTimeout(scrollTimerRef.current);
    scrollTimerRef.current = window.setTimeout(syncSelectionFromScroll, 120);
  };

  // Selección venida de FUERA (click en un pin del mapa) → lleva su card a la vista.
  useEffect(() => {
    const id = state.selectedItemId;
    if (!id || id === syncFromScrollRef.current) {
      syncFromScrollRef.current = "";
      return;
    }
    const card = trackRef.current?.querySelector(`[data-item-id="${id}"]`);
    if (card && typeof card.scrollIntoView === "function") {
      card.scrollIntoView({ block: "center", behavior: "smooth" });
      // Flash breve para que se note el salto (solo cuando viene de un pin).
      card.classList.remove("is-flash");
      void card.offsetWidth; // reflow: reinicia la animación
      card.classList.add("is-flash");
    }
  }, [state.selectedItemId]);

  useEffect(() => {
    updateNav();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state.filteredItems]);

  const handleTrackWheel = (event) => {
    const track = trackRef.current;
    if (!track) return;

    const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
    if (!delta) return;

    event.preventDefault();
    track.scrollLeft += delta;
  };

  const scrollCards = (direction) => {
    const track = trackRef.current;
    if (!track) return;
    track.scrollBy({ left: direction * Math.max(160, track.clientWidth * 0.85), behavior: "smooth" });
  };

  return (
    <>
    <section className="mobile-map-cards" aria-label={t("common.filteredPlaces", "Lugares filtrados")}>
      {hasResults ? (
        <span className="mobile-map-cards__count">
          {t("common.resultsCount", "{n} resultados").replace("{n}", state.filteredItems.length)}
        </span>
      ) : null}

      {uiError ? <div className="map-status-box__error">{uiError}</div> : null}
      {state.loading ? <p className="results-state">{t("common.loadingResults", "Cargando resultados...")}</p> : null}
      {!state.loading && !hasResults ? (
        <p className="results-state">{t("common.noResults", "No hay resultados con los filtros actuales.")}</p>
      ) : null}

      {hasResults ? (
        <div className="mobile-map-cards__viewport">
          <button
            type="button"
            className="mobile-map-cards__nav mobile-map-cards__nav--prev"
            aria-label={t("common.previous", "Anteriores")}
            disabled={!nav.canPrev}
            onClick={() => scrollCards(-1)}
          >
            <ChevronLeft size={18} />
          </button>

          <div
            ref={trackRef}
            className="mobile-map-cards__track"
            role="list"
            onWheel={handleTrackWheel}
            onScroll={onTrackScroll}
          >
            {state.filteredItems.map((entry) => (
              <MobileMapResultCard
                key={entry.id}
                entry={entry}
                isActive={entry.id === state.selectedItemId}
                onSelect={() => state.setSelectedItemId(entry.id === state.selectedItemId ? "" : entry.id)}
                onOpenDetail={setDetailEntry}
              />
            ))}
          </div>

          <button
            type="button"
            className="mobile-map-cards__nav mobile-map-cards__nav--next"
            aria-label={t("common.next", "Siguientes")}
            disabled={!nav.canNext}
            onClick={() => scrollCards(1)}
          >
            <ChevronRight size={18} />
          </button>
        </div>
      ) : null}
    </section>
    <MobileMapCardModal entry={detailEntry} onClose={() => setDetailEntry(null)} />
    </>
  );
}

function resolveMobileDrawerFilterId(tribeId) {
  if (tribeId === "services") return "services";
  if (tribeId === "shops") return "shops";
  if (isSwapistaTribe(tribeId)) return "swapistas";
  return "vehicle";
}

function resolveMobileTribeFilterTitle(state, t) {
  const tribeId = state.tribe || DEFAULT_MAP_TRIBE;
  if (tribeId === "services") return t("map.serviceProfession", "Service profession");
  if (tribeId === "shops") return t("map.shopSubcategory", "Shop subcategory");
  if (isSwapistaTribe(tribeId)) return t("map.swapFilters", "Swap subfilters");
  return t("common.tribe", "Tribe");
}

function resolveMobileDrawerSidebarMode(mode) {
  if (mode === "tribe-filters") return "tribe-filters";
  if (mode === "full-filters") return "full";
  return mode;
}

function MobileMapFilterDrawer({ open, mode, title, state, initialOpenFilterId, searchAutoFocusKey, onClose }) {
  const { t } = useChromeI18n();

  useEffect(() => {
    if (!open) return undefined;

    const onKeyDown = (event) => {
      if (event.key === "Escape") onClose();
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open, onClose]);

  if (!open) return null;

  const titleByMode = {
    country: t("common.location", "Ubicacion"),
    search: t("common.search", "Buscar"),
    filters: t("common.filters", "Filtros"),
    "full-filters": t("common.filters", "Filtros"),
    "tribe-filters": t("common.tribe", "Tribu"),
  };
  const resolvedTitle = title || titleByMode[mode] || titleByMode.filters;

  return (
    <div className={`mobile-map-drawer mobile-map-drawer--${mode || "filters"}`} role="presentation" onClick={onClose}>
      <section
        className="mobile-map-drawer__sheet"
        role="dialog"
        aria-modal="false"
        aria-label={resolvedTitle}
        onClick={(event) => event.stopPropagation()}
      >
        <header className="mobile-map-drawer__header">
          <div>
            <h2 className="mobile-map-drawer__title">{resolvedTitle}</h2>
          </div>
          <button
            type="button"
            className="mobile-map-drawer__close"
            aria-label={t("common.close", "Cerrar")}
            onClick={onClose}
          >
            <X size={16} />
          </button>
        </header>

        <div className="mobile-map-drawer__body">
          <MapShellSidebar
            state={state}
            initialOpenFilterId={initialOpenFilterId}
            searchAutoFocusKey={searchAutoFocusKey}
            mobileMode={resolveMobileDrawerSidebarMode(mode)}
          />
        </div>
      </section>
    </div>
  );
}

function MobileMapShell({ state, vehicleMakeCatalog, canManageMapPlaces, dockAction, openSubdockId, onCloseSubdock }) {
  const { t } = useChromeI18n();
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [drawerMode, setDrawerMode] = useState("filters");
  const [drawerTitle, setDrawerTitle] = useState("");
  const [drawerFilterId, setDrawerFilterId] = useState("tribe");
  const [searchAutoFocusKey, setSearchAutoFocusKey] = useState(0);
  // Which cascade is expanded inside the active subdock: null | "tribe" | "vehicleCategory" | "brand" | "model" | "country"
  const [expandedField, setExpandedField] = useState(null);
  const [cardsCollapsed, setCardsCollapsed] = useState(false);
  const cardsLayerRef = useRef(null);
  const [cardsBottomInset, setCardsBottomInset] = useState(220);

  // Measure how much of the map is occluded by the results panel at the bottom,
  // so the map can recenter its content into the visible gap (not under the cards).
  useEffect(() => {
    const el = cardsLayerRef.current;
    if (!el || typeof window === "undefined") return undefined;
    const measure = () => {
      const rect = el.getBoundingClientRect();
      const inset = Math.max(0, Math.round(window.innerHeight - rect.top));
      setCardsBottomInset((current) => (Math.abs(current - inset) < 2 ? current : inset));
    };
    measure();
    const raf = window.requestAnimationFrame(measure);
    let observer;
    if (typeof ResizeObserver !== "undefined") {
      observer = new ResizeObserver(measure);
      observer.observe(el);
    }
    window.addEventListener("resize", measure);
    return () => {
      window.cancelAnimationFrame(raf);
      observer?.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [cardsCollapsed]);

  // Split móvil: el mapa ocupa la mitad izquierda (las cards van en columna
  // aparte a la derecha, ya no ocluyen el mapa). Header y dock flotan sobre los
  // bordes superior/inferior, de ahí los insets fijos.
  const mapFocusInsets = useMemo(
    () => ({ top: 90, bottom: 90, left: 16, right: 16 }),
    [],
  );

  const subdockOpen =
    openSubdockId === "map-tribe" ||
    openSubdockId === "map-vehicle" ||
    openSubdockId === "map-country" ||
    openSubdockId === "map-search";

  const openDrawer = (mode = "filters", { filterId, focusSearch = false, title = "" } = {}) => {
    setExpandedField(null);
    setDrawerMode(mode);
    setDrawerTitle(title);
    setDrawerFilterId(filterId || "tribe");
    if (focusSearch) {
      setSearchAutoFocusKey((value) => value + 1);
    }
    setDrawerOpen(true);
  };

  // Reset any expanded cascade whenever the active subdock changes (or closes).
  useEffect(() => {
    setExpandedField(null);
  }, [openSubdockId]);

  useEffect(() => {
    if (!state.selectedItemId) return;
    const stillVisible = state.filteredItems.some((entry) => entry.id === state.selectedItemId);
    if (!stillVisible) {
      state.setSelectedItemId("");
    }
  }, [state.filteredItems, state.selectedItemId, state]);

  useEffect(() => {
    if (!dockAction?.id) return;

    // Every dock button (tribe/vehicle/country/search) toggles its subdock in the parent;
    // here we just close the per-tribe drawer and reset any open cascade.
    setDrawerOpen(false);
    setExpandedField(null);
  }, [dockAction]);

  return (
    <div className={`mobile-map-shell ${drawerOpen ? "is-filters-open" : ""} ${subdockOpen ? "has-tribe-subdock" : ""}`}>
      <div className="mobile-map-shell__map-layer">
        <MapShellMain
          state={state}
          canManageMapPlaces={canManageMapPlaces}
          brandCatalog={vehicleMakeCatalog}
          focusInsets={mapFocusInsets}
          suppressSelectionOverlay
        />
      </div>

      <div className="mobile-map-shell__split">
        <div className="mobile-map-shell__top-spacer" aria-hidden="true" />
        <button
          type="button"
          className="mobile-map-cards__collapse"
          aria-expanded={subdockOpen ? undefined : !cardsCollapsed}
          aria-label={
            subdockOpen
              ? t("common.close", "Cerrar")
              : cardsCollapsed
                ? t("common.showResults", "Mostrar resultados")
                : t("common.hideResults", "Ver el mapa completo")
          }
          onClick={() => {
            if (subdockOpen) {
              onCloseSubdock();
              return;
            }
            setCardsCollapsed((value) => !value);
          }}
        >
          {cardsCollapsed && !subdockOpen ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
        </button>
        <div ref={cardsLayerRef} className={`mobile-map-shell__cards-layer ${cardsCollapsed ? "is-collapsed" : ""}`}>
          {cardsCollapsed ? null : <MobileMapCardRail state={state} />}
        </div>
      </div>

      {subdockOpen ? (
        <>
          <button
            type="button"
            className="mobile-map-shell__tribe-backdrop"
            aria-label={t("common.close", "Close")}
            onClick={() => onCloseSubdock()}
          />
          <div className="mobile-map-shell__quick-filter-layer mobile-map-shell__quick-filter-layer--subdock">
            <div className="mobile-map-subdock-cluster">
              {openSubdockId === "map-tribe" ? <MobileMapTribeSubdock state={state} /> : null}

              {openSubdockId === "map-vehicle" ? (
                <MobileMapVehicleSubdock
                  state={state}
                  expandedField={expandedField}
                  onToggleField={(field) => setExpandedField(field)}
                />
              ) : null}

              {openSubdockId === "map-country" ? (
                <MobileMapCountrySubdock
                  state={state}
                  expanded={expandedField === "country"}
                  onToggle={(open) => setExpandedField(open ? "country" : null)}
                />
              ) : null}

              {openSubdockId === "map-search" ? <MobileMapSearchSubdock state={state} /> : null}
            </div>
          </div>
        </>
      ) : null}

      <MobileMapFilterDrawer
        open={drawerOpen}
        mode={drawerMode}
        title={drawerTitle}
        state={state}
        initialOpenFilterId={drawerFilterId}
        searchAutoFocusKey={searchAutoFocusKey}
        onClose={() => setDrawerOpen(false)}
      />
    </div>
  );
}

function useChromeBridge(navigate, session, activeSectionId, canAccessWorkerProfile) {
  useEffect(() => {
    const api = {
      navigate: (dest) => {
        if (typeof dest !== "string") return;
        const normalized = dest.toLowerCase().replace(/^#\/?/, "").trim();
        const target = resolveSectionId(normalized);
        if (!target) return;
        if (target === "worker" && !canAccessWorkerProfile) {
          navigate(DEFAULT_SECTION_ID);
          return;
        }
        navigate(target);
      },
      getActiveRoute: () => ({ section: activeSectionId }),
      getSession: () => ({ status: session.status, user: session.user || null, subject: session.subject || null }),
    };

    window.BTR_CHROME_SHELL = api;
    window.BTR_SHELL = api;
    window.BTR_MOTORS_CHROME = api;

    return () => {
      if (window.BTR_CHROME_SHELL === api) delete window.BTR_CHROME_SHELL;
      if (window.BTR_SHELL === api) delete window.BTR_SHELL;
      if (window.BTR_MOTORS_CHROME === api) delete window.BTR_MOTORS_CHROME;
    };
  }, [navigate, session.status, session.user, session.subject, activeSectionId, canAccessWorkerProfile]);
}

function DesktopShell({
  sections,
  navSections,
  activeSectionId,
  onSelectSection,
  onOpenSettings,
  onSwitchProfileMode,
  canAccessWorkerProfile,
  profilePreferences,
  onChangeProfilePreferences,
  settingsTabId,
  onSelectSettingsTab,
  session,
  mapShellState,
  vehicleMakeCatalog,
  canManageMapPlaces,
}) {
  const mapShellEnabledDesktop = activeSectionId === "map";
  const settingsShellEnabledDesktop = activeSectionId === "settings";
  const remoteOwnLayoutDesktop = !mapShellEnabledDesktop && !settingsShellEnabledDesktop;

  return (
    <div className="chrome-app chrome-app--desktop">
      <aside className="railbar">
        <nav className="railbar__nav" aria-label="Motors sections">
          {navSections.map((section) => {
            const Icon = iconFor(section.id);
            const isActive = section.id === activeSectionId;
            return (
              <button
                key={section.id}
                type="button"
                className={`railbar__btn ${isActive ? "is-active" : ""}`}
                aria-pressed={isActive}
                title={section.label}
                onClick={() => onSelectSection(section.id)}
              >
                <span className="railbar__btn-accent" style={{ backgroundColor: section.color }} />
                <Icon size={18} />
                <span>{section.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="railbar__footer">
          <SettingsSectionButton activeSectionId={activeSectionId} onOpenSettings={onOpenSettings} />
          <ProfileModeSwitcher
            activeSectionId={activeSectionId}
            canAccessWorkerProfile={canAccessWorkerProfile}
            onOpenSettings={onOpenSettings}
            onSwitchMode={onSwitchProfileMode}
            session={session}
            variant="desktop"
          />
        </div>
      </aside>

      {!remoteOwnLayoutDesktop ? (
        <aside
          className={`sidebar-shell ${mapShellEnabledDesktop ? "sidebar-shell--map" : ""}`}
        >
          {mapShellEnabledDesktop ? <MapShellSidebar state={mapShellState} /> : null}
          {settingsShellEnabledDesktop ? (
            <SettingsShellSidebar
              activeTab={settingsTabId}
              onSelectTab={onSelectSettingsTab}
              session={session}
            />
          ) : null}
        </aside>
      ) : null}

      {!remoteOwnLayoutDesktop && !settingsShellEnabledDesktop ? (
        <aside
          className={`contextpanel-shell ${mapShellEnabledDesktop ? "contextpanel-shell--map" : ""}`}
        >
          {mapShellEnabledDesktop ? <MapShellContextPanel state={mapShellState} /> : null}
        </aside>
      ) : null}

      <main
        className={`app-main-shell ${mapShellEnabledDesktop ? "app-main-shell--map" : ""} ${remoteOwnLayoutDesktop ? "app-main-shell--remote-full" : ""}`}
        aria-label="Microfrontend host"
      >
        {mapShellEnabledDesktop ? (
          <MapShellMain
            state={mapShellState}
            canManageMapPlaces={canManageMapPlaces}
            brandCatalog={vehicleMakeCatalog}
          />
        ) : null}
        {settingsShellEnabledDesktop ? (
          <SettingsShellMain
            activeTab={settingsTabId}
            preferences={profilePreferences}
            onChangePreferences={onChangeProfilePreferences}
            session={session}
          />
        ) : null}
        {remoteOwnLayoutDesktop ? (
          <RemoteFrameHost
            sections={sections}
            activeSectionId={activeSectionId}
            viewport="desktop"
            searchText=""
            locale={profilePreferences.language}
            session={session}
            remoteSectionState={{}}
            slotBySection={{}}
          />
        ) : null}
      </main>
    </div>
  );
}

function MobileShell({
  sections,
  navSections,
  activeSectionId,
  onSelectSection,
  onOpenSettings,
  onSwitchProfileMode,
  canAccessWorkerProfile,
  profilePreferences,
  onChangeProfilePreferences,
  searchText,
  onSearchTextChange,
  settingsTabId,
  onSelectSettingsTab,
  session,
  mapShellState,
  vehicleMakeCatalog,
  canManageMapPlaces,
}) {
  const { t, locale } = useChromeI18n();
  const activeSection = getSectionOrDefault(activeSectionId);
  const ActiveSectionIcon = iconFor(activeSection.id);
  const activeSectionLabel = labelForSection(activeSection, t);
  const mapShellEnabledMobile = activeSectionId === "map";
  const marketplaceShellEnabledMobile = activeSectionId === "marketplace";
  const calendarShellEnabledMobile = activeSectionId === "calendar";
  const settingsShellEnabledMobile = activeSectionId === "settings";
  // Secciones servidas por un MFE en iframe (marketplace, garagex, calendar…):
  // el MFE trae su propia UI, no debemos apilarle encima la tarjeta de auth/debug.
  const remoteFrameEnabledMobile = !mapShellEnabledMobile && !settingsShellEnabledMobile;
  // Marketplace y calendar usan el dock del shell (como el mapa): su Buscar vive
  // en el dock, así que ocultamos la barra de búsqueda global para no duplicar.
  const showMobileSearch =
    !mapShellEnabledMobile &&
    !settingsShellEnabledMobile &&
    !marketplaceShellEnabledMobile &&
    !calendarShellEnabledMobile;
  const showMobileAuth = !mapShellEnabledMobile && !remoteFrameEnabledMobile;
  // El dock del shell se pinta para las secciones con handleDockAction operativo:
  // el mapa (nativo) y los iframes marketplace/calendar (por postMessage).
  const showMobileDock =
    mapShellEnabledMobile || marketplaceShellEnabledMobile || calendarShellEnabledMobile;
  const [headerRef, headerHeight] = useElementHeight();
  const [dockRef, dockHeight] = useElementHeight();
  const [menuOpen, setMenuOpen] = useState(false);
  const [marketMenuOpen, setMarketMenuOpen] = useState(false);
  const [mobileSettingsTab, setMobileSettingsTab] = useState(null);
  const [mapDockAction, setMapDockAction] = useState({ id: "", token: 0 });
  const [mapOpenSubdockId, setMapOpenSubdockId] = useState("");
  // Marketplace: comando que se envía al iframe + estado (id abierto / badges)
  // que el iframe devuelve para resaltar el botón activo del dock.
  const [marketplaceDockCommand, setMarketplaceDockCommand] = useState({ id: "", token: 0 });
  const [marketplaceOpenDockId, setMarketplaceOpenDockId] = useState("");
  const [marketplaceDockBadges, setMarketplaceDockBadges] = useState({});
  // Tipo de marketplace activo (coche/moto/parts/tools) → icono en el header.
  const [marketplaceType, setMarketplaceType] = useState("");
  // Calendar: mismo patrón que el marketplace (iframe + postMessage). El shell
  // dispara el comando y el iframe devuelve qué hoja tiene abierta + badges.
  const [calendarDockCommand, setCalendarDockCommand] = useState({ id: "", token: 0 });
  const [calendarOpenDockId, setCalendarOpenDockId] = useState("");
  const [calendarDockBadges, setCalendarDockBadges] = useState({});
  // Comando de tipo pendiente cuando se elige desde la hamburguesa estando en otra
  // sección: se lanza al iframe en cuanto el marketplace monta y nos saluda.
  const pendingMarketTypeRef = useRef(null);
  const dockActions = useMemo(() => createMobileDockActions(activeSectionId, t), [activeSectionId, t]);
  const mapDockBadges = useMemo(
    () => (mapShellEnabledMobile ? getMobileMapDockBadges(mapShellState) : {}),
    [mapShellEnabledMobile, mapShellState],
  );
  const selectedMobileMapTribe = useMemo(
    () => (mapShellEnabledMobile ? getMapTribeMeta(mapShellState.tribe || DEFAULT_MAP_TRIBE, locale) : null),
    [locale, mapShellEnabledMobile, mapShellState.tribe],
  );
  const mobileShellStyle = {
    "--mobile-shell-gap": "8px",
    "--mobile-shell-header-height": `${Math.max(60, headerHeight || 0)}px`,
    "--mobile-shell-dock-height": `${Math.max(76, dockHeight || 0)}px`,
    ...(mapShellEnabledMobile
      ? {
        "--mobile-map-header-height": `${Math.max(60, headerHeight || 0)}px`,
        "--mobile-map-dock-height": `${Math.max(76, dockHeight || 0)}px`,
      }
      : {}),
  };

  useEffect(() => {
    setMenuOpen(false);
    setMobileSettingsTab(null);
  }, [activeSectionId]);

  useEffect(() => {
    setMapOpenSubdockId("");
  }, [mapShellEnabledMobile]);

  useEffect(() => {
    setMarketplaceOpenDockId("");
    setMarketplaceDockBadges({});
  }, [marketplaceShellEnabledMobile]);

  useEffect(() => {
    setCalendarOpenDockId("");
    setCalendarDockBadges({});
  }, [calendarShellEnabledMobile]);

  // El iframe del calendar nos informa de qué hoja tiene abierta (para resaltar
  // el botón del dock) y del número de filtros activos (para el badge).
  useEffect(() => {
    const onMessage = (event) => {
      const payload = event.data;
      if (!payload || typeof payload !== "object" || payload.type !== "beterano-calendar:dock-state") return;
      setCalendarOpenDockId(typeof payload.openId === "string" ? payload.openId : "");
      setCalendarDockBadges(payload.badges && typeof payload.badges === "object" ? payload.badges : {});
    };
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, []);

  // El iframe del marketplace nos informa de qué hoja tiene abierta (para resaltar
  // el botón del dock) y del número de filtros activos (para el badge).
  useEffect(() => {
    const onMessage = (event) => {
      const payload = event.data;
      if (!payload || typeof payload !== "object" || payload.type !== "beterano-marketplace:dock-state") return;
      setMarketplaceOpenDockId(typeof payload.openId === "string" ? payload.openId : "");
      setMarketplaceDockBadges(payload.badges && typeof payload.badges === "object" ? payload.badges : {});
      setMarketplaceType(typeof payload.marketType === "string" ? payload.marketType : "");
      // El iframe ya está vivo: si veníamos de otra sección con un tipo pendiente,
      // lo aplicamos ahora.
      if (pendingMarketTypeRef.current) {
        const action = pendingMarketTypeRef.current;
        pendingMarketTypeRef.current = null;
        setMarketplaceDockCommand((current) => ({ id: action, token: current.token + 1 }));
      }
    };
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, []);

  const handleDockAction = (actionId) => {
    if (mapShellEnabledMobile) {
      setMapOpenSubdockId((current) => (current === actionId ? "" : actionId));
      setMapDockAction((current) => ({ id: actionId, token: current.token + 1 }));
      return;
    }
    if (marketplaceShellEnabledMobile) {
      // Solo disparamos el comando; el iframe decide el nuevo estado y nos lo
      // devuelve por postMessage, que actualiza el resaltado del dock.
      setMarketplaceDockCommand((current) => ({ id: actionId, token: current.token + 1 }));
      return;
    }
    if (calendarShellEnabledMobile) {
      setCalendarDockCommand((current) => ({ id: actionId, token: current.token + 1 }));
    }
  };

  // Elegir tipo desde la hamburguesa: si ya estamos en marketplace, lo aplicamos al
  // iframe al vuelo; si no, cambiamos de sección y lo aplicamos al montar (pending).
  const selectMarketplaceType = (action) => {
    setMenuOpen(false);
    if (marketplaceShellEnabledMobile) {
      setMarketplaceDockCommand((current) => ({ id: action, token: current.token + 1 }));
      return;
    }
    pendingMarketTypeRef.current = action;
    onSelectSection("marketplace");
  };
  const isWorkerMode = activeSectionId === "worker";

  return (
    <div
      className={`chrome-app chrome-app--mobile ${mapShellEnabledMobile ? "chrome-app--mobile-map" : ""} ${marketplaceShellEnabledMobile ? "chrome-app--mobile-fullbleed" : ""}`}
      style={mobileShellStyle}
    >
      <header className="mobile-header" ref={headerRef}>
        <button
          type="button"
          className={`mobile-header__menu-toggle ${menuOpen ? "is-active" : ""}`}
          aria-expanded={menuOpen}
          aria-label={menuOpen ? t("common.close", "Close") : "Open navigation"}
          onClick={() => setMenuOpen((current) => !current)}
        >
          {menuOpen ? <X size={18} /> : <Menu size={18} />}
        </button>
        <div className="mobile-header__center-brand" aria-hidden="true">
          <img src="/mobile-header-symbol.svg" alt="" className="mobile-header__center-logo" />
        </div>
        <div className="mobile-header__actions">
          {/* Semi-píldora que emerge a la izquierda de "Marketplace" con el icono
              del tipo activo (coche/moto/piezas/herramientas), para saber en qué
              marketplace estamos. */}
          {marketplaceShellEnabledMobile && marketplaceType ? (
            <span
              className="mobile-header__type-pill"
              style={{ "--mobile-section-color": activeSection.color }}
              aria-hidden="true"
            >
              {marketplaceType === "coche" ? (
                <CarFront size={15} />
              ) : marketplaceType === "moto" ? (
                <Bike size={15} />
              ) : marketplaceType === "parts" ? (
                <Cog size={15} />
              ) : marketplaceType === "tools" ? (
                <Wrench size={15} />
              ) : null}
            </span>
          ) : null}
          <div
            className="mobile-header__section-indicator"
            style={{ "--mobile-section-color": activeSection.color }}
            aria-label={activeSectionLabel}
          >
            <ActiveSectionIcon size={16} />
            <span>{activeSectionLabel}</span>
          </div>
        </div>
      </header>

      {menuOpen ? (
        <>
          <button
            type="button"
            className="mobile-header-menu__backdrop"
            aria-label={t("common.close", "Close")}
            onClick={() => setMenuOpen(false)}
          />
          <div className="mobile-header-menu">
            <nav className="mobile-header-menu__nav" aria-label="Motors sections">
              {navSections.map((section) => {
                const Icon = iconFor(section.id);
                const isActive = section.id === activeSectionId;
                const sectionButton = (
                  <button
                    key={section.id}
                    type="button"
                    className={`mobile-header-menu__item ${isActive ? "is-active" : ""}`}
                    onClick={() => onSelectSection(section.id)}
                    aria-pressed={isActive}
                  >
                    <span
                      className="mobile-header-menu__item-accent"
                      style={{ backgroundColor: section.color }}
                    />
                    <Icon size={18} />
                    <span>{labelForSection(section, t)}</span>
                  </button>
                );
                // El marketplace no navega por si mismo: es un desplegable. Su
                // boton solo abre/cierra el submenu de tipos (Coche/Moto/Piezas/
                // Herramientas), que son los que aplican filtro y entran al MFE.
                if (section.id === "marketplace") {
                  return (
                    <div
                      key={section.id}
                      className={`mobile-header-menu__group ${marketMenuOpen ? "is-open" : ""}`}
                    >
                      <button
                        type="button"
                        className={`mobile-header-menu__item mobile-header-menu__item--toggle ${isActive ? "is-active" : ""}`}
                        onClick={() => setMarketMenuOpen((open) => !open)}
                        aria-expanded={marketMenuOpen}
                      >
                        <span
                          className="mobile-header-menu__item-accent"
                          style={{ backgroundColor: section.color }}
                        />
                        <Icon size={18} />
                        <span>{labelForSection(section, t)}</span>
                        <ChevronDown size={16} className="mobile-header-menu__chevron" aria-hidden="true" />
                      </button>
                      {marketMenuOpen ? (
                        <div className="mobile-header-menu__subnav">
                          {MARKETPLACE_TYPE_ITEMS.map((typeItem) => {
                            const TypeIcon = typeItem.icon;
                            return (
                              <button
                                key={typeItem.id}
                                type="button"
                                className="mobile-header-menu__subitem"
                                onClick={() => selectMarketplaceType(typeItem.action)}
                              >
                                <TypeIcon size={16} />
                                <span>{t(typeItem.labelKey, typeItem.label)}</span>
                              </button>
                            );
                          })}
                        </div>
                      ) : null}
                    </div>
                  );
                }
                return sectionButton;
              })}
            </nav>
            <div className="mobile-header-menu__divider" aria-hidden="true" />
            <div className="mobile-header-menu__account" aria-label="Cuenta y ajustes">
              <button
                type="button"
                className={`mobile-header-menu__item ${settingsShellEnabledMobile ? "is-active" : ""}`}
                onClick={() => {
                  onOpenSettings();
                  setMenuOpen(false);
                }}
                aria-pressed={settingsShellEnabledMobile}
              >
                <span className="mobile-header-menu__item-accent" style={{ backgroundColor: "#475569" }} />
                <Settings size={18} />
                <span className="mobile-header-menu__item-copy">
                  <strong>{t("common.settings", "Settings")}</strong>
                  <small>
                    {[
                      t("common.profile", "Profile"),
                      t("common.language", "Language"),
                      t("common.notifications", "Notifications"),
                    ].join(" · ")}
                  </small>
                </span>
              </button>

              <button
                type="button"
                className={`mobile-header-menu__item ${!isWorkerMode ? "is-active" : ""}`}
                onClick={() => {
                  onSwitchProfileMode("motors");
                  setMenuOpen(false);
                }}
                aria-pressed={!isWorkerMode}
              >
                <span className="mobile-header-menu__item-accent" style={{ backgroundColor: "#111827" }} />
                <LayoutPanelLeft size={18} />
                <span className="mobile-header-menu__item-copy">
                  <strong>Beterano Motors</strong>
                  <small>{session.displayName}</small>
                </span>
                {!isWorkerMode ? <BadgeCheck size={14} /> : null}
              </button>

              {canAccessWorkerProfile ? (
                <button
                  type="button"
                  className={`mobile-header-menu__item ${isWorkerMode ? "is-active" : ""}`}
                  onClick={() => {
                    onSwitchProfileMode("worker");
                    setMenuOpen(false);
                  }}
                  aria-pressed={isWorkerMode}
                >
                  <span className="mobile-header-menu__item-accent" style={{ backgroundColor: "#b45309" }} />
                  <Wrench size={18} />
                  <span className="mobile-header-menu__item-copy">
                    <strong>Beterano LAB Worker</strong>
                    <small>{t("common.profile", "Profile")}</small>
                  </span>
                  {isWorkerMode ? <BadgeCheck size={14} /> : null}
                </button>
              ) : (
                <div className="mobile-header-menu__hint">
                  El perfil LAB Worker aparece cuando tu usuario tiene registro o rol worker.
                </div>
              )}
            </div>
          </div>
        </>
      ) : null}

      {showMobileSearch ? (
        <div className="mobile-search">
          <Search size={16} />
          <input value={searchText} onChange={(event) => onSearchTextChange(event.target.value)} placeholder={t("common.searchPlaceholder", "Buscar...")} />
        </div>
      ) : null}

      {showMobileAuth ? (
        <div className="mobile-auth-wrap">
          <AuthStatusCard session={session} compact />
        </div>
      ) : null}

      <main className={`mobile-main ${mapShellEnabledMobile ? "mobile-main--map" : ""}`}>
        {mapShellEnabledMobile ? (
          <MobileMapShell
            state={mapShellState}
            vehicleMakeCatalog={vehicleMakeCatalog}
            canManageMapPlaces={canManageMapPlaces}
            dockAction={mapDockAction}
            openSubdockId={mapOpenSubdockId}
            onCloseSubdock={() => setMapOpenSubdockId("")}
          />
        ) : null}

        {settingsShellEnabledMobile ? (
          <div className="mobile-stack-shell mobile-settings">
            {mobileSettingsTab ? (
              <>
                <header className="mobile-settings__detail-header">
                  <button
                    type="button"
                    className="mobile-settings__back"
                    onClick={() => setMobileSettingsTab(null)}
                    aria-label={t("common.back", "Atras")}
                  >
                    <ChevronLeft size={18} aria-hidden="true" />
                    <span>{t("common.back", "Atras")}</span>
                  </button>
                  <h2 className="mobile-settings__detail-title">
                    {mobileSettingsTab === "profile" && t("common.profile", "Perfil")}
                    {mobileSettingsTab === "language" && t("common.language", "Idioma")}
                    {mobileSettingsTab === "subscription" && t("common.subscription", "Suscripcion")}
                    {mobileSettingsTab === "notifications" && t("common.notifications", "Notificaciones")}
                  </h2>
                </header>
                <SettingsShellMain
                  activeTab={mobileSettingsTab}
                  preferences={profilePreferences}
                  onChangePreferences={onChangeProfilePreferences}
                  session={session}
                  compact
                  hideHeader
                />
              </>
            ) : (
              <nav className="mobile-settings__list" aria-label={t("common.settings", "Settings")}>
                {[
                  { id: "profile", icon: CircleUserRound, label: t("common.profile", "Perfil") },
                  { id: "language", icon: Globe2, label: t("common.language", "Idioma") },
                  { id: "subscription", icon: CreditCard, label: t("common.subscription", "Suscripcion") },
                  { id: "notifications", icon: Bell, label: t("common.notifications", "Notificaciones") },
                ].map((item) => {
                  const Icon = item.icon;
                  return (
                    <button
                      key={item.id}
                      type="button"
                      className="mobile-settings__row"
                      onClick={() => {
                        onSelectSettingsTab(item.id);
                        setMobileSettingsTab(item.id);
                      }}
                    >
                      <span className="mobile-settings__row-icon" aria-hidden="true">
                        <Icon size={18} />
                      </span>
                      <span className="mobile-settings__row-label">{item.label}</span>
                      <ChevronRight size={16} className="mobile-settings__row-chevron" aria-hidden="true" />
                    </button>
                  );
                })}
              </nav>
            )}
          </div>
        ) : null}

        {!mapShellEnabledMobile && !settingsShellEnabledMobile ? (
          <RemoteFrameHost
            sections={sections}
            activeSectionId={activeSectionId}
            viewport="mobile"
            searchText={searchText}
            locale={profilePreferences.language}
            session={session}
            dockCommand={calendarShellEnabledMobile ? calendarDockCommand : marketplaceDockCommand}
          />
        ) : null}
      </main>

      {showMobileDock ? (
      <nav className="mobile-dock" aria-label="Motors dock" ref={dockRef}>
        {dockActions.map((action) => {
          const Icon = action.icon;
          const isActive = mapShellEnabledMobile
            ? mapOpenSubdockId === action.id
            : marketplaceShellEnabledMobile
              ? marketplaceOpenDockId === action.id
              : calendarShellEnabledMobile
                ? calendarOpenDockId === action.id
                : false;
          const badgeCount = mapShellEnabledMobile
            ? mapDockBadges[action.id] || 0
            : marketplaceShellEnabledMobile
              ? marketplaceDockBadges[action.id] || 0
              : calendarShellEnabledMobile
                ? calendarDockBadges[action.id] || 0
                : 0;
          const renderTribeGlobe = mapShellEnabledMobile && action.id === "map-tribe" && selectedMobileMapTribe;
          const renderGlobe = mapShellEnabledMobile && action.id !== "map-tribe" && badgeCount > 0;
          return (
            <button
              key={action.id}
              type="button"
              className={`mobile-dock__btn ${isActive ? "is-active" : ""}`}
              onClick={() => handleDockAction(action.id)}
            >
              <span className="mobile-dock__icon-wrap">
                {renderTribeGlobe ? (
                  <span
                    className="mobile-dock__tribe-globe"
                    style={{ "--tribe-accent": selectedMobileMapTribe.color }}
                    aria-hidden="true"
                  >
                    <TribeIcon tribeId={selectedMobileMapTribe.iconId || selectedMobileMapTribe.id} size={14} />
                  </span>
                ) : renderGlobe ? (
                  <span className="mobile-dock__globe" aria-hidden="true">
                    <Icon size={14} />
                  </span>
                ) : (
                  <Icon size={16} />
                )}
                {badgeCount > 0 ? <span className="mobile-dock__badge">{badgeCount}</span> : null}
              </span>
              <span>{action.label}</span>
            </button>
          );
        })}
      </nav>
      ) : null}
    </div>
  );
}

export default function App() {
  const [activeSectionId, navigate] = useActiveSection();
  const [searchText, setSearchText] = useState("");
  const [lastMotorsSectionId, setLastMotorsSectionId] = useState(DEFAULT_SECTION_ID);
  const [profilePreferences, setProfilePreferences] = useProfilePreferences();
  const [settingsTabId, setSettingsTabId] = useState(SETTINGS_TABS[0].id);
  const [vehicleMakeCatalog, setVehicleMakeCatalog] = useState(MAP_BRAND_CATALOG);
  const isMobile = useIsMobile();
  const session = useCoreSession();
  const canManageMapPlaces = useMemo(() => hasSuperAdminMapAccess(session), [session]);
  const canAccessWorkerProfile = hasWorkerProfileAccess(session);
  const preferredMapCountry = useMemo(() => resolveSessionCountry(session), [session]);
  const mapShellState = useMapShellState(activeSectionId === "map", preferredMapCountry, vehicleMakeCatalog);

  useEffect(() => {
    let cancelled = false;

    fetchVehicleMakeNames()
      .then((items) => {
        if (!cancelled && items.length) {
          setVehicleMakeCatalog(items);
        }
      })
      .catch(() => {
        // Keep local fallback while the central catalog is unavailable.
      });

    return () => {
      cancelled = true;
    };
  }, []);

  const navigateWithAccess = (sectionId) => {
    if (sectionId === "worker" && !canAccessWorkerProfile) {
      navigate(DEFAULT_SECTION_ID);
      return;
    }
    navigate(sectionId);
  };

  useChromeBridge(navigateWithAccess, session, activeSectionId, canAccessWorkerProfile);

  useEffect(() => {
    if (activeSectionId !== "worker") {
      setLastMotorsSectionId(activeSectionId);
      return;
    }
    if (!canAccessWorkerProfile) {
      navigate(DEFAULT_SECTION_ID);
    }
  }, [activeSectionId, canAccessWorkerProfile, navigate]);

  const switchProfileMode = (mode) => {
    if (mode === "worker") {
      navigateWithAccess("worker");
      return;
    }
    navigateWithAccess(lastMotorsSectionId === "worker" ? DEFAULT_SECTION_ID : lastMotorsSectionId);
  };

  useEffect(() => {
    const handler = (event) => {
      const payload = event.data;
      if (!payload || typeof payload !== "object") return;
      if (payload.type === "beterano-app-remote:navigate") {
        if (typeof payload.sectionId === "string") navigateWithAccess(payload.sectionId);
        return;
      }
      if (payload.type === "beterano-lab-worker:switch-profile") {
        if (payload.mode === "motors" || payload.mode === "worker") switchProfileMode(payload.mode);
      }
    };

    window.addEventListener("message", handler);
    return () => window.removeEventListener("message", handler);
  }, [navigateWithAccess, switchProfileMode]);

  const sections = useMemo(() => SECTION_DEFS, []);
  const navSections = useMemo(
    () => sections.filter((section) => section.id !== "worker" && section.id !== "settings"),
    [sections],
  );

  return (
    <ChromeI18nProvider locale={profilePreferences.language}>
      {isMobile ? (
        <MobileShell
          sections={sections}
          navSections={navSections}
          activeSectionId={activeSectionId}
          onSelectSection={navigateWithAccess}
          onOpenSettings={() => navigateWithAccess("settings")}
          onSwitchProfileMode={switchProfileMode}
          canAccessWorkerProfile={canAccessWorkerProfile}
          profilePreferences={profilePreferences}
          onChangeProfilePreferences={setProfilePreferences}
          searchText={searchText}
          onSearchTextChange={setSearchText}
          settingsTabId={settingsTabId}
          onSelectSettingsTab={setSettingsTabId}
          session={session}
          mapShellState={mapShellState}
          vehicleMakeCatalog={vehicleMakeCatalog}
          canManageMapPlaces={canManageMapPlaces}
        />
      ) : (
        <DesktopShell
          sections={sections}
          navSections={navSections}
          activeSectionId={activeSectionId}
          onSelectSection={navigateWithAccess}
          onOpenSettings={() => navigateWithAccess("settings")}
          onSwitchProfileMode={switchProfileMode}
          canAccessWorkerProfile={canAccessWorkerProfile}
          profilePreferences={profilePreferences}
          onChangeProfilePreferences={setProfilePreferences}
          settingsTabId={settingsTabId}
          onSelectSettingsTab={setSettingsTabId}
          session={session}
          mapShellState={mapShellState}
          vehicleMakeCatalog={vehicleMakeCatalog}
          canManageMapPlaces={canManageMapPlaces}
        />
      )}
    </ChromeI18nProvider>
  );
}
