const MARKETPLACE_TRIBE_IDS = new Set(["restauradores", "swapistas", "desguaces", "shops", "services"]);
const BRAND_LOGOS_BASE_URL = String(import.meta.env.VITE_BRAND_LOGOS_BASE_URL || "").trim();

const normalizeBrandSlug = (value) =>
  String(value || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "");

const buildBrandLogoCandidates = (brand) => {
  const normalized = normalizeBrandSlug(brand);
  if (!normalized) return [];

  const variants = Array.from(
    new Set([
      normalized,
      normalized.replace(/-/g, ""),
      normalized.replace(/-/g, "_"),
    ]),
  ).filter(Boolean);

  const logoBases = Array.from(
    new Set(
      [BRAND_LOGOS_BASE_URL, CORE_API_BASE_URL ? `${CORE_API_BASE_URL}/v1/assets/logo-brands` : ""]
        .map((entry) => String(entry || "").trim().replace(/\/+$/, ""))
        .filter(Boolean),
    ),
  );

  const candidates = [];
  for (const base of logoBases) {
    for (const slug of variants) {
      candidates.push(`${base}/logo_${slug}.png`);
    }
  }
  return candidates;
};

export function BrandLogoBadge({ brand, className = "brand-logo-badge" }) {
  const logoCandidates = useMemo(() => buildBrandLogoCandidates(brand), [brand]);
  const [candidateIndex, setCandidateIndex] = useState(0);

  useEffect(() => {
    setCandidateIndex(0);
  }, [brand]);

  const normalizedBrand = String(brand || "").trim();
  const hasCandidate = normalizedBrand.length > 0 && candidateIndex < logoCandidates.length;
  const imageSrc = hasCandidate ? logoCandidates[candidateIndex] : "";
  const fallbackText = normalizedBrand ? normalizedBrand.slice(0, 1).toUpperCase() : "ALL";

  return (
    <span className={className} aria-hidden="true">
      {hasCandidate ? (
        <img
          src={imageSrc}
          alt=""
          loading="lazy"
          decoding="async"
          onError={() => setCandidateIndex((current) => current + 1)}
        />
      ) : (
        <span>{fallbackText}</span>
      )}
    </span>
  );
}

function useTrayLayout(open, trayHeight) {
  const [menuLayout, setMenuLayout] = useState({ mode: "inline", style: undefined });
  const rootRef = useRef(null);
  const triggerRef = useRef(null);
  const menuRef = useRef(null);

  useEffect(() => {
    if (!open) {
      setMenuLayout({ mode: "inline", style: undefined });
      return undefined;
    }

    const updateMenuLayout = () => {
      const triggerRect = triggerRef.current?.getBoundingClientRect();
      if (!triggerRect) return;
      const chromeAppRect = document.querySelector(".chrome-app--desktop")?.getBoundingClientRect();

      const viewportWidth = window.innerWidth;
      const viewportHeight = window.innerHeight;
      const pageMargin = 24;
      const trayGap = 8;
      const trayTopBase = Math.round(triggerRect.bottom + trayGap);
      const trayLeft = Math.round(triggerRect.left);
      const trayRight = chromeAppRect
        ? Math.round(chromeAppRect.right - 16)
        : Math.round(viewportWidth - pageMargin);
      const trayWidth = Math.max(0, trayRight - trayLeft);
      const canUseTray = viewportWidth >= 980 && trayWidth >= 320;

      if (!canUseTray) {
        setMenuLayout({ mode: "inline", style: undefined });
        return;
      }

      const resolvedTrayHeight = Math.min(trayHeight, Math.max(196, viewportHeight - trayTopBase - pageMargin));
      const top = Math.max(
        pageMargin,
        Math.min(trayTopBase, viewportHeight - resolvedTrayHeight - pageMargin),
      );

      setMenuLayout({
        mode: "tray",
        style: {
          top: `${top}px`,
          left: `${trayLeft}px`,
          width: `${trayWidth}px`,
          maxHeight: `${resolvedTrayHeight}px`,
        },
      });
    };

    const frameId = window.requestAnimationFrame(updateMenuLayout);
    window.addEventListener("resize", updateMenuLayout);
    window.addEventListener("scroll", updateMenuLayout, true);
    return () => {
      window.cancelAnimationFrame(frameId);
      window.removeEventListener("resize", updateMenuLayout);
      window.removeEventListener("scroll", updateMenuLayout, true);
    };
  }, [open, trayHeight]);

  const handleMenuWheel = (event) => {
    if (!menuRef.current) return;
    if (Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
    event.preventDefault();
    menuRef.current.scrollLeft += event.deltaY;
  };

  return {
    menuLayout,
    rootRef,
    triggerRef,
    menuRef,
    handleMenuWheel,
  };
}

function BrandSelect({ value, options, onChange, selectedVehicleCategory }) {
  const { t, locale } = useChromeI18n();
  const [open, setOpen] = useState(false);
  const { menuLayout, rootRef, triggerRef, menuRef, handleMenuWheel } = useTrayLayout(open, 228);
  const selectedValue = String(value || "");

  useEffect(() => {
    if (!open) return undefined;

    const onPointerDown = (event) => {
      if (rootRef.current?.contains(event.target) || menuRef.current?.contains(event.target)) return;
      setOpen(false);
    };
    const onKeyDown = (event) => {
      if (event.key === "Escape") setOpen(false);
    };

    window.addEventListener("mousedown", onPointerDown);
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("mousedown", onPointerDown);
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [open, rootRef, menuRef]);

  const resolveCategoryBadges = (vehicleCategoryIds) => {
    const normalizedIds = Array.isArray(vehicleCategoryIds) ? vehicleCategoryIds.filter(Boolean) : [];
    if (!normalizedIds.length) return [];

    if (selectedVehicleCategory) {
      const selectedMeta = getMapVehicleCategoryMeta(selectedVehicleCategory, locale);
      return selectedMeta ? [selectedMeta.label] : [];
    }

    const labels = normalizedIds
      .map((entry) => getMapVehicleCategoryMeta(entry, locale)?.label || "")
      .filter(Boolean);

    if (!labels.length) return [];
    if (labels.length === 1) return labels;
    return [`${labels[0]} +${labels.length - 1}`];
  };

  const menuNode = open ? (
    <div
      ref={menuRef}
      className={`brand-select__menu brand-select__menu--${menuLayout.mode}`}
      role="listbox"
      aria-label="Marca"
      style={menuLayout.style}
      onWheel={handleMenuWheel}
    >
      <button
        type="button"
        className={`brand-select__option ${!selectedValue ? "is-active" : ""}`}
        aria-label="Todas las marcas"
        title="Todas las marcas"
        onClick={() => {
          onChange("");
          setOpen(false);
        }}
      >
        <BrandLogoBadge brand="" className="brand-select__image" />
        {!selectedVehicleCategory ? (
          <span className="brand-select__category-badges">
            <span className="brand-select__category-tag">Todas</span>
          </span>
        ) : null}
        <span className="sr-only">Todas las marcas</span>
      </button>

      {options.map((entry) => (
        <button
          key={entry.value}
          type="button"
          className={`brand-select__option ${selectedValue === entry.value ? "is-active" : ""}`}
          aria-label={entry.value}
          title={entry.value}
          onClick={() => {
            onChange(entry.value);
            setOpen(false);
          }}
        >
          <BrandLogoBadge brand={entry.value} className="brand-select__image" />
          {resolveCategoryBadges(entry.vehicleCategoryIds).length ? (
            <span className="brand-select__category-badges">
              {resolveCategoryBadges(entry.vehicleCategoryIds).map((tag) => (
                <span key={`${entry.value}-${tag}`} className="brand-select__category-tag">
                  {tag}
                </span>
              ))}
            </span>
          ) : null}
          <span className="sr-only">{entry.value}</span>
        </button>
      ))}
    </div>
  ) : null;

  return (
    <div className={`brand-select ${open ? "is-open" : ""}`} ref={rootRef}>
      <button
        type="button"
        ref={triggerRef}
        className="brand-select__trigger"
        aria-haspopup="listbox"
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
      >
        <span className="brand-select__selected">
          <BrandLogoBadge brand={selectedValue} className="brand-logo-badge brand-logo-badge--sm" />
          <span className="brand-select__label">{selectedValue || t("map.selectBrand", "Seleccionar marca")}</span>
        </span>
        <span className="brand-select__chevron" aria-hidden="true" />
      </button>

      {open && menuLayout.mode === "inline" ? menuNode : null}
      {open && menuLayout.mode === "tray" && typeof document !== "undefined"
        ? createPortal(menuNode, document.body)
        : null}
    </div>
  );
}

