function countSwapistaSelections(filters) {
  return SWAPISTA_FIELD_DEFS.reduce((count, field) => {
    const rawValue = filters?.[field.id];
    if (field.selectionMode === "single") {
      return count + (String(rawValue || "").trim() ? 1 : 0);
    }

    return count + (Array.isArray(rawValue) ? rawValue.filter(Boolean).length : 0);
  }, 0);
}

