const OPTION_BY_FIELD_AND_VALUE = new Map();
const OPTION_ALIAS_BY_FIELD = new Map();

for (const field of SWAPISTA_FIELD_DEFS) {
  const optionByValue = new Map();
  const aliasMap = new Map();

  for (const option of field.options) {
    optionByValue.set(option.value, option);
    aliasMap.set(normalizeText(option.value), option.value);
    aliasMap.set(normalizeText(option.label), option.value);
    for (const alias of option.aliases || []) {
      aliasMap.set(normalizeText(alias), option.value);
    }
  }

  OPTION_BY_FIELD_AND_VALUE.set(field.id, optionByValue);
  OPTION_ALIAS_BY_FIELD.set(field.id, aliasMap);
}

const toRawFieldValues = (value) => {
  if (Array.isArray(value)) {
    return value.map((entry) => String(entry || "").trim()).filter(Boolean);
  }
  if (typeof value === "string") {
    return value
      .split(",")
      .map((entry) => entry.trim())
      .filter(Boolean);
  }
  return [];
};

const toRawSingleFieldValue = (value) => {
  if (typeof value === "string") return value.trim();
  if (Array.isArray(value)) return String(value[0] || "").trim();
  return "";
};

const normalizeFieldEntry = (field, rawValue) => {
  const trimmed = String(rawValue || "").trim();
  if (!trimmed) return "";

  const aliasMap = OPTION_ALIAS_BY_FIELD.get(field.id) || new Map();
  const matched = aliasMap.get(normalizeText(trimmed));
  if (matched) return matched;

  if (field.customValueStrategy === "text") return normalizeTextValue(trimmed);
  return normalizeSlug(trimmed);
};

export function isSwapistaTribe(value) {
  return String(value || "").trim().toLowerCase() === "swapistas";
}

export function createEmptySwapistaFilters() {
  return SWAPISTA_FIELD_DEFS.reduce((accumulator, field) => {
    accumulator[field.id] = field.selectionMode === "single" ? "" : [];
    return accumulator;
  }, {});
}

export function normalizeSwapistaFieldState(fieldId, value) {
  const field = SWAPISTA_FIELD_BY_ID.get(fieldId);
  if (!field) return value;

  if (field.selectionMode === "single") {
    return normalizeFieldEntry(field, value);
  }

  return uniqueValues(toRawFieldValues(value).map((entry) => normalizeFieldEntry(field, entry)).filter(Boolean));
}

export function readSwapistaState(metadataInput = {}) {
  const metadata = metadataInput && typeof metadataInput === "object" ? metadataInput : {};
  const next = createEmptySwapistaFilters();

  for (const field of SWAPISTA_FIELD_DEFS) {
    const rawValues = field.metadataKeys.flatMap((metadataKey) => {
      const rawValue = metadata[metadataKey];
      if (field.selectionMode === "single") return [toRawSingleFieldValue(rawValue)];
      return toRawFieldValues(rawValue);
    });

    if (field.selectionMode === "single") {
      next[field.id] = normalizeFieldEntry(field, rawValues.find(Boolean) || "");
      continue;
    }

    next[field.id] = uniqueValues(rawValues.map((entry) => normalizeFieldEntry(field, entry)).filter(Boolean));
  }

  return next;
}

export function clearSwapistaMetadata(metadata) {
  const next = { ...(metadata || {}) };
  for (const field of SWAPISTA_FIELD_DEFS) {
    for (const metadataKey of field.metadataKeys) {
      delete next[metadataKey];
    }
  }
  return next;
}

export function applySwapistaStateToMetadata(metadata, draftState) {
  let next = clearSwapistaMetadata(metadata);

  for (const field of SWAPISTA_FIELD_DEFS) {
    const metadataKey = field.metadataKeys[0];
    const normalizedValue = normalizeSwapistaFieldState(field.id, draftState?.[field.id]);

    if (field.selectionMode === "single") {
      if (normalizedValue) next[metadataKey] = normalizedValue;
      continue;
    }

    if (normalizedValue.length) next[metadataKey] = normalizedValue;
  }

  return next;
}

export function getSwapistaValueLabel(fieldId, value) {
  const normalizedValue = String(value || "").trim();
  if (!normalizedValue) return "";

  const optionMap = OPTION_BY_FIELD_AND_VALUE.get(fieldId);
  const option = optionMap?.get(normalizedValue);
  if (option) return option.label;

  const field = SWAPISTA_FIELD_BY_ID.get(fieldId);
  if (!field) return normalizedValue;
  if (field.customValueStrategy === "slug") return humanizeSlug(normalizedValue);
  return normalizedValue;
}

export function getSwapistaFieldOptions(fieldId, extraValues = []) {
  const field = SWAPISTA_FIELD_BY_ID.get(fieldId);
  if (!field) return [];

  const existingValues = new Set(field.options.map((entry) => normalizeText(entry.value)));
  const customOptions = uniqueValues(
    extraValues.map((entry) => normalizeSwapistaFieldState(fieldId, entry)).flat().filter(Boolean),
  )
    .filter((entry) => !existingValues.has(normalizeText(entry)))
    .map((entry) => ({
      value: entry,
      label: getSwapistaValueLabel(fieldId, entry),
    }));

  return [...field.options, ...customOptions];
}
