import React, { useEffect, useMemo, useState } from "react";
import {
  isFirebaseAuthConfigured,
  refreshFirebaseSession,
  registerWithFirebaseEmail,
  signInWithFirebaseEmail,
  signInWithFirebaseGoogle,
  signOutFirebaseSession,
} from "../../lib/firebaseAuth.js";
import { useChromeI18n } from "../../shared/i18n/i18n.jsx";

function getPermissionSummary(session) {
  const permissions = Array.isArray(session.me?.authz?.permissions) ? session.me.authz.permissions : [];
  if (permissions.includes("*")) return "super admin";
  if (permissions.length > 0) return permissions.slice(0, 3).join(", ");
  return "sin permisos especiales";
}

export function AuthSessionCard({ session }) {
  const { t } = useChromeI18n();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busyAction, setBusyAction] = useState("");
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  const firebaseReady = isFirebaseAuthConfigured();
  const usingFirebaseSession = session.authMode === "firebase-id-token";
  const usingDevBypass = session.authMode === "dev-bypass";
  const permissionSummary = useMemo(() => {
    const summary = getPermissionSummary(session);
    if (summary === "super admin") return t("common.superAdmin", "super admin");
    if (summary === "sin permisos especiales") {
      return t("common.specialPermissionsNone", "sin permisos especiales");
    }
    return summary;
  }, [session, t]);

  useEffect(() => {
    if (!email && session.subject?.email) {
      setEmail(session.subject.email);
    }
  }, [email, session.subject?.email]);

  const runAction = async (actionName, action) => {
    setBusyAction(actionName);
    setError("");
    setMessage("");
    try {
      await action();
      setPassword("");
      setMessage(
        actionName === "logout"
          ? t("auth.loggedOut", "Sesion cerrada.")
          : actionName === "refresh"
            ? t("auth.tokenUpdated", "Token actualizado.")
            : t("auth.firebaseUpdated", "Sesion Firebase actualizada."),
      );
      session.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : t("auth.actionFailed", "No se pudo completar la accion."));
    } finally {
      setBusyAction("");
    }
  };

  if (!firebaseReady) {
    return (
      <section className="panel-card auth-session-card">
        <header className="panel-card__header">
          <div>
            <p className="panel-card__eyebrow">Auth</p>
            <h3 className="panel-card__title">{t("common.firebasePending", "Firebase pendiente")}</h3>
          </div>
        </header>

        <div className="auth-session-card__stack">
          <p className="auth-session-card__copy">
            {t(
              "auth.firebasePendingCopy",
              "Falta configurar `VITE_FIREBASE_API_KEY`, `VITE_FIREBASE_AUTH_DOMAIN`, `VITE_FIREBASE_PROJECT_ID` y `VITE_FIREBASE_APP_ID` en `beterano-app-chrome`.",
            )}
          </p>
          {usingDevBypass ? (
            <div className="auth-session-card__notice">
              {t(
                "auth.devBypassNotice",
                "El shell esta entrando por `VITE_DEV_AUTH_EMAIL`. Quita ese valor para probar auth real.",
              )}
            </div>
          ) : null}
        </div>
      </section>
    );
  }

  return (
    <section className="panel-card auth-session-card">
      <header className="panel-card__header">
        <div>
          <p className="panel-card__eyebrow">Auth</p>
          <h3 className="panel-card__title">{t("common.firebaseSession", "Firebase session")}</h3>
        </div>
      </header>

      <div className="auth-session-card__stack">
        {usingFirebaseSession ? (
          <>
            <div className="auth-session-card__summary">
              <div>
                <span>{t("common.provider", "Proveedor")}</span>
                <strong>Firebase Auth</strong>
              </div>
              <div>
                <span>{t("common.permissions", "Permisos")}</span>
                <strong>{permissionSummary}</strong>
              </div>
            </div>

            <div className="auth-session-card__actions">
              <button
                type="button"
                className="ghost-btn"
                onClick={() => runAction("refresh", () => refreshFirebaseSession())}
                disabled={busyAction.length > 0}
              >
                {busyAction === "refresh"
                  ? t("auth.refreshing", "Actualizando...")
                  : t("common.refreshToken", "Refrescar token")}
              </button>
              <button
                type="button"
                className="ghost-btn"
                onClick={() => runAction("logout", () => signOutFirebaseSession())}
                disabled={busyAction.length > 0}
              >
                {busyAction === "logout" ? t("auth.signingOut", "Saliendo...") : t("common.logout", "Cerrar sesion")}
              </button>
            </div>
          </>
        ) : (
          <>
            <p className="auth-session-card__copy">
              {t(
                "auth.firebaseSessionCopy",
                "Inicia sesion o crea cuenta con Firebase para que el shell reciba un `idToken` real.",
              )}
            </p>

            <label className="profile-settings__field">
              <span>{t("common.email", "Email")}</span>
              <input
                type="email"
                autoComplete="email"
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                placeholder="usuario@beterano.test"
              />
            </label>

            <label className="profile-settings__field">
              <span>{t("common.password", "Password")}</span>
              <input
                type="password"
                autoComplete="current-password"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                placeholder={t("auth.minPassword", "Minimo 6 caracteres")}
              />
            </label>

            <div className="auth-session-card__actions">
              <button
                type="button"
                className="ghost-btn"
                onClick={() => runAction("login", () => signInWithFirebaseEmail(email, password))}
                disabled={busyAction.length > 0 || !email.trim() || password.length < 6}
              >
                {busyAction === "login" ? t("auth.loggingIn", "Entrando...") : t("common.enter", "Entrar")}
              </button>
              <button
                type="button"
                className="ghost-btn"
                onClick={() => runAction("signup", () => registerWithFirebaseEmail(email, password))}
                disabled={busyAction.length > 0 || !email.trim() || password.length < 6}
              >
                {busyAction === "signup"
                  ? t("auth.creating", "Creando...")
                  : t("common.createAccount", "Crear cuenta")}
              </button>
              <button
                type="button"
                className="ghost-btn"
                onClick={() => runAction("google", () => signInWithFirebaseGoogle())}
                disabled={busyAction.length > 0}
              >
                {busyAction === "google" ? t("auth.opening", "Abriendo...") : t("common.google", "Google")}
              </button>
            </div>

            {usingDevBypass ? (
              <div className="auth-session-card__notice">
                {t(
                  "auth.devBypassStillActive",
                  "`VITE_DEV_AUTH_EMAIL` sigue activo. Si sales de Firebase, el shell volvera al bypass dev.",
                )}
              </div>
            ) : null}
          </>
        )}

        {message ? <div className="auth-session-card__success">{message}</div> : null}
        {error ? <div className="auth-session-card__error">{error}</div> : null}
      </div>
    </section>
  );
}
