export function safeUrl(input) {
  try {
    return new URL(input);
  } catch {
    return null;
  }
}

export function buildEmbeddedRemoteUrl(section, options = {}) {
  const parsed = safeUrl(section?.remoteUrl || "");
  if (!parsed) return "about:blank";

  // Some remotes (like calendar) are served under a public base path (e.g. /calendar/).
  // `trimSlash()` in section config removes the trailing slash, which breaks Vite's base handling.
  if (parsed.pathname !== "/" && !parsed.pathname.endsWith("/")) {
    parsed.pathname = `${parsed.pathname}/`;
  }

  parsed.searchParams.set("embedded", "1");
  parsed.searchParams.set("shell", "beterano-app-chrome");
  parsed.searchParams.set("theme", "beterano-lab");
  parsed.searchParams.set("viewport", options.viewport === "mobile" ? "mobile" : "desktop");

  if (options.sectionId) parsed.searchParams.set("hostSection", options.sectionId);
  if (options.locale) parsed.searchParams.set("lang", String(options.locale).slice(0, 2).toLowerCase());
  if (options.searchText && section?.id === "map") parsed.searchParams.set("q", String(options.searchText));
  if (options.slot) parsed.searchParams.set("slot", String(options.slot));

  return parsed.toString();
}
