import { matchShopCategory } from "../features/mapShell/shopCategories.js";
import { readSwapistaState } from "../features/mapShell/swapistas.js";
import { normalizeMapTribeId } from "../features/mapShell/tribes.js";
import { matchVehicleCategory } from "../features/mapShell/vehicleCategories.js";
import { fetchCoreJson } from "./coreApi.js";

function toObject(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return value;
}

function toStringArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) {
    return value.map((entry) => String(entry || "").trim()).filter(Boolean);
  }
  if (typeof value === "string") {
    return value
      .split(",")
      .map((entry) => entry.trim())
      .filter(Boolean);
  }
  return [];
}

function uniqueStrings(values) {
  const seen = new Set();
  const output = [];

  for (const value of values) {
    const normalized = String(value || "").trim();
    if (!normalized) continue;
    const key = normalized.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    output.push(normalized);
  }

  return output;
}

function firstStringValue(values) {
  for (const value of values) {
    const normalized = String(value || "").trim();
    if (normalized) return normalized;
  }
  return "";
}

function toFiniteNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function readBoolean(value) {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") {
    if (value === 1) return true;
    if (value === 0) return false;
    return null;
  }
  if (typeof value !== "string") return null;
  const normalized = value.trim().toLowerCase();
  if (!normalized) return null;
  if (["1", "true", "yes", "si", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  return null;
}

export function normalizeMapShellItem(item, index = 0) {
  const point = item?.location?.point;
  if (!point || !Number.isFinite(point.lat) || !Number.isFinite(point.lng)) return null;

  const metadataInput = toObject(item?.metadata);
  const tagsInput = toObject(item?.tags);
  const marketplaceInput = toObject(item?.marketplace);
  const normalizedTribe = normalizeMapTribeId(item?.tribe) || "restauradores";
  const categories = uniqueStrings([
    ...toStringArray(tagsInput.categories),
    ...toStringArray(tagsInput.category),
    ...toStringArray(metadataInput.categories),
    ...toStringArray(metadataInput.category),
    ...toStringArray(tagsInput.vehicleCategories),
    ...toStringArray(tagsInput.vehicleCategory),
    ...toStringArray(metadataInput.vehicleCategories),
    ...toStringArray(metadataInput.vehicleCategory),
    ...toStringArray(tagsInput.types),
  ]);
  const professions = uniqueStrings([
    ...toStringArray(tagsInput.professions),
    ...toStringArray(tagsInput.profession),
    ...toStringArray(metadataInput.professions),
    ...toStringArray(metadataInput.profession),
  ]);
  const services = uniqueStrings([
    ...toStringArray(tagsInput.services),
    ...toStringArray(metadataInput.services),
    ...professions,
  ]);
  const rawShopCategories = uniqueStrings([
    ...toStringArray(tagsInput.shopCategories),
    ...toStringArray(tagsInput.shopCategory),
    ...toStringArray(metadataInput.shopCategories),
    ...toStringArray(metadataInput.shopCategory),
  ]);
  const shopCategoryIds = uniqueStrings(
    [...rawShopCategories, ...categories, ...services].map((entry) => matchShopCategory(entry)).filter(Boolean),
  );
  const swapistaState = readSwapistaState(metadataInput);
  const shortDescription = firstStringValue([
    item?.shortDescription,
    metadataInput.shortDescription,
    metadataInput.short_description,
    item?.description,
  ]);
  const longDescription = firstStringValue([
    item?.longDescription,
    metadataInput.longDescription,
    metadataInput.long_description,
    item?.description,
  ]);

  return {
    id: String(item?.id || item?.slug || `${item?.name || "place"}-${index}`),
    slug: item?.slug || "",
    source: item?.source || "USER_SUBMISSION",
    ownerUserId: item?.ownerUserId || null,
    name: item?.name || "Sin nombre",
    tribe: normalizedTribe,
    city: item?.city || "",
    country: item?.country || "",
    countryCode: item?.countryCode || "",
    region: firstStringValue([item?.region, metadataInput.region, metadataInput.state, metadataInput.province]),
    address: firstStringValue([item?.address, metadataInput.address]),
    postalCode: firstStringValue([
      item?.postalCode,
      metadataInput.postalCode,
      metadataInput.postal_code,
      metadataInput.zipCode,
      metadataInput.zip,
    ]),
    coverage: firstStringValue([item?.coverage, metadataInput.coverage, metadataInput.zonaCobertura]),
    contactName: firstStringValue([
      item?.contactName,
      metadataInput.contactName,
      metadataInput.contactoPrincipal,
    ]),
    description: shortDescription || longDescription || "",
    shortDescription,
    longDescription,
    published: item?.published !== false,
    metadata: metadataInput,
    logoUrl: firstStringValue([
      item?.logoUrl,
      item?.logo,
      item?.media?.logo,
      item?.media?.avatar,
      item?.company?.logo,
      item?.brand?.logo,
      item?.profile?.logo,
    ]),
    images: uniqueStrings([
      ...toStringArray(item?.media?.images),
      ...toStringArray(item?.images),
    ]),
    flags: {
      verified: item?.verified === true || readBoolean(metadataInput.verified) === true,
      featured: item?.featured === true || readBoolean(metadataInput.featured) === true,
    },
    tags: {
      categories,
      brands: uniqueStrings(toStringArray(tagsInput.brands)),
      models: uniqueStrings(toStringArray(tagsInput.models)),
      professions,
      services,
      shopCategories: rawShopCategories,
      swapCategories: swapistaState.swapCategories,
      swapTypes: swapistaState.swapTypes,
      vehicleTypes: swapistaState.vehicleTypes,
      vehicleUses: swapistaState.vehicleUses,
      workshopServices: swapistaState.workshopServices,
      electronics: swapistaState.electronics,
      fabricationProducts: swapistaState.fabricationProducts,
      workshopLevel: swapistaState.workshopLevel,
      vehiclePlatforms: swapistaState.vehiclePlatforms,
      engines: swapistaState.engines,
    },
    swapista: swapistaState,
    vehicleCategoryIds: uniqueStrings(categories.map((entry) => matchVehicleCategory(entry)).filter(Boolean)),
    shopCategoryIds,
    location: {
      point: { lat: Number(point.lat), lng: Number(point.lng) },
      precision: item?.location?.precision || "point",
      bufferKm: toFiniteNumber(item?.location?.bufferKm),
    },
    links: {
      website: item?.links?.website || "",
      instagram: item?.links?.instagram || "",
      facebook: item?.links?.facebook || "",
      youtube: item?.links?.youtube || "",
      linkedin: item?.links?.linkedin || "",
      tiktok: item?.links?.tiktok || "",
      whatsapp: item?.links?.whatsapp || "",
      email: item?.links?.email || "",
      phone: item?.links?.phone || "",
    },
    marketplace: {
      hasProducts: Boolean(
        marketplaceInput.hasProducts === true ||
          (Number.isFinite(Number(marketplaceInput.productCount)) &&
            Number(marketplaceInput.productCount) > 0) ||
          String(marketplaceInput.url || "").trim(),
      ),
      productCount: toFiniteNumber(marketplaceInput.productCount ?? marketplaceInput.productsCount),
      url: firstStringValue([marketplaceInput.url, marketplaceInput.marketplaceUrl]),
      shopId: firstStringValue([marketplaceInput.shopId, marketplaceInput.id]),
      shopSlug: firstStringValue([marketplaceInput.shopSlug, marketplaceInput.slug]),
    },
    createdAt: item?.createdAt || null,
    updatedAt: item?.updatedAt || null,
  };
}

export async function fetchMapPlaces(query = {}, options = {}) {
  const payload = await fetchCoreJson("/v1/motors/map/places", query, options);
  const items = (Array.isArray(payload?.items) ? payload.items : [])
    .map((item, index) => normalizeMapShellItem(item, index))
    .filter(Boolean);
  return {
    items,
    meta: payload?.meta || { count: items.length },
  };
}

export async function fetchMapPlaceDetail(placeId, options = {}) {
  const payload = await fetchCoreJson(`/v1/motors/map/places/${encodeURIComponent(placeId)}`, {}, options);
  return normalizeMapShellItem(payload?.item, 0);
}

export async function createMapPlace(input, options = {}) {
  const payload = await fetchCoreJson("/v1/motors/map/places", {}, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(input),
    ...options,
  });

  return {
    action: payload?.action || "created",
    item: normalizeMapShellItem(payload?.item, 0),
  };
}

export async function updateMapPlace(placeId, input, options = {}) {
  const payload = await fetchCoreJson(`/v1/motors/map/places/${encodeURIComponent(placeId)}`, {}, {
    method: "PATCH",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(input),
    ...options,
  });

  return normalizeMapShellItem(payload?.item, 0);
}

export async function deleteMapPlace(placeId, options = {}) {
  return fetchCoreJson(`/v1/motors/map/places/${encodeURIComponent(placeId)}`, {}, {
    method: "DELETE",
    ...options,
  });
}
