import React, { useMemo } from "react";

function uniqueTrimmedValues(values) {
  const seen = new Set();
  const output = [];

  for (const value of Array.isArray(values) ? values : []) {
    const normalized = String(value || "").trim();
    if (!normalized) continue;
    const key = normalized.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    output.push(normalized);
  }

  return output;
}

export function MapPlaceTagGroup({
  label,
  values,
  className = "",
  includeLabel = false,
  max = 4,
}) {
  const normalizedValues = useMemo(() => uniqueTrimmedValues(values), [values]);

  if (!normalizedValues.length) return null;

  const normalizedMax = Number.isFinite(Number(max)) ? Math.max(1, Number(max)) : normalizedValues.length;
  const visibleValues = normalizedValues.slice(0, normalizedMax);
  const hiddenCount = normalizedValues.length - visibleValues.length;
  const rootClass = className ? `map-tag-group ${className}` : "map-tag-group";

  return (
    <div className={rootClass} aria-label={label}>
      {includeLabel ? <span className="map-tag-group__label">{label}</span> : null}
      <div className="map-tag-group__list">
        {visibleValues.map((value, index) => (
          <span key={`${value.toLowerCase()}-${index}`} className="map-tag-chip">
            {value}
          </span>
        ))}
        {hiddenCount > 0 ? <span className="map-tag-chip map-tag-chip--muted">+{hiddenCount}</span> : null}
      </div>
    </div>
  );
}
