import React, { createContext, useContext, useEffect, useMemo } from "react";
import { CHROME_MESSAGES } from "./messages.js";

export const SUPPORTED_LOCALES = ["es", "en", "de", "fr", "it", "tr", "nl", "pl", "hr", "ja", "zh", "ar"];

export const LOCALE_OPTIONS = [
  { value: "es", label: "Español" },
  { value: "en", label: "English" },
  { value: "de", label: "Deutsch" },
  { value: "fr", label: "Français" },
  { value: "it", label: "Italiano" },
  { value: "tr", label: "Türkçe" },
  { value: "nl", label: "Nederlands" },
  { value: "pl", label: "Polski" },
  { value: "hr", label: "Hrvatski" },
  { value: "ja", label: "日本語" },
  { value: "zh", label: "中文" },
  { value: "ar", label: "العربية" },
];

const LOCALE_TAGS = {
  es: "es-ES",
  en: "en-US",
  de: "de-DE",
  fr: "fr-FR",
  it: "it-IT",
  tr: "tr-TR",
  nl: "nl-NL",
  pl: "pl-PL",
  hr: "hr-HR",
  ja: "ja-JP",
  zh: "zh-CN",
  ar: "ar",
};

const LANG_COOKIE_KEY = "btr_lang";
const LANG_COOKIE_MAX_AGE = 60 * 60 * 24 * 365;

function hasLocale(value) {
  return SUPPORTED_LOCALES.includes(value);
}

function getNestedValue(object, key) {
  return key.split(".").reduce((current, segment) => {
    if (current && typeof current === "object" && segment in current) return current[segment];
    return undefined;
  }, object);
}

export function normalizeLocale(value) {
  if (!value) return undefined;
  const normalized = String(value).trim().toLowerCase().replace(/_/g, "-");
  if (!normalized) return undefined;
  const base = normalized.split("-")[0];
  return hasLocale(base) ? base : undefined;
}

function readLocaleFromCookie() {
  if (typeof document === "undefined") return undefined;
  const cookie = document.cookie
    .split(";")
    .map((entry) => entry.trim())
    .find((entry) => entry.startsWith(`${LANG_COOKIE_KEY}=`));
  if (!cookie) return undefined;
  return normalizeLocale(decodeURIComponent(cookie.slice(LANG_COOKIE_KEY.length + 1)));
}

function readLocaleFromQuery() {
  if (typeof window === "undefined") return undefined;
  return normalizeLocale(new URLSearchParams(window.location.search).get("lang"));
}

export function resolveInitialLocale(fallback = "es") {
  if (typeof window === "undefined") return fallback;
  return (
    normalizeLocale(window.localStorage?.getItem("locale")) ||
    readLocaleFromQuery() ||
    readLocaleFromCookie() ||
    normalizeLocale(window.navigator.language) ||
    fallback
  );
}

export function getLocaleTag(locale) {
  return LOCALE_TAGS[normalizeLocale(locale) || "en"] || "en-US";
}

export function syncLocaleArtifacts(locale) {
  const normalized = normalizeLocale(locale) || "es";

  if (typeof window !== "undefined") {
    try {
      window.localStorage.setItem("locale", normalized);
    } catch {
      // noop
    }
  }

  if (typeof document !== "undefined") {
    document.cookie = `${LANG_COOKIE_KEY}=${encodeURIComponent(normalized)}; path=/; max-age=${LANG_COOKIE_MAX_AGE}; samesite=lax`;
    document.documentElement.lang = normalized;
    document.documentElement.dir = normalized === "ar" ? "rtl" : "ltr";
  }
}

const I18nContext = createContext({
  locale: "es",
  localeTag: "es-ES",
  t: (key, fallback) => fallback || key,
});

export function ChromeI18nProvider({ locale, children }) {
  const normalized = normalizeLocale(locale) || "es";

  useEffect(() => {
    syncLocaleArtifacts(normalized);
  }, [normalized]);

  const value = useMemo(
    () => ({
      locale: normalized,
      localeTag: getLocaleTag(normalized),
      t: (key, fallback = key) => {
        const current = getNestedValue(CHROME_MESSAGES[normalized], key);
        if (typeof current === "string") return current;
        const english = getNestedValue(CHROME_MESSAGES.en, key);
        if (typeof english === "string") return english;
        return fallback;
      },
    }),
    [normalized],
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useChromeI18n() {
  return useContext(I18nContext);
}
