import { useEffect, useMemo, useState } from "react";
import { AUTH_CACHE_UPDATED_EVENT, subscribeToFirebaseSession } from "../lib/firebaseAuth.js";
import {
  CORE_API_BASE_URL,
  HAS_CORE_API_BASE_URL,
  MISSING_CORE_API_MESSAGE,
} from "../lib/coreApiConfig.js";

const CORE_API_BASE = CORE_API_BASE_URL;
const DEV_AUTH_EMAIL = (import.meta.env.VITE_DEV_AUTH_EMAIL || "").trim();

function readLegacyCache() {
  if (typeof window === "undefined") return null;

  const tryParse = (raw) => {
    if (!raw) return null;
    try {
      return JSON.parse(raw);
    } catch {
      return null;
    }
  };

  const local = tryParse(window.localStorage?.getItem("btr_auth_cache_v1"));
  if (local) return local;

  const session = tryParse(window.sessionStorage?.getItem("btr_auth_cache_v1"));
  if (session) return session;

  if (window.__BTR_AUTH__ && typeof window.__BTR_AUTH__ === "object") return window.__BTR_AUTH__;
  return null;
}

function resolveIdToken(snapshot) {
  if (!snapshot || typeof snapshot !== "object") return "";
  if (typeof snapshot.idToken === "string" && snapshot.idToken.trim()) return snapshot.idToken.trim();
  if (typeof snapshot.token === "string" && snapshot.token.trim()) return snapshot.token.trim();
  return "";
}

export function useCoreSession() {
  const [refreshTick, setRefreshTick] = useState(0);
  const [state, setState] = useState({
    status: "loading",
    me: null,
    error: "",
    authMode: "none",
    updatedAt: null,
  });

  useEffect(() => {
    const controller = new AbortController();
    const snapshot = readLegacyCache();
    const idToken = resolveIdToken(snapshot);

    const headers = { Accept: "application/json" };
    let authMode = "none";

    if (idToken) {
      headers.Authorization = `Bearer ${idToken}`;
      authMode = "firebase-id-token";
    } else if (DEV_AUTH_EMAIL) {
      headers["x-dev-auth-email"] = DEV_AUTH_EMAIL;
      authMode = "dev-bypass";
    }

    async function load() {
      setState((prev) => ({ ...prev, status: "loading", error: "", authMode }));
      if (!HAS_CORE_API_BASE_URL) {
        setState({
          status: "error",
          me: null,
          error: MISSING_CORE_API_MESSAGE,
          authMode,
          updatedAt: Date.now(),
        });
        return;
      }

      try {
        const response = await fetch(`${CORE_API_BASE}/v1/me`, { headers, signal: controller.signal });
        const payload = await response.json().catch(() => null);

        if (!response.ok) {
          const message = payload?.error || `HTTP ${response.status}`;
          setState({
            status: response.status === 401 ? "anonymous" : "error",
            me: null,
            error: message,
            authMode,
            updatedAt: Date.now(),
          });
          return;
        }

        setState({
          status: "ready",
          me: payload,
          error: "",
          authMode,
          updatedAt: Date.now(),
        });
      } catch (error) {
        if (controller.signal.aborted) return;
        setState({
          status: "error",
          me: null,
          error: error instanceof Error ? error.message : "Unknown error",
          authMode,
          updatedAt: Date.now(),
        });
      }
    }

    load();
    return () => controller.abort();
  }, [refreshTick]);

  useEffect(() => {
    const onStorage = (event) => {
      if (event.key && event.key !== "btr_auth_cache_v1") return;
      setRefreshTick((value) => value + 1);
    };
    const onFocus = () => setRefreshTick((value) => value + 1);
    const onAuthCacheUpdated = () => setRefreshTick((value) => value + 1);
    window.addEventListener("storage", onStorage);
    window.addEventListener("focus", onFocus);
    window.addEventListener(AUTH_CACHE_UPDATED_EVENT, onAuthCacheUpdated);
    return () => {
      window.removeEventListener("storage", onStorage);
      window.removeEventListener("focus", onFocus);
      window.removeEventListener(AUTH_CACHE_UPDATED_EVENT, onAuthCacheUpdated);
    };
  }, []);

  useEffect(() => {
    const unsubscribe = subscribeToFirebaseSession(() => {
      setRefreshTick((value) => value + 1);
    });
    return () => unsubscribe?.();
  }, []);

  return useMemo(() => {
    const user = state.me?.user || null;
    const subject = state.me?.subject || null;
    return {
      ...state,
      user,
      subject,
      memberships: Array.isArray(user?.memberships) ? user.memberships : [],
      displayName: user?.displayName || user?.primaryEmail || subject?.email || "Invitado",
      refresh: () => setRefreshTick((value) => value + 1),
    };
  }, [state]);
}
