function resolveLocale(locale) {
  const normalized = String(locale || "es").trim().toLowerCase();
  return SHOP_CATEGORY_LABELS[normalized] ? normalized : "en";
}

function localizeShopCategory(entry, locale) {
  const labels = SHOP_CATEGORY_LABELS[resolveLocale(locale)] || SHOP_CATEGORY_LABELS.en;
  return {
    ...entry,
    label: labels[entry.id] || entry.label,
  };
}

export const MAP_SHOP_CATEGORIES = BASE_MAP_SHOP_CATEGORIES;
export const MAP_SHOP_CATEGORY_BY_ID = new Map(MAP_SHOP_CATEGORIES.map((entry) => [entry.id, entry]));

export const getMapShopCategories = (locale = "es") =>
  BASE_MAP_SHOP_CATEGORIES.map((entry) => localizeShopCategory(entry, locale));

export const getMapShopCategoryMeta = (categoryId, locale = "es") => {
  const entry = MAP_SHOP_CATEGORY_BY_ID.get(String(categoryId || "").trim());
  return entry ? localizeShopCategory(entry, locale) : null;
};

export const matchShopCategory = (rawValue) => {
  const normalizedRaw = normalizeText(rawValue);
  if (!normalizedRaw) return "";

  for (const category of MAP_SHOP_CATEGORIES) {
    const matched = [category.id, category.label, ...category.keywords].some((keyword) =>
      normalizedRaw.includes(normalizeText(keyword)),
    );
    if (matched) return category.id;
  }

  return "";
};
