import React, { useEffect, useRef, useState } from "react";
import { buildEmbeddedRemoteUrl, safeUrl } from "../lib/remoteUrl.js";
import { useChromeI18n } from "../shared/i18n/i18n.jsx";

const REMOTE_UNAVAILABLE_MESSAGES = {
  es: {
    title: "Modulo no disponible todavia.",
    copy: "{section} aparecera aqui cuando su frontend publico este listo.",
  },
  en: {
    title: "Module not available yet.",
    copy: "{section} will appear here when its public frontend is ready.",
  },
  de: {
    title: "Modul noch nicht verfuegbar.",
    copy: "{section} wird hier angezeigt, sobald das oeffentliche Frontend bereit ist.",
  },
  fr: {
    title: "Module pas encore disponible.",
    copy: "{section} apparaitra ici lorsque son frontend public sera pret.",
  },
  it: {
    title: "Modulo non ancora disponibile.",
    copy: "{section} apparira qui quando il frontend pubblico sara pronto.",
  },
  tr: {
    title: "Modul henuz kullanima acik degil.",
    copy: "{section} herkese acik on yuz hazir oldugunda burada gorunecek.",
  },
  nl: {
    title: "Module nog niet beschikbaar.",
    copy: "{section} verschijnt hier zodra de publieke frontend klaar is.",
  },
  pl: {
    title: "Modul nie jest jeszcze dostepny.",
    copy: "{section} pojawi sie tutaj, gdy publiczny frontend bedzie gotowy.",
  },
  hr: {
    title: "Modul jos nije dostupan.",
    copy: "{section} ce se ovdje prikazati kada javni frontend bude spreman.",
  },
  ja: {
    title: "このモジュールはまだ利用できません。",
    copy: "{section} の公開フロントエンドの準備ができると、ここに表示されます。",
  },
  zh: {
    title: "该模块暂未开放。",
    copy: "{section} 的公开前端准备好后，将显示在这里。",
  },
  ar: {
    title: "هذه الوحدة غير متاحة بعد.",
    copy: "سيظهر {section} هنا عندما تصبح الواجهة العامة جاهزة.",
  },
};

function tryParse(raw) {
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function readBridgeAuthToken() {
  if (typeof window === "undefined") return "";
  const snapshot =
    tryParse(window.localStorage?.getItem("btr_auth_cache_v1")) ||
    tryParse(window.sessionStorage?.getItem("btr_auth_cache_v1")) ||
    (window.__BTR_AUTH__ && typeof window.__BTR_AUTH__ === "object" ? window.__BTR_AUTH__ : null);

  if (!snapshot || typeof snapshot !== "object") return "";
  if (typeof snapshot.idToken === "string" && snapshot.idToken.trim()) return snapshot.idToken.trim();
  if (typeof snapshot.token === "string" && snapshot.token.trim()) return snapshot.token.trim();
  return "";
}

function resolveRemoteUnavailableCopy(locale, sectionLabel) {
  const normalizedLocale = typeof locale === "string" ? locale.slice(0, 2).toLowerCase() : "en";
  const dictionary = REMOTE_UNAVAILABLE_MESSAGES[normalizedLocale] || REMOTE_UNAVAILABLE_MESSAGES.en;
  return {
    title: dictionary.title,
    copy: dictionary.copy.replace("{section}", sectionLabel),
  };
}

function normalizePathname(pathname) {
  const normalized = String(pathname || "").replace(/\/+$/, "");
  return normalized || "/";
}

function isSelfReferentialRemoteUrl(sectionId, remoteUrl) {
  if (typeof window === "undefined") return false;
  const parsed = safeUrl(remoteUrl);
  if (!parsed) return false;

  let currentUrl;
  try {
    currentUrl = new URL(window.location.href);
  } catch {
    return false;
  }

  if (parsed.origin !== currentUrl.origin) return false;

  const remotePath = normalizePathname(parsed.pathname);
  const currentPath = normalizePathname(currentUrl.pathname);
  const sectionPath = normalizePathname(`/${sectionId}`);

  return (
    remotePath === currentPath ||
    remotePath === "/" ||
    remotePath === sectionPath
  );
}

export default function RemoteFrameHost({
  sections,
  activeSectionId,
  viewport,
  searchText,
  locale,
  session,
  remoteSectionState,
  slotBySection,
  dockCommand,
}) {
  const { t } = useChromeI18n();
  const [visitedSectionIds, setVisitedSectionIds] = useState([activeSectionId]);
  const [loadedById, setLoadedById] = useState({});
  const [readyById, setReadyById] = useState({});
  const [readyTimeoutById, setReadyTimeoutById] = useState({});
  const frameRefs = useRef({});
  const activeSection = sections.find((section) => section.id === activeSectionId) || null;

  useEffect(() => {
    setVisitedSectionIds((current) => (current.includes(activeSectionId) ? current : [...current, activeSectionId]));
  }, [activeSectionId]);

  useEffect(() => {
    const onMessage = (event) => {
      const payload = event.data;
      if (!payload || typeof payload !== "object" || payload.type !== "beterano-app-remote:ready") return;

      const sectionId = typeof payload.sectionId === "string" ? payload.sectionId : "";
      if (!sectionId) return;

      setReadyById((current) => ({ ...current, [sectionId]: true }));
      setReadyTimeoutById((current) => ({ ...current, [sectionId]: false }));
    };

    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, []);

  useEffect(() => {
    const frame = frameRefs.current[activeSectionId];
    if (!frame?.contentWindow) return;
    const bridgeToken = readBridgeAuthToken();

    try {
      frame.contentWindow.postMessage(
        {
          type: "beterano-app-chrome:state",
          searchText,
          locale,
          activeSectionId,
          viewport,
          auth: {
            status: session.status,
            subject: session.subject || null,
            user: session.user || null,
            token: bridgeToken || null,
          },
          remoteSectionState: remoteSectionState || {},
        },
        "*",
      );
    } catch {
      // noop
    }
  }, [
    activeSectionId,
    searchText,
    locale,
    viewport,
    session.status,
    session.subject,
    session.user,
    remoteSectionState,
  ]);

  // Reenvía los comandos del dock del shell (marketplace) al iframe activo.
  useEffect(() => {
    if (!dockCommand || !dockCommand.token || !dockCommand.id) return;
    const frame = frameRefs.current[activeSectionId];
    if (!frame?.contentWindow) return;
    try {
      frame.contentWindow.postMessage(
        { type: "beterano-app-chrome:dock", action: dockCommand.id },
        "*",
      );
    } catch {
      // noop
    }
  }, [dockCommand, activeSectionId]);

  useEffect(() => {
    if (!activeSection?.readySignal) return undefined;
    if (readyById[activeSection.id] === true) {
      setReadyTimeoutById((current) => ({ ...current, [activeSection.id]: false }));
      return undefined;
    }

    setReadyTimeoutById((current) => ({ ...current, [activeSection.id]: false }));
    const timeoutId = window.setTimeout(() => {
      setReadyTimeoutById((current) => ({ ...current, [activeSection.id]: true }));
    }, 3500);

    return () => window.clearTimeout(timeoutId);
  }, [activeSection?.id, activeSection?.readySignal, readyById]);

  const activeLoaded = loadedById[activeSectionId] === true;
  const activeReadyTimeout =
    Boolean(activeSection?.readySignal) &&
    readyTimeoutById[activeSectionId] === true &&
    readyById[activeSectionId] !== true;
  const activeRemoteUrl = activeSection?.remoteUrl || "";
  const activeRemoteUnavailable =
    Boolean(activeSection) &&
    (!activeRemoteUrl || isSelfReferentialRemoteUrl(activeSectionId, activeRemoteUrl));
  const activeUnavailableCopy = resolveRemoteUnavailableCopy(locale, activeSection?.label || activeSectionId);

  return (
    <div className="remote-stack">
      {!activeLoaded && !activeReadyTimeout && !activeRemoteUnavailable ? (
        <div className="remote-stack__loading" aria-live="polite">
          <div className="remote-stack__loading-card">
            <div className="spinner" />
            <p>{`${t("common.loading", "Cargando")} ${activeSectionId}...`}</p>
          </div>
        </div>
      ) : null}

      {activeRemoteUnavailable ? (
        <div className="remote-stack__loading" aria-live="polite">
          <div className="remote-stack__loading-card remote-stack__loading-card--error">
            <div className="remote-stack__error-copy">
              <strong>{activeUnavailableCopy.title}</strong>
              <p>{activeUnavailableCopy.copy}</p>
            </div>
          </div>
        </div>
      ) : null}

      {activeReadyTimeout ? (
        <div className="remote-stack__loading" aria-live="assertive">
          <div className="remote-stack__loading-card remote-stack__loading-card--error">
            <div className="remote-stack__error-copy">
              <strong>{activeSection?.label || activeSectionId} no ha respondido como remoto embebido.</strong>
              <p>
                Se esperaba cargar <code>{activeRemoteUrl}</code>. Si estas mezclando Motors con
                Beterano LAB, usa <code>npm run dev:all:lab-safe</code> o libera ese puerto para{" "}
                <code>{activeSection?.standaloneHint || activeSectionId}</code>.
              </p>
            </div>
          </div>
        </div>
      ) : null}

      {sections.map((section) => {
        if (!visitedSectionIds.includes(section.id)) return null;
        if (!section.remoteUrl) return null;
        const isActive = section.id === activeSectionId;
        const src = buildEmbeddedRemoteUrl(section, {
          viewport,
          searchText,
          locale,
          sectionId: section.id,
          slot: slotBySection?.[section.id],
        });

        return (
          <iframe
            key={section.id}
            ref={(node) => {
              if (node) frameRefs.current[section.id] = node;
            }}
            title={`${section.label} remote`}
            className={`remote-stack__frame ${isActive ? "" : "remote-stack__frame--hidden"}`}
            src={src}
            loading={isActive ? "eager" : "lazy"}
            allow="geolocation *"
            onLoad={() => setLoadedById((current) => ({ ...current, [section.id]: true }))}
          />
        );
      })}
    </div>
  );
}
